\begin{lemma}[K0prime Artinian]
\label{algebra-lemma-K0prime-Artinian}
\source{stacks:00JI}
\href{https://stacks.math.columbia.edu/tag/00JI}{\texttt{Stacks tag 00JI}}
\group{algebra}

\uses{algebra-lemma-length-K0}
Let $R$ be an Artinian local ring.
The map $\text{length}_R : K'_0(R) \to \mathbf{Z}$
of Lemma \ref{algebra-lemma-length-K0} is an isomorphism.
\end{lemma}

\begin{proof}
