\begin{lemma}[Grothendieck regular sequence general]
\label{algebra-lemma-grothendieck-regular-sequence-general}
\source{stacks:0470}
\href{https://stacks.math.columbia.edu/tag/0470}{\texttt{Stacks tag 0470}}
