\begin{proof}
\uses{algebra-lemma-etale-makes-quasi-finite-finite-variant, algebra-lemma-unramified-quasi-finite, algebra-lemma-unramified-at-prime, algebra-lemma-unique-prime-over-localize-below, algebra-lemma-integral-going-up, algebra-lemma-NAK}

