\section{Henselization and quasi-finite ring maps}
\label{algebra-section-henselization-quasi-finite}
In this section we prove some results concerning the functorial maps
between (strict) henselizations for quasi-finite ring maps.

\begin{lemma}[Quasi finite henselization]
\label{algebra-lemma-quasi-finite-henselization}
\source{stacks:05WP}
\href{https://stacks.math.columbia.edu/tag/05WP}{\texttt{Stacks tag 05WP}}
\group{algebra}

\uses{algebra-lemma-henselian-functorial}
Let $R \to S$ be a ring map.
Let $\mathfrak q$ be a prime of $S$ lying over $\mathfrak p$ in $R$.
Assume $R \to S$ is quasi-finite at $\mathfrak q$.
The commutative diagram
$$
\begin{array}{cc}R_{\mathfrak p}^h \longrightarrow & S_{\mathfrak q}^h \\ R_{\mathfrak p} \uparrow\longrightarrow & S_{\mathfrak q} \uparrow\end{array}
$$
of
Lemma \ref{algebra-lemma-henselian-functorial}
identifies $S_{\mathfrak q}^h$ with the localization of
$R_{\mathfrak p}^h \otimes_{R_{\mathfrak p}} S_{\mathfrak q}$
at the prime generated by $\mathfrak q$. Moreover, the ring
map $R_{\mathfrak p}^h \to S_{\mathfrak q}^h$ is finite.
\end{lemma}

\begin{proof}
\uses{algebra-lemma-four-rings, algebra-lemma-finite-over-henselian, algebra-lemma-henselian-functorial-improve, algebra-lemma-uniqueness-henselian}

Note that $R_{\mathfrak p}^h \otimes_R S$ is quasi-finite over
$R_{\mathfrak p}^h$ at the prime ideal corresponding to $\mathfrak q$, see
Lemma \ref{algebra-lemma-four-rings}. Hence the localization $S'$ of
$R_{\mathfrak p}^h \otimes_{R_{\mathfrak p}} S_{\mathfrak q}$ is henselian
and finite over $R_{\mathfrak p}^h$, see
Lemma \ref{algebra-lemma-finite-over-henselian}. As a localization $S'$ is a filtered
colimit of \'etale
$R_{\mathfrak p}^h \otimes_{R_{\mathfrak p}} S_{\mathfrak q}$-algebras.
By Lemma \ref{algebra-lemma-henselian-functorial-improve} we see that
$S_\mathfrak q^h$ is the henselization of
$R_{\mathfrak p}^h \otimes_{R_{\mathfrak p}} S_{\mathfrak q}$.
Thus $S' = S_\mathfrak q^h$ by the uniqueness
result of Lemma \ref{algebra-lemma-uniqueness-henselian}.
\end{proof}

