\begin{lemma}[Formally smooth extensions easy]
\label{algebra-lemma-formally-smooth-extensions-easy}
\source{stacks:0320}
\href{https://stacks.math.columbia.edu/tag/0320}{\texttt{Stacks tag 0320}}
\group{algebra}

Let $K/k$ be an extension of fields.
\begin{enumerate}
\item If $K$ is purely transcendental over $k$, then
$K$ is formally smooth over $k$.
\item If $K$ is separable algebraic over $k$, then $K$ is
formally smooth over $k$.
\item If $K$ is separable over $k$, then $K$ is formally smooth
over $k$.
\end{enumerate}
\end{lemma}

\begin{proof}
\uses{algebra-lemma-formally-etale-etale, algebra-lemma-colimit-formally-etale, algebra-definition-separable-field-extension, algebra-lemma-compose-formally-smooth, algebra-lemma-characterize-formally-smooth-field-extension, algebra-lemma-colimits-NL}

For (1) write $K = k(x_j; j \in J)$. Suppose that
$A$ is a $k$-algebra, and $I \subset A$ is an ideal of
square zero. Let $\varphi : K \to A/I$ be a $k$-algebra map.
Let $a_j \in A$ be an element such that $a_j \mod I = \varphi(x_j)$.
Then it is easy to see that there is a unique $k$-algebra
map $K \to A$ which maps $x_j$ to $a_j$ and which reduces
to $\varphi$ mod $I$. Hence $k \subset K$ is formally smooth.

\medskip\noindent
In case (2) we see that $k \subset K$ is a colimit of
\'etale ring extensions. An \'etale ring map is formally \'etale
(Lemma \ref{algebra-lemma-formally-etale-etale}). Hence this case follows from
Lemma \ref{algebra-lemma-colimit-formally-etale} and the trivial observation
that a formally \'etale ring map is formally smooth.

\medskip\noindent
In case (3), write $K = \colim K_i$ as the filtered colimit of its
finitely generated sub $k$-extensions. By
Definition \ref{algebra-definition-separable-field-extension}
each $K_i$ is separable algebraic over a purely transcendental
extension of $k$. Hence $K_i/k$ is formally smooth by cases (1) and (2) and
Lemma \ref{algebra-lemma-compose-formally-smooth}. Thus
$H_1(L_{K_i/k}) = 0$ by
Lemma \ref{algebra-lemma-characterize-formally-smooth-field-extension}.
Hence $H_1(L_{K/k}) = 0$ by Lemma \ref{algebra-lemma-colimits-NL}.
Hence $K/k$ is formally smooth by
Lemma \ref{algebra-lemma-characterize-formally-smooth-field-extension} again.
\end{proof}

\begin{lemma}[Formally smooth equals separable for field extensions.]
\label{algebra-lemma-fields-are-formally-smooth}
\source{stacks:0321}
\href{https://stacks.math.columbia.edu/tag/0321}{\texttt{Stacks tag 0321}}
\group{algebra}


Let $k$ be a field.
\begin{enumerate}
\item If the characteristic of $k$ is zero, then any extension field
of $k$ is formally smooth over $k$.
\item If the characteristic of $k$ is $p > 0$, then $K/k$ is
formally smooth if and only if it is a separable field extension.
\end{enumerate}
\end{lemma}

\begin{proof}
\uses{algebra-lemma-formally-smooth-implies-separable, algebra-lemma-formally-smooth-extensions-easy}

Combine Lemmas \ref{algebra-lemma-formally-smooth-implies-separable} and
\ref{algebra-lemma-formally-smooth-extensions-easy}.
\end{proof}

Here we put together all the different characterizations of separable
field extensions.

\begin{proposition}[Characterize separable field extensions]
\label{algebra-proposition-characterize-separable-field-extensions}
\source{stacks:0322}
\href{https://stacks.math.columbia.edu/tag/0322}{\texttt{Stacks tag 0322}}
\group{algebra}

Let $K/k$ be a field extension.
If the characteristic of $k$ is zero then
\begin{enumerate}
\item $K$ is separable over $k$,
\item $K$ is geometrically reduced over $k$,
\item $K$ is formally smooth over $k$,
\item $H_1(L_{K/k}) = 0$, and
\item the map $K \otimes_k \Omega_{k/\mathbf{Z}} \to \Omega_{K/\mathbf{Z}}$
is injective.
\end{enumerate}
If the characteristic of $k$ is $p > 0$, then the following are
equivalent:
\begin{enumerate}
\item $K$ is separable over $k$,
\item the ring $K \otimes_k k^{1/p}$ is reduced,
\item $K$ is geometrically reduced over $k$,
\item the map $K \otimes_k \Omega_{k/\mathbf{F}_p} \to \Omega_{K/\mathbf{F}_p}$
is injective,
\item $H_1(L_{K/k}) = 0$, and
\item $K$ is formally smooth over $k$.
\end{enumerate}
\end{proposition}

\begin{proof}
\uses{algebra-lemma-characterize-separable-field-extensions, algebra-lemma-fields-are-formally-smooth, algebra-lemma-formally-smooth-implies-separable, algebra-lemma-separable-differentials}

This is a combination of
Lemmas \ref{algebra-lemma-characterize-separable-field-extensions},
\ref{algebra-lemma-fields-are-formally-smooth}
\ref{algebra-lemma-formally-smooth-implies-separable}, and
\ref{algebra-lemma-separable-differentials}.
\end{proof}

Here is yet another characterization of finitely generated separable field
