\begin{lemma}[CM goes up]
\label{algebra-lemma-CM-goes-up}
\source{stacks:045J}
\href{https://stacks.math.columbia.edu/tag/045J}{\texttt{Stacks tag 045J}}
\group{algebra}

Let $R \to S$ be a flat local homomorphism of local Noetherian rings.
Then the following are equivalent
\begin{enumerate}
\item $S$ is Cohen-Macaulay, and
\item $R$ and $S/\mathfrak m_RS$ are Cohen-Macaulay.
\end{enumerate}
\end{lemma}

\begin{proof}
\uses{algebra-lemma-apply-grothendieck, algebra-lemma-dimension-base-fibre-equals-total}

Follows from the definitions and
Lemmas \ref{algebra-lemma-apply-grothendieck} and
\ref{algebra-lemma-dimension-base-fibre-equals-total}.
\end{proof}

\begin{lemma}[Sk goes up]
\label{algebra-lemma-Sk-goes-up}
\source{stacks:0339}
\href{https://stacks.math.columbia.edu/tag/0339}{\texttt{Stacks tag 0339}}
\group{algebra}

Let $\varphi : R \to S$ be a ring map. Assume
\begin{enumerate}
\item $R$ is Noetherian,
\item $S$ is Noetherian,
\item $\varphi$ is flat,
\item the fibre rings $S \otimes_R \kappa(\mathfrak p)$ are $(S_k)$, and
\item $R$ has property $(S_k)$.
\end{enumerate}
Then $S$ has property $(S_k)$.
\end{lemma}

\begin{proof}
\uses{algebra-lemma-apply-grothendieck, algebra-lemma-dimension-base-fibre-total, algebra-lemma-dimension-base-fibre-equals-total}

Let $\mathfrak q$ be a prime of $S$
lying over a prime $\mathfrak p$ of $R$. By
Lemma \ref{algebra-lemma-apply-grothendieck} we have
$$
\text{depth}(S_{\mathfrak q}) =
\text{depth}(S_{\mathfrak q}/\mathfrak pS_{\mathfrak q}) +
\text{depth}(R_{\mathfrak p}).
$$
On the other hand, we have
$$
\dim(R_{\mathfrak p})
+
\dim(S_{\mathfrak q}/\mathfrak pS_{\mathfrak q})
\geq
\dim(S_{\mathfrak q})
$$
by Lemma \ref{algebra-lemma-dimension-base-fibre-total}.
(Actually equality holds, by
Lemma \ref{algebra-lemma-dimension-base-fibre-equals-total}
but strictly speaking we do not need this.)
Finally, as the fibre rings of the map
are assumed $(S_k)$ we see that
$\text{depth}(S_{\mathfrak q}/\mathfrak pS_{\mathfrak q})
\geq \min(k, \dim(S_{\mathfrak q}/\mathfrak pS_{\mathfrak q}))$.
Thus the lemma follows by the following string of inequalities
\begin{eqnarray*}
\text{depth}(S_{\mathfrak q}) & = &
\text{depth}(S_{\mathfrak q}/\mathfrak pS_{\mathfrak q}) +
\text{depth}(R_{\mathfrak p}) \\
& \geq &
\min(k, \dim(S_{\mathfrak q}/\mathfrak pS_{\mathfrak q})) +
\min(k, \dim(R_{\mathfrak p})) \\
& = &
\min(2k, \dim(S_{\mathfrak q}/\mathfrak pS_{\mathfrak q}) + k,
k + \dim(R_\mathfrak p),
\dim(S_{\mathfrak q}/\mathfrak pS_{\mathfrak q}) +
\dim(R_{\mathfrak p})) \\
& \geq &
\min(k, \dim(S_{\mathfrak q}))
\end{eqnarray*}
as desired.
\end{proof}

\begin{lemma}[Rk goes up]
\label{algebra-lemma-Rk-goes-up}
\source{stacks:033A}
\href{https://stacks.math.columbia.edu/tag/033A}{\texttt{Stacks tag 033A}}
\group{algebra}

Let $\varphi : R \to S$ be a ring map. Assume
\begin{enumerate}
\item $R$ is Noetherian,
\item $S$ is Noetherian
\item $\varphi$ is flat,
\item the fibre rings $S \otimes_R \kappa(\mathfrak p)$
have property $(R_k)$, and
\item $R$ has property $(R_k)$.
\end{enumerate}
Then $S$ has property $(R_k)$.
\end{lemma}

\begin{proof}
\uses{algebra-lemma-dimension-base-fibre-equals-total, algebra-lemma-flat-over-regular-with-regular-fibre}

Let $\mathfrak q$ be a prime of $S$
lying over a prime $\mathfrak p$ of $R$.
Assume that $\dim(S_{\mathfrak q}) \leq k$.
Since $\dim(S_{\mathfrak q}) = \dim(R_{\mathfrak p})
+ \dim(S_{\mathfrak q}/\mathfrak pS_{\mathfrak q})$ by
Lemma \ref{algebra-lemma-dimension-base-fibre-equals-total}
we see that $\dim(R_{\mathfrak p}) \leq k$ and
$\dim(S_{\mathfrak q}/\mathfrak pS_{\mathfrak q}) \leq k$.
Hence $R_{\mathfrak p}$ and $S_{\mathfrak q}/\mathfrak pS_{\mathfrak q}$
are regular by assumption.
It follows that $S_{\mathfrak q}$ is regular by
Lemma \ref{algebra-lemma-flat-over-regular-with-regular-fibre}.
\end{proof}

\begin{lemma}[Reduced goes up noetherian]
\label{algebra-lemma-reduced-goes-up-noetherian}
