Let $\varphi : R \to S$ be a ring map. Assume
\begin{enumerate}
\item $R$ is Noetherian,
\item $S$ is Noetherian
\item $\varphi$ is flat,
\item the fibre rings $S \otimes_R \kappa(\mathfrak p)$ are reduced,
\item $R$ is reduced.
\end{enumerate}
Then $S$ is reduced.
\end{lemma}

\begin{proof}
\uses{algebra-lemma-criterion-reduced, algebra-lemma-Sk-goes-up, algebra-lemma-Rk-goes-up}

For Noetherian rings reduced is the same as having properties
$(S_1)$ and $(R_0)$, see Lemma \ref{algebra-lemma-criterion-reduced}.
Thus we know $R$ and the fibre rings have these properties.
Hence we may apply Lemmas \ref{algebra-lemma-Sk-goes-up} and \ref{algebra-lemma-Rk-goes-up}
and we see that $S$ is $(S_1)$ and $(R_0)$, in other words reduced
by Lemma \ref{algebra-lemma-criterion-reduced} again.
\end{proof}

\begin{lemma}[Reduced goes up]
\label{algebra-lemma-reduced-goes-up}
\source{stacks:033B}
\href{https://stacks.math.columbia.edu/tag/033B}{\texttt{Stacks tag 033B}}
\group{algebra}

Let $\varphi : R \to S$ be a ring map. Assume
\begin{enumerate}
\item $\varphi$ is smooth,
\item $R$ is reduced.
\end{enumerate}
Then $S$ is reduced.
\end{lemma}

\begin{proof}
\uses{algebra-lemma-reduced-goes-up-noetherian}

Observe that $R \to S$ is flat with regular fibres (see the list of
results on smooth ring maps in Section \ref{algebra-section-smooth-overview}).
In particular, the fibres are reduced.
Thus if $R$ is Noetherian, then $S$ is Noetherian and we get
the result from Lemma \ref{algebra-lemma-reduced-goes-up-noetherian}.

\medskip\noindent
In the general case we may find a finitely generated
$\mathbf{Z}$-subalgebra $R_0 \subset R$ and a smooth ring
map $R_0 \to S_0$ such that $S \cong R \otimes_{R_0} S_0$, see
remark (10) in Section \ref{algebra-section-smooth-overview}.
Now, if $x \in S$ is an element with $x^2 = 0$,
then we can enlarge $R_0$ and assume that $x$ comes
from an element $x_0 \in S_0$. After enlarging
$R_0$ once more we may assume that $x_0^2 = 0$ in $S_0$.
However, since $R_0 \subset R$ is reduced we see that
$S_0$ is reduced and hence $x_0 = 0$ as desired.
\end{proof}

