\group{algebra}

\uses{algebra-lemma-geometrically-normal}
Let $k$ be a field.
A $k$-algebra $R$ is called {\it geometrically normal} over $k$ if
the equivalent conditions of Lemma \ref{algebra-lemma-geometrically-normal} hold.
\end{definition}

\begin{lemma}[Localization preserves geometric normality.]
\label{algebra-lemma-localization-geometrically-normal-algebra}
\source{stacks:06DE}
\href{https://stacks.math.columbia.edu/tag/06DE}{\texttt{Stacks tag 06DE}}
\group{algebra}


Let $k$ be a field. A localization of a geometrically normal $k$-algebra
is geometrically normal.
\end{lemma}

\begin{proof}
This is clear as being a normal ring is checked at the localizations at
prime ideals.
\end{proof}

\begin{lemma}[Separable field extension geometrically normal]
\label{algebra-lemma-separable-field-extension-geometrically-normal}
\source{stacks:0C30}
\href{https://stacks.math.columbia.edu/tag/0C30}{\texttt{Stacks tag 0C30}}
\group{algebra}

Let $k$ be a field. Let $K/k$ be a separable field extension.
Then $K$ is geometrically normal over $k$.
\end{lemma}

\begin{proof}
\uses{algebra-lemma-separable-extension-preserves-reducedness, algebra-lemma-perfection, algebra-definition-perfection, algebra-lemma-radicial-integral-bijective}

This is true because $k^{perf} \otimes_k K$ is a field.
Namely, it is reduced by
Lemma \ref{algebra-lemma-separable-extension-preserves-reducedness}.
By Lemma \ref{algebra-lemma-perfection} (or by
Definition \ref{algebra-definition-perfection})
the field extension $k^{perf}/k$ is purely inseparable.
Hence by Lemma \ref{algebra-lemma-radicial-integral-bijective} the ring
$k^{perf} \otimes_k K$ has a unique prime ideal. A reduced ring with
a unique prime ideal is a field.
\end{proof}

\begin{lemma}[Geometrically normal tensor normal]
\label{algebra-lemma-geometrically-normal-tensor-normal}
\source{stacks:06DF}
\href{https://stacks.math.columbia.edu/tag/06DF}{\texttt{Stacks tag 06DF}}
\group{algebra}

Let $k$ be a field. Let $A, B$ be $k$-algebras. Assume $A$ is geometrically
normal over $k$ and $B$ is a normal ring. Then $A \otimes_k B$ is a normal
ring.
\end{lemma}

\begin{proof}
\uses{algebra-lemma-localization-normal-ring, algebra-lemma-localization-geometrically-normal-algebra, algebra-proposition-ubiquity-nagata, algebra-proposition-nagata-universally-japanese, algebra-lemma-colimit-normal-ring, algebra-lemma-Noetherian-permanence, algebra-lemma-Noetherian-irreducible-components, algebra-lemma-flat-going-down, algebra-lemma-characterize-reduced-ring-normal, algebra-lemma-normal-ring-integrally-closed, algebra-lemma-subalgebra-separable, algebra-lemma-localization-smooth-separable, algebra-lemma-normal-goes-up}

Let $\mathfrak r$ be a prime ideal of $A \otimes_k B$. Denote
$\mathfrak p$, resp.\ $\mathfrak q$ the corresponding prime of $A$,
resp.\ $B$. Then $(A \otimes_k B)_{\mathfrak r}$ is a localization of
$A_{\mathfrak p} \otimes_k B_{\mathfrak q}$. Hence it suffices to prove the
result for the ring $A_{\mathfrak p} \otimes_k B_{\mathfrak q}$, see
Lemma \ref{algebra-lemma-localization-normal-ring}
and
Lemma \ref{algebra-lemma-localization-geometrically-normal-algebra}.
Thus we may assume $A$ and $B$ are domains.

\medskip\noindent
Assume that $A$ and $B$ are domains with fractions fields $K$ and $L$.
Note that $B$ is the filtered colimit of its finite type normal
$k$-sub algebras (as $k$ is a Nagata ring, see
Proposition \ref{algebra-proposition-ubiquity-nagata},
and hence the integral closure of a finite type $k$-sub algebra is still
a finite type $k$-sub algebra by
Proposition \ref{algebra-proposition-nagata-universally-japanese}).
By
Lemma \ref{algebra-lemma-colimit-normal-ring}
we reduce to the case that $B$ is of finite type over $k$.

\medskip\noindent
Assume that $A$ and $B$ are domains with fractions fields $K$ and $L$
and $B$ of finite type over $k$. In this case the ring $K \otimes_k B$
is of finite type over $K$, hence Noetherian
(Lemma \ref{algebra-lemma-Noetherian-permanence}).
In particular $K \otimes_k B$ has finitely many minimal primes
(Lemma \ref{algebra-lemma-Noetherian-irreducible-components}).
Since $A \to A \otimes_k B$ is flat, this implies that $A \otimes_k B$
has finitely many minimal primes (by going down for flat ring maps --
Lemma \ref{algebra-lemma-flat-going-down}
-- these primes all lie over $(0) \subset A$). Thus it suffices to prove
that $A \otimes_k B$ is integrally closed in its total ring of fractions
(Lemma \ref{algebra-lemma-characterize-reduced-ring-normal}).

\medskip\noindent
We claim that $K \otimes_k B$ and $A \otimes_k L$ are both normal rings.
If this is true then any element $x$ of $Q(A \otimes_k B)$ which is
integral over $A \otimes_k B$ is (by
Lemma \ref{algebra-lemma-normal-ring-integrally-closed})
contained in $K \otimes_k B \cap A \otimes_k L = A \otimes_k B$ and we're done.
Since $A \otimes_K L$ is a normal ring by assumption, it suffices to
prove that $K \otimes_k B$ is normal.

\medskip\noindent
As $A$ is geometrically normal over $k$ we see $K$ is geometrically normal
over $k$
(Lemma \ref{algebra-lemma-localization-geometrically-normal-algebra})
hence $K$ is geometrically reduced over $k$.
Hence $K = \bigcup K_i$ is the union of finitely generated field extensions
of $k$ which are geometrically reduced
(Lemma \ref{algebra-lemma-subalgebra-separable}).
Each $K_i$ is the localization of a smooth $k$-algebra
(Lemma \ref{algebra-lemma-localization-smooth-separable}).
So $K_i \otimes_k B$ is the localization of a smooth $B$-algebra hence normal
(Lemma \ref{algebra-lemma-normal-goes-up}).
Thus $K \otimes_k B$ is a normal ring
(Lemma \ref{algebra-lemma-colimit-normal-ring})
and we win.
\end{proof}

\begin{lemma}[Geometrically normal over separable algebraic]
\label{algebra-lemma-geometrically-normal-over-separable-algebraic}
\source{stacks:0C31}
\href{https://stacks.math.columbia.edu/tag/0C31}{\texttt{Stacks tag 0C31}}
\group{algebra}

Let $k'/k$ be a separable algebraic field extension.
Let $A$ be an algebra over $k'$. Then $A$ is geometrically normal
over $k$ if and only if it is geometrically normal over $k'$.
\end{lemma}

\begin{proof}
\uses{algebra-lemma-separable-algebraic-diagonal}

Let $L/k$ be a finite purely inseparable field extension.
Then $L' = k' \otimes_k L$ is a field (see material in
Fields, Section \ref{fields-section-algebraic})
and $A \otimes_k L = A \otimes_{k'} L'$. Hence if
$A$ is geometrically normal over $k'$, then $A$ is geometrically
normal over $k$.

\medskip\noindent
Assume $A$ is geometrically normal over $k$. Let $K/k'$ be a field
extension. Then
$$
K \otimes_{k'} A = (K \otimes_k A) \otimes_{(k' \otimes_k k')} k'
$$
Since $k' \otimes_k k' \to k'$ is a localization by
Lemma \ref{algebra-lemma-separable-algebraic-diagonal},
we see that $K \otimes_{k'} A$
is a localization of a normal ring, hence normal.
\end{proof}

\section{Geometrically regular algebras}
\label{algebra-section-geometrically-regular}
Let $k$ be a field.
Let $A$ be a Noetherian $k$-algebra.
Let $K/k$ be a finitely generated field extension.
Then the ring $K \otimes_k A$ is Noetherian as well, see
Lemma \ref{algebra-lemma-Noetherian-field-extension}.
Thus the following lemma makes sense.

\begin{lemma}[Geometrically regular]
\label{algebra-lemma-geometrically-regular}
\source{stacks:0381}
\href{https://stacks.math.columbia.edu/tag/0381}{\texttt{Stacks tag 0381}}
\group{algebra}

\uses{algebra-definition-regular}
Let $k$ be a field. Let $A$ be a $k$-algebra.
Assume $A$ is Noetherian.
The following properties of $A$ are equivalent:
\begin{enumerate}
\item $k' \otimes_k A$ is regular for every finitely generated field
extension $k'/k$, and
\item $k' \otimes_k A$ is regular for every finite purely inseparable
extension $k'/k$.
\end{enumerate}
Here regular ring is as in Definition \ref{algebra-definition-regular}.
\end{lemma}

\begin{proof}
\uses{algebra-lemma-make-separable, algebra-lemma-localization-smooth-separable, algebra-lemma-base-change-smooth, algebra-lemma-regular-goes-up, algebra-lemma-descent-regular}

The lemma makes sense by the remarks preceding the lemma.
It is clear that (1) $\Rightarrow$ (2).

\medskip\noindent
Assume (2) and let $K/k$ be a finitely generated field extension.
By Lemma \ref{algebra-lemma-make-separable} we can find a diagram
$$
\begin{array}{cc}K \longrightarrow & K' \\ k \uparrow\longrightarrow & k' \uparrow\end{array}
$$
where $k'/k$, $K'/K$ are finite purely inseparable field
extensions such that $K'/k'$ is separable. By
Lemma \ref{algebra-lemma-localization-smooth-separable}
there exists a smooth $k'$-algebra $B$ such that $K'$ is the
fraction field of $B$. Now we can argue as follows:
Step 1: $k' \otimes_k A$ is a regular ring because we assumed (2).
Step 2: $B \otimes_{k'} k' \otimes_k A$ is a regular ring as
$k' \otimes_k A \to B \otimes_{k'} k' \otimes_k A$ is smooth
(Lemma \ref{algebra-lemma-base-change-smooth})
and ascent of regularity along smooth maps
(Lemma \ref{algebra-lemma-regular-goes-up}).
Step 3. $K' \otimes_{k'} k' \otimes_k A = K' \otimes_k A$ is
a regular ring as it is a localization of a regular ring
(immediate from the definition).
Step 4. Finally $K \otimes_k A$ is a regular ring by descent of
regularity along the faithfully flat ring map
$K \otimes_k A \to K' \otimes_k A$ (Lemma \ref{algebra-lemma-descent-regular}).
This proves the lemma.
\end{proof}

\begin{definition}[Geometrically regular]
\label{algebra-definition-geometrically-regular}
\source{stacks:0382}
\href{https://stacks.math.columbia.edu/tag/0382}{\texttt{Stacks tag 0382}}
\group{algebra}

\uses{algebra-lemma-geometrically-regular}
Let $k$ be a field. Let $R$ be a Noetherian $k$-algebra.
The $k$-algebra $R$ is called {\it geometrically regular} over $k$ if
the equivalent conditions of Lemma \ref{algebra-lemma-geometrically-regular} hold.
\end{definition}

It is clear from the definition that $K \otimes_k R$ is a geometrically
regular algebra over $K$ for any finitely generated field extension $K$ of
$k$. We will see later (More on Algebra, Proposition
\ref{more-algebra-proposition-characterization-geometrically-regular})
that it suffices to check $R \otimes_k k'$ is regular whenever
$k \subset k' \subset k^{1/p}$ (finite).

\begin{lemma}[Geometric regularity descends through faithfully flat maps of algebras]
\label{algebra-lemma-geometrically-regular-descent}
\source{stacks:07NH}
\href{https://stacks.math.columbia.edu/tag/07NH}{\texttt{Stacks tag 07NH}}
\group{algebra}


Let $k$ be a field. Let $A \to B$ be a faithfully flat $k$-algebra
map. If $B$ is geometrically regular over $k$, so is $A$.
\end{lemma}

\begin{proof}
\uses{algebra-lemma-surjective-spec-radical-ideal, algebra-lemma-flat-base-change, algebra-lemma-descent-regular}

Assume $B$ is geometrically regular over $k$.
Let $k'/k$ be a finite, purely inseparable extension.
Then $A \otimes_k k' \to B \otimes_k k'$ is faithfully flat as a
base change of $A \to B$ (by
Lemmas \ref{algebra-lemma-surjective-spec-radical-ideal} and
\ref{algebra-lemma-flat-base-change})
and $B \otimes_k k'$ is regular by our
assumption on $B$ over $k$. Then $A \otimes_k k'$ is regular by
Lemma \ref{algebra-lemma-descent-regular}.
\end{proof}

\begin{lemma}[Geometrically regular goes up]
\label{algebra-lemma-geometrically-regular-goes-up}
\source{stacks:07QF}
\href{https://stacks.math.columbia.edu/tag/07QF}{\texttt{Stacks tag 07QF}}
\group{algebra}

Let $k$ be a field. Let $A \to B$ be a smooth ring map
of $k$-algebras. If $A$ is geometrically regular over $k$,
then $B$ is geometrically regular over $k$.
\end{lemma}

\begin{proof}
\uses{algebra-lemma-base-change-smooth, algebra-lemma-regular-goes-up}

Let $k'/k$ be a finitely generated field extension.
Then $A \otimes_k k' \to B \otimes_k k'$ is a smooth ring map
(Lemma \ref{algebra-lemma-base-change-smooth}) and $A \otimes_k k'$
is regular. Hence $B \otimes_k k'$ is regular by
Lemma \ref{algebra-lemma-regular-goes-up}.
\end{proof}

\begin{lemma}[Geometrically regular over subfields]
\label{algebra-lemma-geometrically-regular-over-subfields}
\source{stacks:07QG}
\href{https://stacks.math.columbia.edu/tag/07QG}{\texttt{Stacks tag 07QG}}
\group{algebra}

Let $k$ be a field. Let $A$ be an algebra over $k$.
Let $k = \colim k_i$ be a directed colimit of subfields.
If $A$ is geometrically regular over each $k_i$, then
$A$ is geometrically regular over $k$.
\end{lemma}

\begin{proof}
Let $k'/k$ be a finite purely inseparable field extension.
We can get $k'$ by adjoining finitely many variables to $k$ and
imposing finitely many polynomial relations. Hence we see that
there exists an $i$ and a finite purely inseparable field extension
$k_i'/k_i$ such that $k_i = k \otimes_{k_i} k_i'$.
Thus $A \otimes_k k' = A \otimes_{k_i} k_i'$ and the lemma is clear.
\end{proof}

\begin{lemma}[Geometrically regular over separable algebraic]
\label{algebra-lemma-geometrically-regular-over-separable-algebraic}
\source{stacks:07QH}
\href{https://stacks.math.columbia.edu/tag/07QH}{\texttt{Stacks tag 07QH}}
\group{algebra}

Let $k'/k$ be a separable algebraic field extension.
Let $A$ be an algebra over $k'$. Then $A$ is geometrically
regular over $k$ if and only if it is geometrically regular over $k'$.
\end{lemma}

\begin{proof}
\uses{algebra-lemma-geometrically-regular-over-subfields, algebra-lemma-etale, algebra-lemma-geometrically-regular-goes-up}

Let $L/k$ be a finite purely inseparable field extension.
Then $L' = k' \otimes_k L$ is a field (see material in
Fields, Section \ref{fields-section-algebraic})
and $A \otimes_k L = A \otimes_{k'} L'$. Hence if
$A$ is geometrically regular over $k'$, then $A$ is geometrically
regular over $k$.

\medskip\noindent
Assume $A$ is geometrically regular over $k$. Since $k'$
is the filtered colimit of finite extensions of $k$ we may
assume by Lemma \ref{algebra-lemma-geometrically-regular-over-subfields}
that $k'/k$ is finite separable. Consider the ring maps
$$
k' \to A \otimes_k k' \to A.
$$
Note that $A \otimes_k k'$ is geometrically regular over $k'$
as a base change of $A$ to $k'$. Note that $A \otimes_k k' \to A$
is the base change of $k' \otimes_k k' \to k'$ by the map
$k' \to A$. Since $k'/k$ is an \'etale extension of rings, we
see that $k' \otimes_k k' \to k'$ is \'etale
(Lemma \ref{algebra-lemma-etale}). Hence $A$ is
geometrically regular over $k'$ by
Lemma \ref{algebra-lemma-geometrically-regular-goes-up}.
\end{proof}

\section{Geometrically Cohen-Macaulay algebras}
\label{algebra-section-geometrically-CM}
This section is a bit of a misnomer, since Cohen-Macaulay algebras
are automatically geometrically Cohen-Macaulay. Namely, see
Lemma \ref{algebra-lemma-extend-field-CM-locus}
and
Lemma \ref{algebra-lemma-CM-geometrically-CM}
below.

\begin{lemma}[Tensor fields CM]
\label{algebra-lemma-tensor-fields-CM}
\source{stacks:045M}
\href{https://stacks.math.columbia.edu/tag/045M}{\texttt{Stacks tag 045M}}
\group{algebra}

Let $k$ be a field and let $K/k$ and $L/k$ be
two field extensions such that one of them is a field extension of finite type.
Then $K \otimes_k L$ is a Noetherian Cohen-Macaulay ring.
\end{lemma}

\begin{proof}
\uses{algebra-lemma-Noetherian-field-extension, algebra-lemma-finite-flat-over-regular-CM, algebra-lemma-CM-polynomial-algebra}

The ring $K \otimes_k L$ is Noetherian by
Lemma \ref{algebra-lemma-Noetherian-field-extension}.
Say $K$ is a finite extension of the purely transcendental extension
$k(t_1, \ldots, t_r)$. Then
$k(t_1, \ldots, t_r) \otimes_k L \to K \otimes_k L$
is a finite free ring map. By
Lemma \ref{algebra-lemma-finite-flat-over-regular-CM}
it suffices to show that $k(t_1, \ldots, t_r) \otimes_k L$ is Cohen-Macaulay.
This is clear because it is a localization of the polynomial
ring $L[t_1, \ldots, t_r]$. (See for example
Lemma \ref{algebra-lemma-CM-polynomial-algebra}
for the fact that a polynomial ring is Cohen-Macaulay.)
\end{proof}

\begin{lemma}[CM geometrically CM]
\label{algebra-lemma-CM-geometrically-CM}
\source{stacks:045N}
\href{https://stacks.math.columbia.edu/tag/045N}{\texttt{Stacks tag 045N}}
\group{algebra}

Let $k$ be a field. Let $S$ be a Noetherian $k$-algebra.
Let $K/k$ be a finitely generated field extension,
and set $S_K = K \otimes_k S$. Let $\mathfrak q \subset S$
be a prime of $S$. Let $\mathfrak q_K \subset S_K$ be a prime
of $S_K$ lying over $\mathfrak q$. Then $S_{\mathfrak q}$ is Cohen-Macaulay
if and only if $(S_K)_{\mathfrak q_K}$ is Cohen-Macaulay.
\end{lemma}

\begin{proof}
\uses{algebra-lemma-Noetherian-field-extension, algebra-lemma-tensor-fields-CM, algebra-lemma-CM-goes-up}

By
Lemma \ref{algebra-lemma-Noetherian-field-extension}
the ring $S_K$ is Noetherian. Hence
$S_{\mathfrak q} \to (S_K)_{\mathfrak q_K}$ is a flat local homomorphism
of Noetherian local rings. Note that the fibre
$$
(S_K)_{\mathfrak q_K} / \mathfrak q (S_K)_{\mathfrak q_K}
\cong (\kappa(\mathfrak q) \otimes_k K)_{\mathfrak q'}
$$
is the localization of the Cohen-Macaulay (Lemma \ref{algebra-lemma-tensor-fields-CM})
ring $\kappa(\mathfrak q) \otimes_k K$ at a suitable prime ideal
$\mathfrak q'$. Hence the lemma follows from Lemma \ref{algebra-lemma-CM-goes-up}.
\end{proof}

\section{Colimits and maps of finite presentation, II}
\label{algebra-section-colimits-finite-presentation}
This section is a continuation of Section \ref{algebra-section-colimits-flat}.

\medskip\noindent
We start with an application of the openness of flatness.
It says that we can approximate flat modules by flat modules
which is useful.

\begin{lemma}[Flat finite presentation limit flat]
\label{algebra-lemma-flat-finite-presentation-limit-flat}
\source{stacks:02JO}
\href{https://stacks.math.columbia.edu/tag/02JO}{\texttt{Stacks tag 02JO}}
\group{algebra}

Let $R \to S$ be a ring map.
Let $M$ be an $S$-module.
Assume that
\begin{enumerate}
\item $R \to S$ is of finite presentation,
\item $M$ is a finitely presented $S$-module, and
\item $M$ is flat over $R$.
\end{enumerate}
In this case we have the following:
\begin{enumerate}
\item There exists a finite type $\mathbf{Z}$-algebra $R_0$ and
a finite type ring map $R_0 \to S_0$ and a finite $S_0$-module $M_0$
such that $M_0$ is flat over $R_0$, together with a ring maps
$R_0 \to R$ and $S_0 \to S$ and an $S_0$-module map $M_0 \to M$
such that $S \cong R \otimes_{R_0} S_0$ and $M = S \otimes_{S_0} M_0$.
\item If $R = \colim_{\lambda \in \Lambda} R_\lambda$ is written
as a directed colimit, then there exists a $\lambda$ and a ring map
$R_\lambda \to S_\lambda$ of finite presentation, and an $S_\lambda$-module
$M_\lambda$ of finite presentation such that $M_\lambda$ is flat over
$R_\lambda$ and such that $S = R \otimes_{R_\lambda} S_\lambda$ and
$M = S \otimes_{S_{\lambda}} M_\lambda$.
\item If
$$
(R \to S, M) =
\colim_{\lambda \in \Lambda}
(R_\lambda \to S_\lambda, M_\lambda)
$$
is written as a directed colimit such that
\begin{enumerate}
\item $R_\mu \otimes_{R_\lambda} S_\lambda \to S_\mu$ and
$S_\mu \otimes_{S_\lambda} M_\lambda \to M_\mu$ are isomorphisms
for $\mu \geq \lambda$,
\item $R_\lambda \to S_\lambda$ is of finite presentation,
\item $M_\lambda$ is a finitely presented $S_\lambda$-module,
\end{enumerate}
then for all sufficiently large $\lambda$ the module $M_\lambda$
is flat over $R_\lambda$.
\end{enumerate}
\end{lemma}

\begin{proof}
\uses{algebra-lemma-limit-module-finite-presentation, algebra-theorem-openness-flatness, algebra-lemma-limit-module-essentially-finite-presentation, algebra-lemma-colimit-eventually-flat, algebra-lemma-characterize-finite-presentation, algebra-lemma-colimit-category-fp-algebras, algebra-lemma-module-map-property-in-colimit, algebra-lemma-colimit-category-fp-modules}

We first write $(R \to S, M)$ as the directed colimit of a system
$(R_\lambda \to S_\lambda, M_\lambda)$ as in
Lemma \ref{algebra-lemma-limit-module-finite-presentation}.
Let $\mathfrak q \subset S$ be a prime.
Let $\mathfrak p \subset R$, $\mathfrak q_\lambda \subset S_\lambda$,
and $\mathfrak p_\lambda \subset R_\lambda$ the corresponding primes.
As seen in the proof of Theorem \ref{algebra-theorem-openness-flatness}
$$
((R_\lambda)_{\mathfrak p_\lambda},
(S_\lambda)_{\mathfrak q_\lambda},
(M_\lambda)_{\mathfrak q_{\lambda}})
$$
is a system as in
Lemma \ref{algebra-lemma-limit-module-essentially-finite-presentation}, and
hence by Lemma \ref{algebra-lemma-colimit-eventually-flat}
we see that for some $\lambda_{\mathfrak q} \in \Lambda$
for all $\lambda \geq \lambda_{\mathfrak q}$
the module $M_\lambda$ is flat over
$R_\lambda$ at the prime $\mathfrak q_{\lambda}$.

\medskip\noindent
By Theorem \ref{algebra-theorem-openness-flatness} we get an open subset
$U_\lambda \subset \Spec(S_\lambda)$ such that $M_\lambda$
flat over $R_\lambda$ at all the primes of $U_\lambda$.
Denote $V_\lambda \subset \Spec(S)$ the inverse image of
$U_\lambda$ under the map $\Spec(S) \to \Spec(S_\lambda)$.
The argument above shows that for every $\mathfrak q \in \Spec(S)$
there exists a $\lambda_{\mathfrak q}$ such that
$\mathfrak q \in V_\lambda$ for all $\lambda \geq \lambda_{\mathfrak q}$.
Since $\Spec(S)$ is quasi-compact we see this implies there
exists a single $\lambda_0 \in \Lambda$ such that
$V_{\lambda_0} = \Spec(S)$.

\medskip\noindent
The complement $\Spec(S_{\lambda_0}) \setminus U_{\lambda_0}$
is $V(I)$ for some ideal $I \subset S_{\lambda_0}$. As
$V_{\lambda_0} = \Spec(S)$ we see that $IS = S$.
Choose $f_1, \ldots, f_r \in I$ and $s_1, \ldots, s_n \in S$ such
that $\sum f_i s_i = 1$. Since $\colim S_\lambda = S$, after
increasing $\lambda_0$ we may assume there exist
$s_{i, \lambda_0} \in S_{\lambda_0}$ such that
$\sum f_i s_{i, \lambda_0} = 1$.
Hence for this $\lambda_0$ we have
$U_{\lambda_0} = \Spec(S_{\lambda_0})$.
This proves (1).

\medskip\noindent
Proof of (2). Let $(R_0 \to S_0, M_0)$ be as in (1) and suppose that
$R = \colim R_\lambda$. Since $R_0$ is a finite type $\mathbf{Z}$
algebra, there exists a $\lambda$ and a map $R_0 \to R_\lambda$ such
that $R_0 \to R_\lambda \to R$ is the given map $R_0 \to R$ (see
Lemma \ref{algebra-lemma-characterize-finite-presentation}).
Then, part (2) follows by taking $S_\lambda = R_\lambda \otimes_{R_0} S_0$
and $M_\lambda = S_\lambda \otimes_{S_0} M_0$.

\medskip\noindent
Finally, we come to the proof of (3). Let
$(R_\lambda \to S_\lambda, M_\lambda)$ be as in (3). Choose
$(R_0 \to S_0, M_0)$ and $R_0 \to R$ as in (1).
As in the proof of (2), there exists a $\lambda_0$ and a ring map
$R_0 \to R_{\lambda_0}$ such that $R_0 \to R_{\lambda_0} \to R$ is the given
map $R_0 \to R$. Since $S_0$ is of finite presentation over $R_0$ and since
$S = \colim S_\lambda$ we see that for some $\lambda_1 \geq \lambda_0$
we get an $R_0$-algebra map $S_0 \to S_{\lambda_1}$ such that the
composition $S_0 \to S_{\lambda_1} \to S$ is the given map $S_0 \to S$
(see Lemma \ref{algebra-lemma-characterize-finite-presentation}).
For all $\lambda \geq \lambda_1$ this gives maps
$$
\Psi_{\lambda} :
R_\lambda \otimes_{R_0} S_0
\longrightarrow
R_\lambda \otimes_{R_{\lambda_1}} S_{\lambda_1}
\cong
S_\lambda
$$
the last isomorphism by assumption. By construction
$\colim_\lambda \Psi_\lambda$ is an isomorphism. Hence $\Psi_\lambda$
is an isomorphism for all $\lambda$ large enough by
Lemma \ref{algebra-lemma-colimit-category-fp-algebras}.
In the same vein, there exists a $\lambda_2 \geq \lambda_1$
and an $S_0$-module map $M_0 \to M_{\lambda_2}$ such that
$M_0 \to M_{\lambda_2} \to M$ is the given
map $M_0 \to M$ (see Lemma \ref{algebra-lemma-module-map-property-in-colimit}).
For $\lambda \geq \lambda_2$ there is an induced map
$$
S_\lambda \otimes_{S_0} M_0
\longrightarrow
S_\lambda \otimes_{S_{\lambda_2}} M_{\lambda_2}
\cong
M_\lambda
$$
and for $\lambda$ large enough this map is an isomorphism by
Lemma \ref{algebra-lemma-colimit-category-fp-modules}.
This implies (3) because $M_0$ is flat over $R_0$.
\end{proof}

\begin{lemma}[Descend faithfully flat finite presentation]
\label{algebra-lemma-descend-faithfully-flat-finite-presentation}
\source{stacks:034Y}
\href{https://stacks.math.columbia.edu/tag/034Y}{\texttt{Stacks tag 034Y}}
\group{algebra}

Let $R \to A \to B$ be ring maps.
Assume $A \to B$ faithfully flat of finite presentation.
Then there exists a commutative diagram
$$
\begin{array}{ccc}R \longrightarrow\downarrow & A_0 \downarrow\longrightarrow & B_0 \downarrow \\ R \longrightarrow & A \longrightarrow & B\end{array}
$$
with $R \to A_0$ of finite presentation,
$A_0 \to B_0$ faithfully flat of finite presentation
and $B = A \otimes_{A_0} B_0$.
\end{lemma}

\begin{proof}
\uses{algebra-lemma-flat-finite-presentation-limit-flat, algebra-proposition-fppf-open, algebra-lemma-ff-rings}

We first prove the lemma with $R$ replaced $\mathbf{Z}$.
By Lemma \ref{algebra-lemma-flat-finite-presentation-limit-flat}
there exists a diagram
$$
\begin{array}{cc}A_0 \longrightarrow\downarrow & A \downarrow \\ B_0 \longrightarrow & B\end{array}
$$
where $A_0$ is of finite type over $\mathbf{Z}$, $B_0$ is flat of finite
presentation over $A_0$ such that $B = A \otimes_{A_0} B_0$.
As $A_0 \to B_0$ is flat of finite presentation we see that the image of
$\Spec(B_0) \to \Spec(A_0)$ is open, see
Proposition \ref{algebra-proposition-fppf-open}. Hence the complement of the image
is $V(I_0)$ for some ideal $I_0 \subset A_0$.
As $A \to B$ is faithfully
flat the map $\Spec(B) \to \Spec(A)$ is surjective, see
Lemma \ref{algebra-lemma-ff-rings}.
Now we use that
the base change of the image is the image of the base change.
Hence $I_0A = A$. Pick a relation
$\sum f_i r_i = 1$, with $r_i \in A$, $f_i \in I_0$. Then after
enlarging $A_0$ to contain the elements $r_i$ (and correspondingly
enlarging $B_0$) we see that $A_0 \to B_0$ is surjective on spectra
also, i.e., faithfully flat.

\medskip\noindent
Thus the lemma holds in case $R = \mathbf{Z}$.
In the general case, take the solution $A_0' \to B_0'$
just obtained and set $A_0 = A_0' \otimes_{\mathbf{Z}} R$,
$B_0 = B_0' \otimes_{\mathbf{Z}} R$.
\end{proof}

\begin{lemma}[Colimit finite]
\label{algebra-lemma-colimit-finite}
\source{stacks:07RG}
\href{https://stacks.math.columbia.edu/tag/07RG}{\texttt{Stacks tag 07RG}}
\group{algebra}

Let $A = \colim_{i \in I} A_i$ be a directed colimit of rings.
Let $0 \in I$ and $\varphi_0 : B_0 \to C_0$ a map of $A_0$-algebras.
Assume
\begin{enumerate}
\item $A \otimes_{A_0} B_0 \to A \otimes_{A_0} C_0$ is finite,
\item $C_0$ is of finite type over $B_0$.
\end{enumerate}
Then there exists an $i \geq 0$ such that the map
$A_i \otimes_{A_0} B_0 \to A_i \otimes_{A_0} C_0$
is finite.
\end{lemma}

\begin{proof}
Let $x_1, \ldots, x_m$ be generators for $C_0$ over $B_0$.
Pick monic polynomials $P_j \in A \otimes_{A_0} B_0[T]$ such
that $P_j(1 \otimes x_j) = 0$ in $A \otimes_{A_0} C_0$. For some
$i \geq 0$ we can find $P_{j, i} \in A_i \otimes_{A_0} B_0[T]$
mapping to $P_j$. Since $\otimes$
commutes with colimits we see that $P_{j, i}(1 \otimes x_j)$ is zero
in $A_i \otimes_{A_0} C_0$ after possibly increasing $i$.
Then this $i$ works.
\end{proof}

\begin{lemma}[Colimit surjective]
\label{algebra-lemma-colimit-surjective}
\source{stacks:07RH}
\href{https://stacks.math.columbia.edu/tag/07RH}{\texttt{Stacks tag 07RH}}
\group{algebra}

Let $A = \colim_{i \in I} A_i$ be a directed colimit of rings.
Let $0 \in I$ and $\varphi_0 : B_0 \to C_0$ a map of $A_0$-algebras.
Assume
\begin{enumerate}
\item $A \otimes_{A_0} B_0 \to A \otimes_{A_0} C_0$ is surjective,
\item $C_0$ is of finite type over $B_0$.
\end{enumerate}
Then for some $i \geq 0$ the map
$A_i \otimes_{A_0} B_0 \to A_i \otimes_{A_0} C_0$
is surjective.
\end{lemma}

\begin{proof}
Let $x_1, \ldots, x_m$ be generators for $C_0$ over $B_0$.
Pick $b_j \in A \otimes_{A_0} B_0$ mapping to $1 \otimes x_j$ in
$A \otimes_{A_0} C_0$. For some $i \geq 0$ we can find
$b_{j, i} \in A_i \otimes_{A_0} B_0$ mapping to $b_j$.
After increasing $i$ we may assume that $b_{j, i}$ maps
to $1 \otimes x_j$ in $A_i \otimes_{A_0} C_0$ for all $j = 1, \ldots, m$.
Then this $i$ works.
\end{proof}

\begin{lemma}[Colimit unramified]
\label{algebra-lemma-colimit-unramified}
\source{stacks:0C4F}
\href{https://stacks.math.columbia.edu/tag/0C4F}{\texttt{Stacks tag 0C4F}}
\group{algebra}

Let $A = \colim_{i \in I} A_i$ be a directed colimit of rings.
Let $0 \in I$ and $\varphi_0 : B_0 \to C_0$ a map of $A_0$-algebras.
Assume
\begin{enumerate}
\item $A \otimes_{A_0} B_0 \to A \otimes_{A_0} C_0$ is unramified,
\item $C_0$ is of finite type over $B_0$.
\end{enumerate}
Then for some $i \geq 0$ the map
$A_i \otimes_{A_0} B_0 \to A_i \otimes_{A_0} C_0$
is unramified.
\end{lemma}

\begin{proof}
\uses{algebra-lemma-differentials-polynomial-ring, algebra-lemma-differential-seq, algebra-lemma-colimit-differentials}

Set $B_i = A_i \otimes_{A_0} B_0$, $C_i = A_i \otimes_{A_0} C_0$,
$B = A \otimes_{A_0} B_0$, and $C = A \otimes_{A_0} C_0$.
Let $x_1, \ldots, x_m$ be generators for $C_0$ over $B_0$.
Then $\text{d}x_1, \ldots, \text{d}x_m$ generate $\Omega_{C_0/B_0}$
over $C_0$ and their images generate $\Omega_{C_i/B_i}$ over $C_i$
(Lemmas \ref{algebra-lemma-differentials-polynomial-ring} and
\ref{algebra-lemma-differential-seq}).
Observe that $0 = \Omega_{C/B} = \colim \Omega_{C_i/B_i}$
(Lemma \ref{algebra-lemma-colimit-differentials}).
Thus there is an $i$ such that $\text{d}x_1, \ldots, \text{d}x_m$
map to zero and hence $\Omega_{C_i/B_i} = 0$ as desired.
\end{proof}

\begin{lemma}[Colimit isomorphism]
\label{algebra-lemma-colimit-isomorphism}
\source{stacks:0C32}
\href{https://stacks.math.columbia.edu/tag/0C32}{\texttt{Stacks tag 0C32}}
\group{algebra}

Let $A = \colim_{i \in I} A_i$ be a directed colimit of rings.
Let $0 \in I$ and $\varphi_0 : B_0 \to C_0$ a map of $A_0$-algebras.
Assume
\begin{enumerate}
\item $A \otimes_{A_0} B_0 \to A \otimes_{A_0} C_0$ is
an isomorphism,
\item $B_0 \to C_0$ is of finite presentation.
\end{enumerate}
Then for some $i \geq 0$ the map
$A_i \otimes_{A_0} B_0 \to A_i \otimes_{A_0} C_0$ is
an isomorphism.
\end{lemma}

\begin{proof}
\uses{algebra-lemma-colimit-surjective}

By Lemma \ref{algebra-lemma-colimit-surjective} there exists an $i$ such that
$A_i \otimes_{A_0} B_0 \to A_i \otimes_{A_0} C_0$ is
surjective. Since the map is of finite presentation
the kernel is a finitely generated ideal. Let
$g_1, \ldots, g_r \in A_i \otimes_{A_0} B_0$ generate the kernel.
Then we may pick $i' \geq i$ such that $g_j$ map to zero
in $A_{i'} \otimes_{A_0} B_0$. Then
$A_{i'} \otimes_{A_0} B_0 \to A_{i'} \otimes_{A_0} C_0$ is
an isomorphism.
\end{proof}

\begin{lemma}[Colimit etale]
\label{algebra-lemma-colimit-etale}
\source{stacks:07RI}
\href{https://stacks.math.columbia.edu/tag/07RI}{\texttt{Stacks tag 07RI}}
\group{algebra}

Let $A = \colim_{i \in I} A_i$ be a directed colimit of rings.
Let $0 \in I$ and $\varphi_0 : B_0 \to C_0$ a map of $A_0$-algebras.
Assume
\begin{enumerate}
\item $A \otimes_{A_0} B_0 \to A \otimes_{A_0} C_0$ is \'etale,
\item $B_0 \to C_0$ is of finite presentation.
\end{enumerate}
Then for some $i \geq 0$ the map
$A_i \otimes_{A_0} B_0 \to A_i \otimes_{A_0} C_0$
is \'etale.
\end{lemma}

\begin{proof}
Write $C_0 = B_0[x_1, \ldots, x_n]/(f_{1, 0}, \ldots, f_{m, 0})$.
Write $B_i = A_i \otimes_{A_0} B_0$ and $C_i = A_i \otimes_{A_0} C_0$.
Note that $C_i = B_i[x_1, \ldots, x_n]/(f_{1, i}, \ldots, f_{m, i})$
where $f_{j, i}$ is the image of $f_{j, 0}$ in the polynomial ring
over $B_i$. Write $B = A \otimes_{A_0} B_0$ and $C = A \otimes_{A_0} C_0$.
Note that $C = B[x_1, \ldots, x_n]/(f_1, \ldots, f_m)$
where $f_j$ is the image of $f_{j, 0}$ in the polynomial ring
over $B$. The assumption is that the map
$$
\text{d} :
(f_1, \ldots, f_m)/(f_1, \ldots, f_m)^2
\longrightarrow
\bigoplus C \text{d}x_k
$$
is an isomorphism. Thus for sufficiently large $i$ we can find elements
$$
\xi_{k, i} \in (f_{1, i}, \ldots, f_{m, i})/(f_{1, i}, \ldots, f_{m, i})^2
$$
with $\text{d}\xi_{k, i} = \text{d}x_k$ in $\bigoplus C_i \text{d}x_k$.
Moreover, on increasing $i$ if necessary, we see that
$\sum (\partial f_{j, i}/\partial x_k) \xi_{k, i} =
f_{j, i} \bmod (f_{1, i}, \ldots, f_{m, i})^2$
since this is true in the limit. Then this $i$ works.
\end{proof}

\begin{lemma}[Colimit smooth]
\label{algebra-lemma-colimit-smooth}
\source{stacks:0C0B}
\href{https://stacks.math.columbia.edu/tag/0C0B}{\texttt{Stacks tag 0C0B}}
\group{algebra}

Let $A = \colim_{i \in I} A_i$ be a directed colimit of rings.
Let $0 \in I$ and $\varphi_0 : B_0 \to C_0$ a map of $A_0$-algebras.
Assume
\begin{enumerate}
\item $A \otimes_{A_0} B_0 \to A \otimes_{A_0} C_0$ is smooth,
\item $B_0 \to C_0$ is of finite presentation.
\end{enumerate}
Then for some $i \geq 0$ the map
$A_i \otimes_{A_0} B_0 \to A_i \otimes_{A_0} C_0$ is smooth.
\end{lemma}

\begin{proof}
Write $C_0 = B_0[x_1, \ldots, x_n]/(f_{1, 0}, \ldots, f_{m, 0})$.
Write $B_i = A_i \otimes_{A_0} B_0$ and $C_i = A_i \otimes_{A_0} C_0$.
Note that $C_i = B_i[x_1, \ldots, x_n]/(f_{1, i}, \ldots, f_{m, i})$
where $f_{j, i}$ is the image of $f_{j, 0}$ in the polynomial ring
over $B_i$. Write $B = A \otimes_{A_0} B_0$ and $C = A \otimes_{A_0} C_0$.
Note that $C = B[x_1, \ldots, x_n]/(f_1, \ldots, f_m)$
where $f_j$ is the image of $f_{j, 0}$ in the polynomial ring
over $B$. The assumption is that the map
$$
\text{d} :
(f_1, \ldots, f_m)/(f_1, \ldots, f_m)^2
\longrightarrow
\bigoplus C \text{d}x_k
$$
is a split injection. Let $\xi_k \in (f_1, \ldots, f_m)/(f_1, \ldots, f_m)^2$
be elements such that $\sum (\partial f_j/\partial x_k) \xi_k =
f_j \bmod (f_1, \ldots, f_m)^2$. Then for sufficiently large $i$ we can
find elements
$$
\xi_{k, i} \in (f_{1, i}, \ldots, f_{m, i})/(f_{1, i}, \ldots, f_{m, i})^2
$$
with $\sum (\partial f_{j, i}/\partial x_k) \xi_{k, i} =
f_{j, i} \bmod (f_{1, i}, \ldots, f_{m, i})^2$
since this is true in the limit. Then this $i$ works.
\end{proof}

\begin{lemma}[Colimit lci]
\label{algebra-lemma-colimit-lci}
\source{stacks:0C33}
\href{https://stacks.math.columbia.edu/tag/0C33}{\texttt{Stacks tag 0C33}}
\group{algebra}

Let $A = \colim_{i \in I} A_i$ be a directed colimit of rings.
Let $0 \in I$ and $\varphi_0 : B_0 \to C_0$ a map of $A_0$-algebras.
Assume
\begin{enumerate}
\item $A \otimes_{A_0} B_0 \to A \otimes_{A_0} C_0$ is
syntomic (resp.\ a relative global complete intersection),
\item $C_0$ is of finite presentation over $B_0$.
\end{enumerate}
Then there exists an $i \geq 0$ such that the map
$A_i \otimes_{A_0} B_0 \to A_i \otimes_{A_0} C_0$
is syntomic (resp.\ a relative global complete intersection).
\end{lemma}

\begin{proof}
\uses{algebra-lemma-relative-global-complete-intersection-Noetherian, algebra-lemma-characterize-finite-presentation, algebra-lemma-colimit-isomorphism, algebra-lemma-base-change-relative-global-complete-intersection, algebra-lemma-syntomic, algebra-lemma-local-syntomic}

Assume $A \otimes_{A_0} B_0 \to A \otimes_{A_0} C_0$ is a relative
global complete intersection.
By Lemma \ref{algebra-lemma-relative-global-complete-intersection-Noetherian}
there exists a finite type $\mathbf{Z}$-algebra $R$,
a ring map $R \to A \otimes_{A_0} B_0$, a relative
global complete intersection $R \to S$, and an isomorphism
$$
(A \otimes_{A_0} B_0) \otimes_R S
\longrightarrow
A \otimes_{A_0} C_0
$$
Because $R$ is of finite type (and hence finite presentation)
over $\mathbf{Z}$, there exists an $i$ and a map
$R \to A_i \otimes_{A_0} B_0$ lifting the map $R \to A \otimes_{A_0} B_0$,
see Lemma \ref{algebra-lemma-characterize-finite-presentation}.
Using the same lemma, there exists an $i' \geq i$ such that
$(A_i \otimes_{A_0} B_0) \otimes_R S \to A \otimes_{A_0} C_0$
comes from a map
$(A_i \otimes_{A_0} B_0) \otimes_R S \to A_{i'} \otimes_{A_0} C_0$.
Thus we may assume, after replacing $i$ by $i'$,
that the displayed map comes from an $A_i \otimes_{A_0} B_0$-algebra map
$$
(A_i \otimes_{A_0} B_0) \otimes_R S
\longrightarrow
A_i \otimes_{A_0} C_0
$$
By Lemma \ref{algebra-lemma-colimit-isomorphism} after increasing $i$ this
map is an isomorphism. This finishes the proof in this case because the base
change of a relative global complete intersection is a relative
global complete intersection by
Lemma \ref{algebra-lemma-base-change-relative-global-complete-intersection}.

\medskip\noindent
Assume $A \otimes_{A_0} B_0 \to A \otimes_{A_0} C_0$ is syntomic.
Then there exist elements $g_1, \ldots, g_m$ in
$A \otimes_{A_0} C_0$ generating the unit ideal such that
$A \otimes_{A_0} B_0 \to (A \otimes_{A_0} C_0)_{g_j}$ is a
relative global complete intersection, see Lemma \ref{algebra-lemma-syntomic}.
We can find an $i$ and elements $g_{i, j} \in A_i \otimes_{A_0} C_0$
mapping to $g_j$. After increasing $i$ we may assume
$g_{i, 1}, \ldots, g_{i, m}$ generate the unit ideal
of $A_i \otimes_{A_0} C_0$. The result of the previous paragraph
implies that, after increasing $i$, we may assume the maps
$A_i \otimes_{A_0} B_0 \to (A_i \otimes_{A_0} C_0)_{g_{i, j}}$
are relative global complete intersections.
Then $A_i \otimes_{A_0} B_0 \to A_i \otimes_{A_0} C_0$
is syntomic by Lemma \ref{algebra-lemma-local-syntomic}
(and the already used Lemma \ref{algebra-lemma-syntomic}).
\end{proof}


The following lemma is an application of the results above
which doesn't seem to fit well anywhere else.

\begin{lemma}[Fppf fpqf]
\label{algebra-lemma-fppf-fpqf}
\source{stacks:034Z}
\href{https://stacks.math.columbia.edu/tag/034Z}{\texttt{Stacks tag 034Z}}
\group{algebra}

Let $R \to S$ be a faithfully flat ring map of finite presentation.
Then there exists a commutative diagram
$$
\begin{array}{ccc}S \longrightarrow &  & S' \\  & R \nwarrow\nearrow & \end{array}
$$
where $R \to S'$ is quasi-finite, faithfully flat and of finite presentation.
\end{lemma}

\begin{proof}
\uses{algebra-lemma-descend-faithfully-flat-finite-presentation, algebra-lemma-quasi-finite-base-change, algebra-lemma-finite-presentation-flat-CM-locus-open, algebra-lemma-ff-rings, algebra-lemma-generic-CM-flat-finite-presentation, algebra-lemma-quasi-compact, algebra-proposition-fppf-open, algebra-lemma-isolated-point-fibre, algebra-lemma-grothendieck-regular-sequence, algebra-theorem-openness-flatness, algebra-lemma-quasi-finite-open}

As a first step we reduce this lemma to the case where $R$ is of finite
type over $\mathbf{Z}$.
By Lemma \ref{algebra-lemma-descend-faithfully-flat-finite-presentation}
there exists a diagram
$$
\begin{array}{cc}S_0 \longrightarrow & S \\ R_0 \uparrow\longrightarrow & R \uparrow\end{array}
$$
where $R_0$ is of finite type over $\mathbf{Z}$,
and $S_0$ is faithfully flat of finite presentation over $R_0$
such that $S = R \otimes_{R_0} S_0$.
If we prove the lemma for the ring map $R_0 \to S_0$, then the lemma
follows for $R \to S$ by base change, as the base change of
a quasi-finite ring map is quasi-finite, see
Lemma \ref{algebra-lemma-quasi-finite-base-change}. (Of course we
also use that base changes of flat maps are flat and
base changes of maps of finite presentation are of finite presentation.)

\medskip\noindent
Assume $R \to S$ is a faithfully flat ring map of finite presentation
and that $R$ is Noetherian (which we may assume by the preceding
paragraph). Let $W \subset \Spec(S)$ be the open set of
Lemma \ref{algebra-lemma-finite-presentation-flat-CM-locus-open}.
As $R \to S$ is faithfully flat the map $\Spec(S) \to \Spec(R)$
is surjective, see Lemma \ref{algebra-lemma-ff-rings}.
By Lemma \ref{algebra-lemma-generic-CM-flat-finite-presentation}
the map $W \to \Spec(R)$ is also surjective.
Hence by replacing $S$ with a product $S_{g_1} \times \ldots \times S_{g_m}$
we may assume $W = \Spec(S)$; here we use that $\Spec(R)$
is quasi-compact (Lemma \ref{algebra-lemma-quasi-compact}), and that the map
$\Spec(S) \to \Spec(R)$ is open
(Proposition \ref{algebra-proposition-fppf-open}).
Suppose that $\mathfrak p \subset R$ is a prime. Choose a prime
$\mathfrak q \subset S$ lying over $\mathfrak p$ which corresponds
to a maximal ideal of the fibre ring $S \otimes_R \kappa(\mathfrak p)$.
The Noetherian local ring
$\overline{S}_{\mathfrak q} = S_{\mathfrak q}/\mathfrak pS_{\mathfrak q}$
is Cohen-Macaulay, say of dimension $d$. We may choose $f_1, \ldots, f_d$
in the maximal ideal of $S_{\mathfrak q}$ which map to a regular sequence
in $\overline{S}_{\mathfrak q}$. Choose a common denominator
$g \in S$, $g \not \in \mathfrak q$ of $f_1, \ldots, f_d$, and consider
the $R$-algebra
$$
S' = S_g/(f_1, \ldots, f_d).
$$
By construction there is a prime ideal $\mathfrak q' \subset S'$
lying over $\mathfrak p$ and corresponding to $\mathfrak q$ (via
$S_g \to S'_g$). Also by construction the ring map $R \to S'$ is
quasi-finite at $\mathfrak q$ as the local ring
$$
S'_{\mathfrak q'}/\mathfrak pS'_{\mathfrak q'} =
S_{\mathfrak q}/(f_1, \ldots, f_d) + \mathfrak pS_{\mathfrak q} =
\overline{S}_{\mathfrak q}/(\overline{f}_1, \ldots, \overline{f}_d)
$$
has dimension zero, see Lemma \ref{algebra-lemma-isolated-point-fibre}.
Also by construction $R \to S'$ is of finite presentation.
Finally, by Lemma \ref{algebra-lemma-grothendieck-regular-sequence} the local ring map
$R_{\mathfrak p} \to S'_{\mathfrak q'}$ is flat (this is where we
use that $R$ is Noetherian). Hence, by openness of flatness
(Theorem \ref{algebra-theorem-openness-flatness}), and openness of quasi-finiteness
(Lemma \ref{algebra-lemma-quasi-finite-open})
we may after replacing
$g$ by $gg'$ for a suitable $g' \in S$, $g' \not \in \mathfrak q$
assume that $R \to S'$ is flat and quasi-finite.
The image $\Spec(S') \to \Spec(R)$ is open and
contains $\mathfrak p$. In other words we have shown
a ring $S'$ as in the statement of the lemma exists (except possibly
the faithfulness part) whose image contains any given prime.
Using one more time the quasi-compactness of $\Spec(R)$
we see that a finite product of such rings does the job.
\end{proof}

\label{chap:brauer}
\section{Introduction}
\label{brauer-section-introduction}
A reference is the lectures by Serre in the Seminaire Cartan, see
\cite{Serre-Cartan}. Serre in turn refers to
\cite{Deuring} and \cite{ANT}. We changed some of the proofs, in particular
we used a fun argument of Rieffel to prove Wedderburn's theorem.
Very likely this change is not an improvement and we strongly
encourage the reader to read the original exposition by Serre.

\section{Noncommutative algebras}
\label{brauer-section-algebras}
Let $k$ be a field. In this chapter an {\it algebra} $A$ over $k$ is
a possibly noncommutative ring $A$ together with a ring map
$k \to A$ such that $k$ maps into the center of $A$ and such that
$1$ maps to an identity element of $A$. An {\it $A$-module} is a right
$A$-module such that the identity of $A$ acts as the identity.

\begin{definition}[Finite]
\label{brauer-definition-finite}
\source{stacks:073Z}
\href{https://stacks.math.columbia.edu/tag/073Z}{\texttt{Stacks tag 073Z}}
\group{brauer}

Let $A$ be a $k$-algebra. We say $A$ is {\it finite} if $\dim_k(A) < \infty$.
In this case we write $[A : k] = \dim_k(A)$.
\end{definition}

\begin{definition}[Skew field]
\label{brauer-definition-skew-field}
\source{stacks:0740}
\href{https://stacks.math.columbia.edu/tag/0740}{\texttt{Stacks tag 0740}}
\group{brauer}

A {\it skew field} is a possibly noncommutative ring with an identity
element $1$, with $1 \not = 0$, in which every nonzero element
has a multiplicative inverse.
\end{definition}

A skew field is a $k$-algebra for some $k$ (e.g., for the prime field
contained in it). We will use below that any module over a skew field
is free because a maximal linearly independent set of vectors forms a
basis and exists by Zorn's lemma.

\begin{definition}[Simple]
\label{brauer-definition-simple}
\source{stacks:0741}
\href{https://stacks.math.columbia.edu/tag/0741}{\texttt{Stacks tag 0741}}
\group{brauer}

Let $A$ be a $k$-algebra.
We say an $A$-module $M$ is {\it simple} if it is nonzero and
the only $A$-submodules are $0$ and $M$.
We say $A$ is {\it simple} if the only two-sided ideals of $A$ are
$0$ and $A$.
\end{definition}

\begin{definition}[Central]
\label{brauer-definition-central}
\source{stacks:0742}
\href{https://stacks.math.columbia.edu/tag/0742}{\texttt{Stacks tag 0742}}
\group{brauer}

A $k$-algebra $A$ is {\it central} if the center of $A$ is the image of
$k \to A$.
\end{definition}

\begin{definition}[Opposite]
\label{brauer-definition-opposite}
\source{stacks:0743}
\href{https://stacks.math.columbia.edu/tag/0743}{\texttt{Stacks tag 0743}}
\group{brauer}

Given a $k$-algebra $A$ we denote $A^{op}$ the $k$-algebra we get by
reversing the order of multiplication in $A$. This is called the
{\it opposite algebra}.
\end{definition}

\section{Wedderburn's theorem}
\label{brauer-section-wedderburn}
The following cute argument can be found in a paper of Rieffel, see
\cite{Rieffel}. The proof could not be simpler (quote from
Carl Faith's review).

\begin{lemma}[Rieffel]
\label{brauer-lemma-rieffel}
\source{stacks:0745}
\href{https://stacks.math.columbia.edu/tag/0745}{\texttt{Stacks tag 0745}}
\group{brauer}

Let $A$ be a possibly noncommutative ring with $1$ which contains no
nontrivial two-sided ideal. Let $M$ be a nonzero right ideal in $A$,
and view $M$ as a right $A$-module. Then $A$ coincides with the
bicommutant of $M$.
\end{lemma}

\begin{proof}
Let $A' = \text{End}_A(M)$, so $M$ is a left $A'$-module.
Set $A'' = \text{End}_{A'}(M)$ (the bicommutant of $M$).
We view $M$ as a right $A''$-module\footnote{This
means that given $a'' \in A''$ and $m \in M$ we have a product
$m a'' \in M$. In particular, the multiplication in $A''$
is the opposite of what you'd get if you wrote elements of $A''$
as endomorphisms acting on the left.}.
Let $R : A \to A''$ be the natural homomorphism such that
$mR(a) = ma$. Then $R$ is injective, since $R(1) = \text{id}_M$
and $A$ contains no nontrivial two-sided ideal. We claim that $R(M)$
is a right ideal in $A''$. Namely, $R(m)a'' = R(ma'')$ for $a'' \in A''$
and $m$ in $M$, because {\it left} multiplication of $M$ by any element $n$
of $M$ represents an element of $A'$, and so
$(nm)a'' = n(ma'')$ for all $n$ in $M$.
Finally, the product ideal $AM$ is a two-sided ideal, and so
$A = AM$. Thus $R(A) = R(A)R(M)$, so that $R(A)$ is a right ideal in $A''$.
But $R(A)$ contains the identity element of $A''$, and so $R(A) = A''$.
\end{proof}

\begin{lemma}[Simple module]
\label{brauer-lemma-simple-module}
\source{stacks:0746}
\href{https://stacks.math.columbia.edu/tag/0746}{\texttt{Stacks tag 0746}}
\group{brauer}

Let $A$ be a $k$-algebra. If $A$ is finite, then
\begin{enumerate}
\item $A$ has a simple module,
\item any nonzero module contains a simple submodule,
\item a simple module over $A$ has finite dimension over $k$, and
\item if $M$ is a simple $A$-module, then $\text{End}_A(M)$ is a
skew field.
\end{enumerate}
\end{lemma}

\begin{proof}
Of course (1) follows from (2) since $A$ is a nonzero $A$-module.
For (2), any submodule of minimal (finite) dimension as a $k$-vector
space will be simple. There exists a finite dimensional one
because a cyclic submodule is one. If $M$ is simple, then
$mA \subset M$ is a sub-module, hence we see (3). Any nonzero element
of $\text{End}_A(M)$ is an isomorphism, hence (4) holds.
\end{proof}

\begin{theorem}[Simple finite algebras over a field are matrix algebras over a skew field.]
\label{brauer-theorem-wedderburn}
\source{stacks:0747}
\href{https://stacks.math.columbia.edu/tag/0747}{\texttt{Stacks tag 0747}}
\group{brauer}


Let $A$ be a simple finite $k$-algebra. Then $A$ is a matrix algebra over
a finite $k$-algebra $K$ which is a skew field.
\end{theorem}

\begin{proof}
\uses{brauer-lemma-simple-module, brauer-lemma-rieffel}

We may choose a simple submodule $M \subset A$ and then
the $k$-algebra $K = \text{End}_A(M)$ is a skew field, see
Lemma \ref{brauer-lemma-simple-module}.
By
Lemma \ref{brauer-lemma-rieffel}
we see that $A = \text{End}_K(M)$. Since $K$ is a skew field and
$M$ is finitely generated (since $\dim_k(M) < \infty$) we see that
$M$ is finite free as a left $K$-module. It follows immediately that
$A \cong \text{Mat}(n \times n, K^{op})$.
\end{proof}

\section{Lemmas on algebras}
\label{brauer-section-lemmas}
Let $A$ be a $k$-algebra. Let $B \subset A$ be a subalgebra.
The {\it centralizer of $B$ in $A$} is the subalgebra
$$
C  = \{y \in A \mid xy = yx \text{ for all }x \in B\}.
$$
It is a $k$-algebra.

\begin{lemma}[Centralizer]
\label{brauer-lemma-centralizer}
\source{stacks:0749}
\href{https://stacks.math.columbia.edu/tag/0749}{\texttt{Stacks tag 0749}}
\group{brauer}

Let $A$, $A'$ be $k$-algebras. Let $B \subset A$, $B' \subset A'$ be
subalgebras with centralizers $C$, $C'$. Then the centralizer of
$B \otimes_k B'$ in $A \otimes_k A'$ is $C \otimes_k C'$.
\end{lemma}

\begin{proof}
Denote $C'' \subset A \otimes_k A'$ the centralizer of $B \otimes_k B'$.
It is clear that $C \otimes_k C' \subset C''$. Conversely, every element
of $C''$ commutes with $B \otimes 1$ hence is contained in $C \otimes_k A'$.
Similarly $C'' \subset A \otimes_k C'$. Thus
$C'' \subset C \otimes_k A' \cap A \otimes_k C' = C \otimes_k C'$.
\end{proof}

\begin{lemma}[Center csa]
\label{brauer-lemma-center-csa}
\source{stacks:074A}
\href{https://stacks.math.columbia.edu/tag/074A}{\texttt{Stacks tag 074A}}
\group{brauer}

Let $A$ be a finite simple $k$-algebra. Then the center $k'$ of $A$
is a finite field extension of $k$.
\end{lemma}

\begin{proof}
\uses{brauer-theorem-wedderburn, brauer-lemma-centralizer}

Write $A = \text{Mat}(n \times n, K)$ for some skew field $K$ finite
over $k$, see
Theorem \ref{brauer-theorem-wedderburn}.
By
Lemma \ref{brauer-lemma-centralizer}
the center of $A$ is $k \otimes_k k'$ where $k' \subset K$ is the
center of $K$. Since the center of a skew field is a field, we win.
\end{proof}

\begin{lemma}[Generate two sided sub]
\label{brauer-lemma-generate-two-sided-sub}
\source{stacks:074B}
\href{https://stacks.math.columbia.edu/tag/074B}{\texttt{Stacks tag 074B}}
\group{brauer}

Let $V$ be a $k$ vector space. Let $K$ be a central $k$-algebra
which is a skew field. Let $W \subset V \otimes_k K$ be a two-sided
$K$-sub vector space. Then $W$ is generated as a left $K$-vector
space by $W \cap (V \otimes 1)$.
\end{lemma}

\begin{proof}
Let $V' \subset V$ be the $k$-sub vector space generated by $v \in V$
such that $v \otimes 1 \in W$. Then $V' \otimes_k K \subset W$ and
we have
$$
W/(V' \otimes_k K)  \subset  (V/V') \otimes_k K.
$$
If $\overline{v} \in V/V'$ is a nonzero vector such that
$\overline{v} \otimes 1$ is contained in $W/(V' \otimes_k K)$,
then we see that $v \otimes 1 \in W$ where $v \in V$ lifts $\overline{v}$.
This contradicts our construction of $V'$. Hence we may replace
$V$ by $V/V'$ and $W$ by $W/(V' \otimes_k K)$ and it suffices to prove
that $W \cap (V \otimes 1)$ is nonzero if $W$ is nonzero.

\medskip\noindent
To see this let $w \in W$ be a nonzero element which can be written
as $w = \sum_{i = 1, \ldots, n} v_i \otimes k_i$ with $n$ minimal.
We may right multiply with $k_1^{-1}$ and assume that $k_1 = 1$.
If $n = 1$, then we win because $v_1 \otimes 1 \in W$.
If $n > 1$, then we see that for any $c \in K$
$$
c w - w c = \sum\nolimits_{i = 2, \ldots, n} v_i \otimes (c k_i - k_i c) \in W
$$
and hence $c k_i - k_i c = 0$ by minimality of $n$.
This implies that $k_i$ is in the center of $K$ which is $k$ by
assumption. Hence $w = (v_1 + \sum k_i v_i) \otimes 1$ contradicting
the minimality of $n$.
\end{proof}

\begin{lemma}[Generate two sided ideal]
\label{brauer-lemma-generate-two-sided-ideal}
\source{stacks:074C}
\href{https://stacks.math.columbia.edu/tag/074C}{\texttt{Stacks tag 074C}}
\group{brauer}

Let $A$ be a $k$-algebra. Let $K$ be a central $k$-algebra
which is a skew field. Then any two-sided ideal $I \subset A \otimes_k K$
is of the form $J \otimes_k K$ for some two-sided ideal $J \subset A$.
In particular, if $A$ is simple, then so is $A \otimes_k K$.
\end{lemma}

\begin{proof}
\uses{brauer-lemma-generate-two-sided-sub}

Set $J = \{a \in A \mid a \otimes 1 \in I\}$. This is a two-sided ideal
of $A$. And $I = J \otimes_k K$ by
Lemma \ref{brauer-lemma-generate-two-sided-sub}.
\end{proof}

\begin{lemma}[Matrix algebras]
\label{brauer-lemma-matrix-algebras}
\source{stacks:074D}
\href{https://stacks.math.columbia.edu/tag/074D}{\texttt{Stacks tag 074D}}
\group{brauer}

Let $R$ be a possibly noncommutative ring. Let $n \geq 1$ be an integer.
Let $R_n = \text{Mat}(n \times n, R)$.
\begin{enumerate}
\item The functors $M \mapsto M^{\oplus n}$ and
$N \mapsto Ne_{11}$ define quasi-inverse equivalences of categories
$\text{Mod}_R \leftrightarrow \text{Mod}_{R_n}$.
\item A two-sided ideal of $R_n$ is of the form $IR_n$ for some
two-sided ideal $I$ of $R$.
\item The center of $R_n$ is equal to the center of $R$.
\end{enumerate}
\end{lemma}

\begin{proof}
Part (1) proves itself. If $J \subset R_n$ is a two-sided ideal, then
$J = \bigoplus e_{ii}Je_{jj}$ and all of the summands $e_{ii}Je_{jj}$ are
equal to each other and are a two-sided ideal $I$ of $R$. This proves (2).
Part (3) is clear.
\end{proof}

\begin{lemma}[Simple module unique]
\label{brauer-lemma-simple-module-unique}
\source{stacks:074E}
\href{https://stacks.math.columbia.edu/tag/074E}{\texttt{Stacks tag 074E}}
\group{brauer}

Let $A$ be a finite simple $k$-algebra.
\begin{enumerate}
\item There exists exactly one simple $A$-module $M$ up to isomorphism.
\item Any finite $A$-module is a direct sum of copies of a simple module.
\item Two finite $A$-modules are isomorphic if and only if they
have the same dimension over $k$.
\item If $A = \text{Mat}(n \times n, K)$ with $K$ a finite skew field
extension of $k$, then $M = K^{\oplus n}$ is a simple $A$-module and
$\text{End}_A(M) = K^{op}$.
\item If $M$ is a simple $A$-module, then $L = \text{End}_A(M)$
is a skew field finite over $k$ acting on the left on $M$, we have
$A = \text{End}_L(M)$, and the centers of $A$ and $L$ agree.
Also $[A : k] [L : k] = \dim_k(M)^2$.
\item For a finite $A$-module $N$ the algebra $B = \text{End}_A(N)$ is a
matrix algebra over the skew field $L$ of (5). Moreover $\text{End}_B(N) = A$.
\end{enumerate}
\end{lemma}

\begin{proof}
\uses{brauer-theorem-wedderburn, brauer-lemma-matrix-algebras}

By
Theorem \ref{brauer-theorem-wedderburn}
we can write $A = \text{Mat}(n \times n, K)$ for some finite skew
field extension $K$ of $k$. By
Lemma \ref{brauer-lemma-matrix-algebras}
the category of modules over $A$ is equivalent to the category of
modules over $K$. Thus (1), (2), and (3) hold
because every module over $K$ is free. Part (4) holds
because the equivalence transforms the $K$-module $K$
to $M = K^{\oplus n}$. Using $M = K^{\oplus n}$ in (5)
we see that $L = K^{op}$. The statement about the center of $L = K^{op}$
follows from
Lemma \ref{brauer-lemma-matrix-algebras}.
The statement about $\text{End}_L(M)$ follows from the explicit form
of $M$. The formula of dimensions is clear.
Part (6) follows as $N$ is isomorphic to a direct sum of
copies of a simple module.
\end{proof}

\begin{lemma}[Tensor simple]
\label{brauer-lemma-tensor-simple}
\source{stacks:074F}
\href{https://stacks.math.columbia.edu/tag/074F}{\texttt{Stacks tag 074F}}
\group{brauer}

Let $A$, $A'$ be two simple $k$-algebras one of which is finite and central
over $k$. Then $A \otimes_k A'$ is simple.
\end{lemma}

\begin{proof}
\uses{brauer-theorem-wedderburn, brauer-lemma-generate-two-sided-ideal, brauer-lemma-matrix-algebras}

Suppose that $A'$ is finite and central over $k$.
Write $A' = \text{Mat}(n \times n, K')$, see
Theorem \ref{brauer-theorem-wedderburn}.
Then the center of $K'$ is $k$ and we conclude that
$A \otimes_k K'$ is simple by
Lemma \ref{brauer-lemma-generate-two-sided-ideal}.
Hence $A \otimes_k A' = \text{Mat}(n \times n, A \otimes_k K')$ is simple
by Lemma \ref{brauer-lemma-matrix-algebras}.
\end{proof}

\begin{lemma}[Tensor central simple]
\label{brauer-lemma-tensor-central-simple}
\source{stacks:074G}
\href{https://stacks.math.columbia.edu/tag/074G}{\texttt{Stacks tag 074G}}
\group{brauer}

The tensor product of finite central simple algebras over $k$ is finite,
central, and simple.
\end{lemma}

\begin{proof}
\uses{brauer-lemma-centralizer, brauer-lemma-tensor-simple}

Combine Lemmas \ref{brauer-lemma-centralizer} and \ref{brauer-lemma-tensor-simple}.
\end{proof}

\begin{lemma}[Base change]
\label{brauer-lemma-base-change}
\source{stacks:074H}
\href{https://stacks.math.columbia.edu/tag/074H}{\texttt{Stacks tag 074H}}
\group{brauer}

Let $A$ be a finite central simple algebra over $k$.
Let $k'/k$ be a field extension. Then $A' = A \otimes_k k'$ is
a finite central simple algebra over $k'$.
\end{lemma}

\begin{proof}
\uses{brauer-lemma-centralizer, brauer-lemma-tensor-simple}

Combine Lemmas \ref{brauer-lemma-centralizer} and \ref{brauer-lemma-tensor-simple}.
\end{proof}

\begin{lemma}[Inverse]
\label{brauer-lemma-inverse}
\source{stacks:074I}
\href{https://stacks.math.columbia.edu/tag/074I}{\texttt{Stacks tag 074I}}
\group{brauer}

Let $A$ be a finite central simple algebra over $k$.
Then $A \otimes_k A^{op} \cong \text{Mat}(n \times n, k)$
where $n = [A : k]$.
\end{lemma}

\begin{proof}
\uses{brauer-lemma-tensor-central-simple}

By Lemma \ref{brauer-lemma-tensor-central-simple} the algebra $A \otimes_k A^{op}$
is simple. Hence the map
$$
A \otimes_k A^{op} \longrightarrow \text{End}_k(A),\quad
a \otimes a' \longmapsto (x \mapsto axa')
$$
is injective. Since both sides of the arrow have the same dimension
we win.
\end{proof}

\section{The Brauer group of a field}
\label{brauer-section-brauer}
Let $k$ be a field. Consider two finite central simple algebras
$A$ and $B$ over $k$. We say $A$ and $B$ are {\it similar} if there
exist $n, m > 0$ such that
$\text{Mat}(n \times n, A) \cong \text{Mat}(m \times m, B)$
as $k$-algebras.

\begin{lemma}[Similar]
\label{brauer-lemma-similar}
\source{stacks:074K}
\href{https://stacks.math.columbia.edu/tag/074K}{\texttt{Stacks tag 074K}}
\group{brauer}

Similarity.
\begin{enumerate}
\item Similarity defines an equivalence relation on the set of isomorphism
classes of finite central simple algebras over $k$.
\item Every similarity class contains a unique (up to isomorphism)
finite central skew field extension of $k$.
\item If $A = \text{Mat}(n \times n, K)$ and $B = \text{Mat}(m \times m, K')$
for some finite central skew fields $K$, $K'$ over $k$
then $A$ and $B$ are similar if and only if $K \cong K'$ as $k$-algebras.
\end{enumerate}
\end{lemma}

\begin{proof}
\uses{brauer-theorem-wedderburn, brauer-lemma-simple-module-unique}

Note that by Wedderburn's theorem (Theorem \ref{brauer-theorem-wedderburn})
we can always write a finite central simple algebra as a matrix
algebra over a finite central skew field. Hence it suffices to prove
the third assertion. To see this it suffices to show that if
$A = \text{Mat}(n \times n, K) \cong \text{Mat}(m \times m, K') = B$
then $K \cong K'$. To see this note that for a simple module $M$ of $A$
we have $\text{End}_A(M) = K^{op}$, see
Lemma \ref{brauer-lemma-simple-module-unique}.
Hence $A \cong B$ implies $K^{op} \cong (K')^{op}$ and we win.
\end{proof}

Given two finite central simple $k$-algebras $A$, $B$ the tensor
product $A \otimes_k B$ is another, see
Lemma \ref{brauer-lemma-tensor-central-simple}.
Moreover if $A$ is similar to $A'$, then $A \otimes_k B$ is similar
to $A' \otimes_k B$ because tensor products and taking matrix
algebras commute. Hence tensor product defines an operation on
equivalence classes of finite central simple algebras which is clearly
associative and commutative. Finally,
Lemma \ref{brauer-lemma-inverse}
shows that $A \otimes_k A^{op}$ is isomorphic to a matrix algebra, i.e.,
that $A \otimes_k A^{op}$ is in the similarity class of $k$.
Thus we obtain an abelian group.

\begin{definition}[Brauer group]
\label{brauer-definition-brauer-group}
\source{stacks:074L}
\href{https://stacks.math.columbia.edu/tag/074L}{\texttt{Stacks tag 074L}}
\group{brauer}

Let $k$ be a field. The {\it Brauer group} of $k$ is the abelian group
of similarity classes of finite central simple $k$-algebras defined
above. Notation $\text{Br}(k)$.
\end{definition}

For any map of fields $k \to k'$ we obtain a group homomorphism
$$
\text{Br}(k) \longrightarrow \text{Br}(k'),\quad
A \longmapsto A \otimes_k k'
$$
see Lemma \ref{brauer-lemma-base-change}. In other words, $\text{Br}(-)$ is
a functor from the category of fields to the category of abelian groups.
Observe that the Brauer group
of a field is zero if and only if every finite central skew field
extension $k \subset K$ is trivial.

\begin{lemma}[Brauer algebraically closed]
\label{brauer-lemma-brauer-algebraically-closed}
\source{stacks:074M}
\href{https://stacks.math.columbia.edu/tag/074M}{\texttt{Stacks tag 074M}}
\group{brauer}

The Brauer group of an algebraically closed field is zero.
\end{lemma}

\begin{proof}
Let $k \subset K$ be a finite central skew field extension.
For any element $x \in K$ the subring $k[x] \subset K$ is a
commutative finite integral $k$-sub algebra, hence a field, see
Algebra, Lemma \ref{algebra-lemma-integral-over-field}.
Since $k$ is algebraically closed we conclude that
$k[x] = k$. Since $x$ was arbitrary we conclude $k = K$.
\end{proof}

\begin{lemma}[Dimension square]
\label{brauer-lemma-dimension-square}
\source{stacks:074N}
\href{https://stacks.math.columbia.edu/tag/074N}{\texttt{Stacks tag 074N}}
\group{brauer}

Let $A$ be a finite central simple algebra over a field $k$.
Then $[A : k]$ is a square.
\end{lemma}

\begin{proof}
\uses{brauer-lemma-brauer-algebraically-closed}

This is true because $A \otimes_k \overline{k}$ is a matrix
algebra over $\overline{k}$ by
Lemma \ref{brauer-lemma-brauer-algebraically-closed}.
\end{proof}

\section{Skolem-Noether}
\label{brauer-section-skolem-noether}
\begin{theorem}[Skolem noether]
\label{brauer-theorem-skolem-noether}
\source{stacks:074Q}
\href{https://stacks.math.columbia.edu/tag/074Q}{\texttt{Stacks tag 074Q}}
\group{brauer}

Let $A$ be a finite central simple $k$-algebra. Let $B$ be a simple
$k$-algebra. Let $f, g : B \to A$ be two $k$-algebra homomorphisms.
Then there exists an invertible element $x \in A$ such that
$f(b) = xg(b)x^{-1}$ for all $b \in B$.
\end{theorem}

\begin{proof}
\uses{brauer-lemma-simple-module, brauer-lemma-simple-module-unique, brauer-lemma-tensor-simple}

Choose a simple $A$-module $M$. Set $L = \text{End}_A(M)$.
Then $L$ is a skew field with center $k$ which acts on the left on $M$, see
Lemmas \ref{brauer-lemma-simple-module} and \ref{brauer-lemma-simple-module-unique}.
Then $M$ has two $B \otimes_k L^{op}$-module structures defined by
$m \cdot_1 (b \otimes l) = lmf(b)$ and $m \cdot_2 (b \otimes l) = lmg(b)$.
The $k$-algebra $B \otimes_k L^{op}$ is simple by
Lemma \ref{brauer-lemma-tensor-simple}. Since $B$ is simple, the existence of a
$k$-algebra homomorphism $B \to A$ implies that $B$ is finite. Thus
$B \otimes_k L^{op}$ is finite simple and we conclude the two
$B \otimes_k L^{op}$-module structures on $M$
are isomorphic by Lemma \ref{brauer-lemma-simple-module-unique}.
Hence we find $\varphi : M \to M$ intertwining these operations.
In particular $\varphi$ is in the commutant of $L$ which implies that
$\varphi$ is multiplication by some $x \in A$, see
Lemma \ref{brauer-lemma-simple-module-unique}. Working out the definitions we see
that $x$ is a solution to our problem.
\end{proof}

\begin{lemma}[Automorphism inner]
\label{brauer-lemma-automorphism-inner}
\source{stacks:074R}
\href{https://stacks.math.columbia.edu/tag/074R}{\texttt{Stacks tag 074R}}
\group{brauer}

Let $A$ be a finite central simple $k$-algebra. Any automorphism of $A$ is
inner. In particular, any automorphism of $\text{Mat}(n \times n, k)$
is inner.
\end{lemma}

\begin{proof}
\uses{brauer-theorem-skolem-noether}

The Skolem-Noether theorem (Theorem \ref{brauer-theorem-skolem-noether})
applies.
\end{proof}

\section{The centralizer theorem}
\label{brauer-section-centralizer}
\begin{theorem}[Centralizer]
\label{brauer-theorem-centralizer}
\source{stacks:074T}
\href{https://stacks.math.columbia.edu/tag/074T}{\texttt{Stacks tag 074T}}
\group{brauer}

Let $A$ be a finite central simple algebra over $k$, and let
$B$ be a simple subalgebra of $A$. Then
\begin{enumerate}
\item the centralizer $C$ of $B$ in $A$ is simple,
\item $[A : k] = [B : k][C : k]$, and
\item the centralizer of $C$ in $A$ is $B$.
\end{enumerate}
\end{theorem}

\begin{proof}
\uses{brauer-lemma-simple-module-unique, brauer-lemma-tensor-simple}

Throughout this proof we use the results of
Lemma \ref{brauer-lemma-simple-module-unique} freely.
Choose a simple $A$-module $M$. Set $L = \text{End}_A(M)$.
Then $L$ is a skew field with center $k$ which acts on the left on $M$
and $A = \text{End}_L(M)$.
Then $M$ is a right $B \otimes_k L^{op}$-module and
$C = \text{End}_{B \otimes_k L^{op}}(M)$.
Since the algebra $B \otimes_k L^{op}$ is simple by
Lemma \ref{brauer-lemma-tensor-simple} we see that $C$ is simple (by
Lemma \ref{brauer-lemma-simple-module-unique} again).

\medskip\noindent
Write $B \otimes_k L^{op} = \text{Mat}(m \times m, K)$ for some
skew field $K$ finite over $k$. Then $C = \text{Mat}(n \times n, K^{op})$
if $M$ is isomorphic to a direct sum of $n$ copies of the simple
$B \otimes_k L^{op}$-module $K^{\oplus m}$ (the lemma again). Thus we have
$\dim_k(M) = nm [K : k]$, $[B : k] [L : k] = m^2 [K : k]$,
$[C : k] = n^2 [K : k]$, and $[A : k] [L : k] = \dim_k(M)^2$ (by
the lemma again). We conclude that (2) holds.

\medskip\noindent
Part (3) follows because of (2) applied to $C \subset A$ shows
that $[B : k] = [C' : k]$ where $C'$ is the centralizer of $C$ in $A$
(and the obvious fact that $B \subset C')$.
\end{proof}

\begin{lemma}[When tensor is equal]
\label{brauer-lemma-when-tensor-is-equal}
\source{stacks:074U}
\href{https://stacks.math.columbia.edu/tag/074U}{\texttt{Stacks tag 074U}}
\group{brauer}

Let $A$ be a finite central simple algebra over $k$, and let
$B$ be a simple subalgebra of $A$. If $B$ is a central
$k$-algebra, then $A = B \otimes_k C$ where $C$ is the (central simple)
centralizer of $B$ in $A$.
\end{lemma}

\begin{proof}
\uses{brauer-theorem-centralizer, brauer-lemma-tensor-simple}

We have $\dim_k(A) = \dim_k(B \otimes_k C)$ by
Theorem \ref{brauer-theorem-centralizer}. By
Lemma \ref{brauer-lemma-tensor-simple}
the tensor product is simple. Hence the natural map
$B \otimes_k C \to A$ is injective hence an isomorphism.
\end{proof}

\begin{lemma}[Self centralizing subfield]
\label{brauer-lemma-self-centralizing-subfield}
\source{stacks:074V}
\href{https://stacks.math.columbia.edu/tag/074V}{\texttt{Stacks tag 074V}}
\group{brauer}

Let $A$ be a finite central simple algebra over $k$.
If $K \subset A$ is a subfield, then the following are equivalent
\begin{enumerate}
\item $[A : k] = [K : k]^2$,
\item $K$ is its own centralizer, and
\item $K$ is a maximal commutative subring.
\end{enumerate}
\end{lemma}

\begin{proof}
\uses{brauer-theorem-centralizer}

Theorem \ref{brauer-theorem-centralizer}
shows that (1) and (2) are equivalent.
It is clear that (3) and (2) are equivalent.
\end{proof}

\begin{lemma}[The dimension of a finite central skew field is the square of the dimension of any maxi...]
\label{brauer-lemma-maximal-subfield}
\source{stacks:074W}
\href{https://stacks.math.columbia.edu/tag/074W}{\texttt{Stacks tag 074W}}
\group{brauer}


Let $A$ be a finite central skew field over $k$.
Then every maximal subfield $K \subset A$ satisfies
$[A : k] = [K : k]^2$.
\end{lemma}

\begin{proof}
\uses{brauer-lemma-self-centralizing-subfield}

Special case of Lemma \ref{brauer-lemma-self-centralizing-subfield}.
\end{proof}

\section{Splitting fields}
\label{brauer-section-splitting}
\begin{definition}[Splitting]
\label{brauer-definition-splitting}
\source{stacks:074Y}
\href{https://stacks.math.columbia.edu/tag/074Y}{\texttt{Stacks tag 074Y}}
\group{brauer}

Let $A$ be a finite central simple $k$-algebra.
We say a field extension $k'/k$ {\it splits} $A$, or
$k'$ is a {\it splitting field} for $A$ if $A \otimes_k k'$ is
a matrix algebra over $k'$.
\end{definition}

Another way to say this is that the class of $A$ maps to zero
under the map $\text{Br}(k) \to \text{Br}(k')$.

\begin{theorem}[Splitting]
\label{brauer-theorem-splitting}
\source{stacks:074Z}
\href{https://stacks.math.columbia.edu/tag/074Z}{\texttt{Stacks tag 074Z}}
\group{brauer}

Let $A$ be a finite central simple $k$-algebra.
Let $k'/k$ be a finite field extension.
The following are equivalent
\begin{enumerate}
\item $k'$ splits $A$, and
\item there exists a finite central simple algebra $B$ similar to $A$
such that $k' \subset B$ and $[B : k] = [k' : k]^2$.
\end{enumerate}
\end{theorem}

\begin{proof}
\uses{brauer-lemma-self-centralizing-subfield, brauer-lemma-when-tensor-is-equal, brauer-theorem-centralizer}

Assume (2). It suffices to show that $B \otimes_k k'$ is a matrix
algebra. We know that $B \otimes_k B^{op} \cong \text{End}_k(B)$.
Since $k'$ is the centralizer of $k'$ in $B^{op}$ by
Lemma \ref{brauer-lemma-self-centralizing-subfield}
we see that $B \otimes_k k'$ is the centralizer of $k \otimes k'$
in $B \otimes_k B^{op} = \text{End}_k(B)$. Of course this centralizer
is just $\text{End}_{k'}(B)$ where we view $B$ as a $k'$ vector space
via the embedding $k' \to B$. Thus the result.

\medskip\noindent
Assume (1). This means that we have an isomorphism
$A \otimes_k k' \cong \text{End}_{k'}(V)$ for some $k'$-vector space $V$.
Let $B$ be the commutant of $A$ in $\text{End}_k(V)$. Note that
$k'$ sits in $B$. By
Lemma \ref{brauer-lemma-when-tensor-is-equal}
the classes of $A$ and $B$ add up to zero in $\text{Br}(k)$.
From the dimension formula in
Theorem \ref{brauer-theorem-centralizer}
we see that
$$
[B : k] [A : k] =
\dim_k(V)^2 =
[k' : k]^2 \dim_{k'}(V)^2 =
[k' : k]^2 [A : k].
$$
Hence $[B : k] = [k' : k]^2$. Thus we have proved the result for the
opposite to the Brauer class of $A$. However, $k'$ splits the Brauer
class of $A$ if and only if it splits
the Brauer class of the opposite algebra, so we win anyway.
\end{proof}

\begin{lemma}[Maximal subfield splits]
\label{brauer-lemma-maximal-subfield-splits}
\source{stacks:0750}
\href{https://stacks.math.columbia.edu/tag/0750}{\texttt{Stacks tag 0750}}
\group{brauer}

A maximal subfield of a finite central skew field $K$ over $k$ is
a splitting field for $K$.
\end{lemma}

\begin{proof}
\uses{brauer-lemma-maximal-subfield, brauer-theorem-splitting}

Combine Lemma \ref{brauer-lemma-maximal-subfield} with
Theorem \ref{brauer-theorem-splitting}.
\end{proof}

\begin{lemma}[Splitting field degree]
\label{brauer-lemma-splitting-field-degree}
\source{stacks:0751}
\href{https://stacks.math.columbia.edu/tag/0751}{\texttt{Stacks tag 0751}}
\group{brauer}

Consider a finite central skew field $K$ over $k$. Let $d^2 = [K : k]$.
For any finite splitting field $k'$ for $K$ the degree $[k' : k]$ is
divisible by $d$.
\end{lemma}

\begin{proof}
\uses{brauer-theorem-splitting, brauer-lemma-similar}

By Theorem \ref{brauer-theorem-splitting} there exists a finite central
simple algebra $B$ in the Brauer class of $K$ such that
$[B : k] = [k' : k]^2$. By
Lemma \ref{brauer-lemma-similar}
we see that $B = \text{Mat}(n \times n, K)$ for some $n$.
Then $[k' : k]^2 = n^2d^2$ whence the result.
\end{proof}

\begin{proposition}[Separable splitting field]
\label{brauer-proposition-separable-splitting-field}
\source{stacks:0752}
\href{https://stacks.math.columbia.edu/tag/0752}{\texttt{Stacks tag 0752}}
\group{brauer}

Consider a finite central skew field $K$ over $k$.
There exists a maximal subfield $k \subset k' \subset K$ which
is separable over $k$.
In particular, every Brauer class has a finite separable
spitting field.
\end{proposition}

\begin{proof}
\uses{brauer-lemma-maximal-subfield-splits, brauer-lemma-base-change, brauer-lemma-brauer-algebraically-closed}

Since every Brauer class is represented by a finite central skew
field over $k$, we see that the second statement follows from the
first by
Lemma \ref{brauer-lemma-maximal-subfield-splits}.

\medskip\noindent
To prove the first statement, suppose that we are given a separable
subfield $k' \subset K$. Then the centralizer $K'$ of $k'$ in $K$
has center $k'$, and the problem reduces to finding a maximal
subfield of $K'$ separable over $k'$. Thus it suffices to prove, if
$k \not = K$, that we can find an element $x \in K$, $x \not \in k$
which is separable over $k$. This statement is clear in characteristic
zero. Hence we may assume that $k$ has characteristic $p > 0$. If the
ground field $k$ is finite then, the result is clear as well (because
extensions of finite fields are always separable). Thus we may assume
that $k$ is an infinite field of positive characteristic.

\medskip\noindent
To get a contradiction assume no element of $K$ is separable over $k$.
By the discussion in
Fields, Section \ref{fields-section-algebraic}
this means the minimal polynomial of any $x \in K$ is of the form
$T^q - a$ where $q$ is a power of $p$ and $a \in k$. Since it is
clear that every element of $K$ has a minimal polynomial of degree
$\leq \dim_k(K)$ we conclude that there exists a fixed $p$-power
$q$ such that $x^q \in k$ for all $x \in K$.

\medskip\noindent
Consider the map
$$
(-)^q : K \longrightarrow K
$$
and write it out in terms of a $k$-basis $\{a_1, \ldots, a_n\}$ of $K$
with $a_1 = 1$. So
$$
(\sum x_i a_i)^q = \sum f_i(x_1, \ldots, x_n)a_i.
$$
Since multiplication on $K$ is $k$-bilinear we see that each $f_i$
is a polynomial in $x_1, \ldots, x_n$ (details omitted).
The choice of $q$ above and the fact that $k$ is infinite shows that
$f_i$ is identically zero for $i \geq 2$. Hence we see that it remains
zero on extending $k$ to its algebraic closure $\overline{k}$. But the
algebra $K \otimes_k \overline{k}$ is a matrix algebra (for example by
Lemmas \ref{brauer-lemma-base-change} and \ref{brauer-lemma-brauer-algebraically-closed}),
which implies there are some elements whose $q$th power is not central
(e.g., $e_{11}$). This is the desired contradiction.
\end{proof}

The results above allow us to characterize finite central simple algebras
as follows.

\begin{lemma}[Finite central simple algebra]
\label{brauer-lemma-finite-central-simple-algebra}
\source{stacks:0753}
\href{https://stacks.math.columbia.edu/tag/0753}{\texttt{Stacks tag 0753}}
\group{brauer}

Let $k$ be a field. For a $k$-algebra $A$ the following are equivalent
\begin{enumerate}
\item $A$ is finite central simple $k$-algebra,
\item $A$ is a finite dimensional $k$-vector space, $k$ is the center of $A$,
and $A$ has no nontrivial two-sided ideal,
\item there exists $d \geq 1$ such that
$A \otimes_k \bar k \cong \text{Mat}(d \times d, \bar k)$,
\item there exists $d \geq 1$ such that
$A \otimes_k k^{sep} \cong \text{Mat}(d \times d, k^{sep})$,
\item there exist $d \geq 1$ and a finite Galois extension $k'/k$
such that
$A \otimes_k k' \cong \text{Mat}(d \times d, k')$,
\item there exist $n \geq 1$ and a finite central skew field $K$
over $k$ such that $A \cong \text{Mat}(n \times n, K)$.
\end{enumerate}
The integer $d$ is called the {\it degree} of $A$.
\end{lemma}

\begin{proof}
\uses{brauer-proposition-separable-splitting-field, brauer-lemma-matrix-algebras, brauer-theorem-wedderburn}

The equivalence of (1) and (2) is a consequence of the definitions, see
Section \ref{brauer-section-algebras}.
Assume (1). By
Proposition \ref{brauer-proposition-separable-splitting-field}
there exists a separable splitting field $k \subset k'$ for $A$.
Of course, then a Galois closure of $k'/k$ is a splitting field also.
Thus we see that (1) implies (5). It is clear that (5) $\Rightarrow$ (4)
$\Rightarrow$ (3). Assume (3). Then $A \otimes_k \overline{k}$
is a finite central simple $\overline{k}$-algebra for example by
Lemma \ref{brauer-lemma-matrix-algebras}.
This trivially implies that $A$ is a finite central simple $k$-algebra.
Finally, the equivalence of (1) and (6) is Wedderburn's theorem, see
Theorem \ref{brauer-theorem-wedderburn}.
\end{proof}

\label{chap:homology}
\section{Introduction}
\label{homology-section-introduction}
Basic homological algebra will be explained in this document.
We add as needed in the other parts, since there is clearly
an infinite amount of this stuff around.
A reference is \cite{Maclane}.

\section{Basic notions}
\label{homology-section-topology-basic}
The following notions are considered basic and will not be defined,
and or proved. This does not mean they are all necessarily easy or
well known.

\begin{enumerate}
\item Nothing yet.
\end{enumerate}

\section{Preadditive and additive categories}
\label{homology-section-additive-categories}
Here is the definition of a preadditive category.

\begin{definition}[Preadditive]
\label{homology-definition-preadditive}
\source{stacks:00ZY}
\href{https://stacks.math.columbia.edu/tag/00ZY}{\texttt{Stacks tag 00ZY}}
\group{homology}

A category $\mathcal{A}$ is called {\it preadditive} if each
morphism set $\Mor_\mathcal{A}(x, y)$ is endowed
with the structure of an abelian group such that the
compositions
$$
\Mor(x, y) \times \Mor(y, z)
\longrightarrow
\Mor(x, z)
$$
are bilinear. A functor $F : \mathcal{A} \to \mathcal{B}$ of
preadditive categories is called {\it additive} if and only
if $F : \Mor(x, y) \to \Mor(F(x), F(y))$
is a homomorphism of abelian groups for all
$x, y \in \Ob(\mathcal{A})$.
\end{definition}

In particular for every $x, y$ there exists at least
one morphism $x \to y$, namely the zero map.

\begin{lemma}[Preadditive zero]
\label{homology-lemma-preadditive-zero}
\source{stacks:00ZZ}
\href{https://stacks.math.columbia.edu/tag/00ZZ}{\texttt{Stacks tag 00ZZ}}
\group{homology}

Let $\mathcal{A}$ be a preadditive category.
Let $x$ be an object of $\mathcal{A}$.
The following are equivalent
\begin{enumerate}
\item $x$ is an initial object,
\item $x$ is a final object, and
\item $\text{id}_x = 0$ in $\Mor_\mathcal{A}(x, x)$.
\end{enumerate}
Furthermore, if such an object $0$ exists, then a morphism
$\alpha : y \to z$ factors through $0$ if and only if $\alpha = 0$.
\end{lemma}

\begin{proof}
First assume that $x$ is either (1) initial or (2) final.
In both cases, it follows that $\Mor(x,x)$ is a trivial abelian group
containing $\text{id}_x$, thus $\text{id}_x = 0$ in
$\Mor(x, x)$, which shows that each of (1) and (2) implies (3).

\medskip\noindent
Now assume that $\text{id}_x = 0$ in $\Mor(x,x)$. Let $y$
be an arbitrary object of $\mathcal{A}$ and let $f \in \Mor(x ,y)$.
Denote $C : \Mor(x,x) \times \Mor(x,y) \to \Mor(x,y)$ the composition map.
Then $f = C(0, f)$ and since $C$ is bilinear we have $C(0, f) = 0$.
Thus $f = 0$. Hence $x$ is initial in $\mathcal{A}$.
A similar argument for $f \in \Mor(y, x)$ can be used to show that
$x$ is also final. Thus (3) implies both (1) and (2).
\end{proof}

\begin{definition}[Zero object]
\label{homology-definition-zero-object}
\source{stacks:0100}
\href{https://stacks.math.columbia.edu/tag/0100}{\texttt{Stacks tag 0100}}
\group{homology}

\uses{homology-lemma-preadditive-zero}
In a preadditive category $\mathcal{A}$, we call an object that is both
final and initial (as in Lemma \ref{homology-lemma-preadditive-zero}) a
{\it zero object} and denote it $0$.
\end{definition}

\begin{lemma}[Preadditive direct sum]
\label{homology-lemma-preadditive-direct-sum}
\source{stacks:0101}
\href{https://stacks.math.columbia.edu/tag/0101}{\texttt{Stacks tag 0101}}
\group{homology}

Let $\mathcal{A}$ be a preadditive category.
Let $x, y \in \Ob(\mathcal{A})$.
If the product $x \times y$ exists, then so does
the coproduct $x \amalg y$.
If the coproduct $x \amalg y$ exists, then so does
the product $x \times y$. In this case
also $x \amalg y \cong x \times y$.
\end{lemma}

\begin{proof}
Suppose that $z = x \times y$ with projections
$p : z \to x$ and $q : z \to y$. Denote $i : x \to z$
the morphism corresponding to $(1, 0)$. Denote $j : y \to z$
the morphism corresponding to $(0, 1)$. Thus we have the
commutative diagram
$$
\begin{array}{ccc}x \overset{1}{\longrightarrow}\overset{i}{\searrow} &  & x \\  & z \overset{p}{\nearrow}\overset{q}{\searrow} &  \\ y \overset{1}{\longrightarrow}\overset{j}{\nearrow} &  & y\end{array}
$$
where the diagonal compositions are zero. It follows that
$i \circ p + j \circ q : z \to z$ is the identity since
it is a morphism which upon composing with $p$ gives $p$
and upon composing with $q$ gives $q$.
Suppose given morphisms $a : x \to w$ and $b : y \to w$.
Then we can form the map $a \circ p + b \circ q : z \to w$.
In this way we get a bijection $\Mor(z, w)
= \Mor(x, w) \times \Mor(y, w)$ which
shows that $z = x \amalg y$.

\medskip\noindent
We leave it to the reader to construct the morphisms
$p, q$ given a coproduct $x \amalg y$ instead of a
product.
\end{proof}

\begin{definition}[Direct sum]
\label{homology-definition-direct-sum}
\source{stacks:0102}
\href{https://stacks.math.columbia.edu/tag/0102}{\texttt{Stacks tag 0102}}
\group{homology}

\uses{homology-lemma-preadditive-direct-sum}
Given a pair of objects $x, y$ in a preadditive category $\mathcal{A}$,
the {\it direct sum} $x \oplus y$ of $x$ and $y$ is the direct
product $x \times y$ endowed with the morphisms
$i, j, p, q$ as in Lemma \ref{homology-lemma-preadditive-direct-sum} above.
\end{definition}

\begin{remark}[Direct sum]
\label{homology-remark-direct-sum}
\source{stacks:0103}
\href{https://stacks.math.columbia.edu/tag/0103}{\texttt{Stacks tag 0103}}
\group{homology}

\uses{homology-lemma-preadditive-direct-sum}
Note that the proof of Lemma \ref{homology-lemma-preadditive-direct-sum}
shows that given $p$ and $q$ the morphisms $i$, $j$ are uniquely
determined by the rules $p \circ i = \text{id}_x$,
$q \circ j = \text{id}_y$, $p \circ j = 0$, $q \circ i = 0$.
Moreover, we automatically have
$i \circ p + j \circ q = \text{id}_{x \oplus y}$.
Similarly, given $i$, $j$ the morphisms $p$ and $q$ are uniquely determined.
Finally, given objects $x, y, z$ and morphisms
$i : x \to z$, $j : y \to z$, $p : z \to x$ and
$q : z \to y$ such that $p \circ i = \text{id}_x$,
$q \circ j = \text{id}_y$, $p \circ j = 0$, $q \circ i = 0$
and $i \circ p + j \circ q = \text{id}_z$, then $z$
is the direct sum of $x$ and $y$ with the four morphisms
equal to $i, j, p, q$.
\end{remark}

\begin{lemma}[Additive additive]
\label{homology-lemma-additive-additive}
\source{stacks:0105}
\href{https://stacks.math.columbia.edu/tag/0105}{\texttt{Stacks tag 0105}}
\group{homology}

Let $\mathcal{A}$, $\mathcal{B}$ be preadditive categories.
Let $F : \mathcal{A} \to \mathcal{B}$ be an additive functor.
Then $F$ transforms direct sums to direct sums and zero to zero.
\end{lemma}

\begin{proof}
\uses{homology-remark-direct-sum, homology-lemma-preadditive-zero}

Suppose $F$ is additive. A direct sum $z$
of $x$ and $y$ is characterized by having morphisms
$i : x \to z$, $j : y \to z$, $p : z \to x$ and
$q : z \to y$ such that $p \circ i = \text{id}_x$,
$q \circ j = \text{id}_y$, $p \circ j = 0$, $q \circ i = 0$
and $i \circ p + j \circ q = \text{id}_z$, according
to Remark \ref{homology-remark-direct-sum}. Clearly $F(x), F(y), F(z)$
and the morphisms $F(i), F(j), F(p), F(q)$ satisfy exactly the
same relations (by additivity) and we see that $F(z)$ is
a direct sum of $F(x)$ and $F(y)$.
Hence, $F$ transforms direct sums to direct sums.

\medskip\noindent
To see that $F$ transforms zero to zero, use the
characterization (3) of the zero object in
Lemma \ref{homology-lemma-preadditive-zero}.
\end{proof}

\begin{definition}[Additive category]
\label{homology-definition-additive-category}
\source{stacks:0104}
\href{https://stacks.math.columbia.edu/tag/0104}{\texttt{Stacks tag 0104}}
\group{homology}

A category $\mathcal{A}$ is called {\it additive}
if it is preadditive and finite products exist, in other
words it has a zero object and direct sums.
\end{definition}

Namely the empty product is a finite product and
if it exists, then it is a final object.

\begin{definition}[Kernel]
\label{homology-definition-kernel}
\source{stacks:0106}
\href{https://stacks.math.columbia.edu/tag/0106}{\texttt{Stacks tag 0106}}
\group{homology}

Let $\mathcal{A}$ be a preadditive category.
Let $f : x \to y$ be a morphism.
\begin{enumerate}
\item A {\it kernel} of $f$ is a morphism
$i : z \to x$ such that (a) $f \circ i = 0$ and (b)
for any $i' : z' \to x$ such that $f \circ i' = 0$ there
exists a unique morphism $g : z' \to z$ such that
$i' = i \circ g$.
\item If the kernel of $f$ exists, then we denote
this $\Ker(f) \to x$.
\item A {\it cokernel} of $f$ is a morphism
$p : y \to z$ such that (a) $p \circ f = 0$ and (b)
for any $p' : y \to z'$ such that $p' \circ f = 0$ there
exists a unique morphism $g : z \to z'$ such that
$p' = g \circ p$.
\item If a cokernel of $f$ exists we denote this
$y \to \Coker(f)$.
\item If a kernel of $f$ exists, then a {\it coimage
of $f$} is a cokernel for the morphism $\Ker(f) \to x$.
\item If a kernel and coimage exist then we denote this
$x \to \Coim(f)$.
\item If a cokernel of $f$ exists, then the {\it image of
$f$} is a kernel of the morphism $y \to \Coker(f)$.
\item If a cokernel and image of $f$ exist then we denote
this $\Im(f) \to y$.
\end{enumerate}
\end{definition}

In the above definition, we have spoken of ``the kernel'' and
``the cokernel'', tacitly using their uniqueness
up to unique isomorphism. This follows from the Yoneda lemma
(Categories, Section \ref{categories-section-opposite})
because the kernel of $f : x \to y$ represents the functor
sending an object $z$ to the set
$\Ker(\Mor_\mathcal{A}(z, x) \to \Mor_\mathcal{A}(z, y))$.
The case of cokernels is dual.

\medskip\noindent
We first relate the direct sum to kernels as follows.

\begin{lemma}[Additive cat biproduct kernel]
\label{homology-lemma-additive-cat-biproduct-kernel}
\source{stacks:09QG}
\href{https://stacks.math.columbia.edu/tag/09QG}{\texttt{Stacks tag 09QG}}
\group{homology}

\uses{homology-lemma-preadditive-direct-sum}
Let $\mathcal{C}$ be a preadditive category.
Let $x \oplus y$ with morphisms $i, j, p, q$ as in
Lemma \ref{homology-lemma-preadditive-direct-sum}
be a direct sum in $\mathcal{C}$. Then $i : x \to x \oplus y$
is a kernel of $q : x \oplus y \rightarrow y$. Dually, $p$ is
a cokernel for $j$.
\end{lemma}

\begin{proof}
Let $f : z' \to x \oplus y$ be a morphism such that $q \circ f = 0$.
We have to show that there exists a unique morphism $g : z' \to x$
such that $f = i \circ g$. Since $i \circ p + j \circ q$ is the identity on
$x \oplus y$ we see that
$$
f = (i \circ p + j \circ q) \circ f = i \circ p \circ f
$$
and hence $g = p \circ f$ works. Uniqueness holds because $p \circ i$
is the identity on $x$. The proof of the second statement is dual.
\end{proof}

\begin{lemma}[Kernel mono]
\label{homology-lemma-kernel-mono}
\source{stacks:0E43}
\href{https://stacks.math.columbia.edu/tag/0E43}{\texttt{Stacks tag 0E43}}
\group{homology}

Let $\mathcal{C}$ be a preadditive category.
Let $f : x \to y$ be a morphism in $\mathcal{C}$.
\begin{enumerate}
\item If a kernel of $f$ exists, then
this kernel is a monomorphism.
\item If a cokernel of $f$ exists, then
this cokernel is an epimorphism.
\item If a kernel and coimage of $f$ exist, then
the coimage is an epimorphism.
\item If a cokernel and image of $f$ exist, then
the image is a monomorphism.
\end{enumerate}
\end{lemma}

\begin{proof}
Part (1) follows easily from the uniqueness required in the
definition of a kernel. The proof of (2) is dual.
Part (3) follows from (2), since the coimage is a cokernel.
Similarly, (4) follows from (1).
\end{proof}

\begin{lemma}[Coim im map]
\label{homology-lemma-coim-im-map}
\source{stacks:0107}
\href{https://stacks.math.columbia.edu/tag/0107}{\texttt{Stacks tag 0107}}
\group{homology}

Let $f : x \to y$ be a morphism in a preadditive category
such that the kernel, cokernel, image and coimage all exist.
Then $f$ can be factored uniquely as
$x \to \Coim(f) \to \Im(f) \to y$.
\end{lemma}

\begin{proof}
\uses{homology-lemma-kernel-mono}

There is a canonical morphism $\Coim(f) \to y$
because $\Ker(f) \to x \to y$ is zero.
The composition $\Coim(f) \to y \to \Coker(f)$
is zero, because it is the unique morphism which gives
rise to the morphism $x \to y \to \Coker(f)$ which
is zero
(the uniqueness follows from
Lemma \ref{homology-lemma-kernel-mono} (3)).
Hence $\Coim(f) \to y$ factors uniquely through
$\Im(f) \to y$, which gives us the desired map.
\end{proof}

\begin{example}[Not abelian]
\label{homology-example-not-abelian}
\source{stacks:0108}
\href{https://stacks.math.columbia.edu/tag/0108}{\texttt{Stacks tag 0108}}
\group{homology}

\uses{homology-definition-filtered}
Let $k$ be a field.
Consider the category
of filtered vector spaces over $k$.
(See Definition \ref{homology-definition-filtered}.)
Consider the filtered vector spaces $(V, F)$ and $(W, F)$ with
$V = W = k$ and
$$
F^iV
=
\left\{
\begin{matrix}
V & \text{if} & i < 0 \\
0 & \text{if} & i \geq 0
\end{matrix}
\right.
\text{ and }
F^iW
=
\left\{
\begin{matrix}
W & \text{if} & i \leq 0 \\
0 & \text{if} & i > 0
\end{matrix}
\right.
$$
The map $f : V \to W$ corresponding to $\text{id}_k$ on the underlying
vector spaces has trivial kernel and cokernel but is not
an isomorphism. Note also that $\Coim(f) = V$ and $\Im(f) = W$.
This means that the category of filtered vector spaces over $k$
is not abelian.
\end{example}

We finish this section by some lemmas on splitting images of
idempotent endormorphisms. Recall that an endomorphism $f$
is idempotent if $f \circ f = f$.

\begin{remark}[Idempotent symmetry]
\label{homology-remark-idempotent-symmetry}
\source{stacks:0H9N}
\href{https://stacks.math.columbia.edu/tag/0H9N}{\texttt{Stacks tag 0H9N}}
\group{homology}

Let $\mathcal{A}$ be a preadditive category,
$x$ an object of $\mathcal{A}$,
and $f : x \to x$ idempotent.
Writing $g = \text{id} _ x - f$,
one has $f \circ g = 0$, $g \circ f = 0$, and $g \circ g = g$.
\end{remark}

\begin{lemma}[Idempotent kernel cokernel]
\label{homology-lemma-idempotent-kernel-cokernel}
\source{stacks:0H9P}
\href{https://stacks.math.columbia.edu/tag/0H9P}{\texttt{Stacks tag 0H9P}}
\group{homology}

\uses{homology-remark-idempotent-symmetry}
Let $\mathcal{A}$ be a preadditive category,
$x$ be an object of $\mathcal{A}$,
and $f : x \to x$ be idempotent.
Write $g = \text{id} _ x - f$
and recall by Remark \ref{homology-remark-idempotent-symmetry}
that $f \circ g = g \circ f = 0$.
\begin{enumerate}
\item If $f$ has kernel $i : \Ker (f) \to x$
and $p$ is the unique morphism such that $g = i \circ p$,
then $p \circ i = \text{id} _ {\Ker (f)}$
and $p$ is the cokernel of $f$.
\item If $f$ has cokernel $p : x \to \Coker (f)$
and $i$ is the unique morphism such that $g = i \circ p$,
then $p \circ i = \text{id} _ {\Coker (f)}$
and $i$ is the kernel of $f$.
\item If $g$ has kernel $j : \Ker (g) \to x$
and $q$ is the unique morphism such that $f = j \circ q$,
then $q \circ j = \text{id} _ {\Ker (g)}$
and $q$ is the cokernel of $g$.
\item If $g$ has cokernel $q : x \to \Coker (g)$
and $j$ is the unique morphism such that $f = j \circ q$,
then $q \circ j = \text{id} _ {\Coker (g)}$
and $j$ is the kernel of $g$.
\end{enumerate}
\end{lemma}

\begin{proof}
\uses{homology-lemma-kernel-mono, homology-remark-idempotent-symmetry}

As for (1), compute first that $i = (f + g) \circ i = g \circ i$.
By the construction of $p$, this implies that
$i \circ p \circ i = g \circ i = i \circ \text{id} _ {\Ker (f)}$.
By Lemma \ref{homology-lemma-kernel-mono} we conclude that
$p \circ i = \text{id} _ {\Ker (f)}$.

\medskip\noindent
It remains to show that $p : x \to \Ker (f)$
satisfies the universal property of the cokernel of $f$,
i.e., that given a morphism $a : x \to y$ satisfying $a \circ f = 0$
there exists a unique morphism $b : \Ker (f) \to y$
such that $a = b \circ p$.
Existence follows by first computing that $a = a \circ (f + g) = a \circ g$
and concluding by the construction of $p$
that $a = a \circ g = a \circ i \circ p$
(so that we can take $b = a \circ i$).
Uniqueness follows from that $b = b \circ p \circ i = a \circ i$
(so that $a$ determines $b$).

\medskip\noindent
By duality,
symmetry (i.e., that $g$ is itself idempotent;
cf. Remark \ref{homology-remark-idempotent-symmetry}),
and duality and symmetry respectively, (2), (3), and (4) follow as did (1).
\end{proof}

\begin{lemma}[Idempotent splitting]
\label{homology-lemma-idempotent-splitting}
\source{stacks:0H9Q}
\href{https://stacks.math.columbia.edu/tag/0H9Q}{\texttt{Stacks tag 0H9Q}}
\group{homology}

\uses{homology-lemma-idempotent-kernel-cokernel}
Let $\mathcal{A}$ be a preadditive category,
$x$ be an object of $\mathcal{A}$,
and $f : x \to x$ be idempotent.
Write $g = \text{id} _ x - f$.
If each of $f$ and $g$ have at least one of a kernel or cokernel
and in turn morphisms $i , j , p , q$ are constructed
as in the statement of Lemma \ref{homology-lemma-idempotent-kernel-cokernel},
then all four (co)kernels exist and
\begin{align*}
x
& \simeq \Ker (f) \oplus \Ker (g) \\
& \simeq \Coker (f) \oplus \Ker (g) \\
& \simeq \Ker (f) \oplus \Coker (g) \\
& \simeq \Coker (f) \oplus \Coker (g)
\end{align*}
with the structure of each direct product given by $i , j , p , q$.
\end{lemma}

\begin{proof}
\uses{homology-lemma-idempotent-kernel-cokernel, homology-remark-direct-sum}

By Lemma \ref{homology-lemma-idempotent-kernel-cokernel}
$p \circ i = \text{id} _ {\Ker (f)} = \text{id} _ {\Coker (f)}$
and $q \circ j = \text{id} _ {\Ker (g)} = \text{id} _ {\Coker (g)}$.
By construction, $i \circ p + j \circ q = f + g = \text{id} _ x$.
By Remark \ref{homology-remark-direct-sum} the claim follows.
\end{proof}

\begin{lemma}[Split morphism kernel cokernel]
\label{homology-lemma-split-morphism-kernel-cokernel}
\source{stacks:0H9R}
\href{https://stacks.math.columbia.edu/tag/0H9R}{\texttt{Stacks tag 0H9R}}
\group{homology}

Let $\mathcal{A}$ be a preadditive category,
$x$ and $y$ be objects of $\mathcal{A}$,
and $j : y \to x$ and $q : x \to y$ be morphisms
satisfying $q \circ j = \text{id} _ y$.
Then
\begin{enumerate}
\item $\text{id} _ x - j \circ q$ has kernel $j$.
\item $\text{id} _ x - j \circ q$ has cokernel $q$.
\end{enumerate}
\end{lemma}

\begin{proof}
As for (1), compute first that $(\text{id} _ x - j \circ q) \circ j = 0$.
We must show that $j$ satisfies the universal property
of the kernel of $\text{id} _ {x} - j \circ q$,
i.e., that given a morphism $a : z \to x$
satisfying $(\text{id} _ x - j \circ q) \circ a = 0$
there exists a unique morphism $b : z \to y$
such that $a = j \circ b$.
Existence follows by computing that $a = j \circ q \circ a$
(so that we can take $b = q \circ a$).
Uniqueness follows from that $b = q \circ j \circ b = q \circ a$
(so that $a$ determines $b$).

\medskip\noindent
By duality, (2) follows as did (1).
\end{proof}

\begin{lemma}[Split morphism splitting]
\label{homology-lemma-split-morphism-splitting}
\source{stacks:0H9S}
\href{https://stacks.math.columbia.edu/tag/0H9S}{\texttt{Stacks tag 0H9S}}
\group{homology}

Let $\mathcal{A}$ be a preadditive category,
$x$ and $y$ be objects of $\mathcal{A}$,
and $j : y \to x$ and $q : x \to y$ be morphisms
satisfying $q \circ j = \text{id} _ y$.
If $j \circ q$ has at least one of a kernel or cokernel,
then both (co)kernels exist and
\begin{align*}
x
& \simeq \Ker (j \circ q) \oplus y \\
& \simeq \Coker (j \circ q) \oplus y
\end{align*}
with the structure of either direct product including $j , q$,
and the canonical (co)kernel morphism,
and the remaining map uniquely determined.
\end{lemma}

\begin{proof}
\uses{homology-lemma-idempotent-splitting, homology-lemma-split-morphism-kernel-cokernel}

Write $f = j \circ q$,
compute that $f \circ f = f$,
and apply Lemma \ref{homology-lemma-idempotent-splitting}
and Lemma \ref{homology-lemma-split-morphism-kernel-cokernel}.
\end{proof}

\section{Karoubian categories}
\label{homology-section-karoubian}
Skip this section on a first reading.

\begin{definition}[Karoubian]
\label{homology-definition-karoubian}
\source{stacks:09SG}
\href{https://stacks.math.columbia.edu/tag/09SG}{\texttt{Stacks tag 09SG}}
\group{homology}

Let $\mathcal{C}$ be a preadditive category. We say $\mathcal{C}$
is {\it Karoubian} if every idempotent endomorphism of an object
of $\mathcal{C}$ has a kernel.
\end{definition}

The dual notion would be that every idempotent endomorphism of an
object has a cokernel. However, in view of the (dual of the)
following lemma that would be an equivalent notion.

\begin{lemma}[Karoubian]
\label{homology-lemma-karoubian}
\source{stacks:09SH}
\href{https://stacks.math.columbia.edu/tag/09SH}{\texttt{Stacks tag 09SH}}
\group{homology}

Let $\mathcal{C}$ be a preadditive category. The following
are equivalent
\begin{enumerate}
\item $\mathcal{C}$ is Karoubian,
\item every idempotent endomorphism of an object of $\mathcal{C}$ has a
cokernel, and
\item given an idempotent endomorphism $p : z \to z$ of $\mathcal{C}$
there exists a direct sum decomposition $z = x \oplus y$ such
that $p$ corresponds to the projection onto $y$.
\end{enumerate}
\end{lemma}

\begin{proof}
\uses{homology-lemma-idempotent-kernel-cokernel, homology-lemma-idempotent-splitting, homology-lemma-additive-cat-biproduct-kernel}

Immediate via Lemmas \ref{homology-lemma-idempotent-kernel-cokernel},
\ref{homology-lemma-idempotent-splitting}, and \ref{homology-lemma-additive-cat-biproduct-kernel}.
\end{proof}

\begin{lemma}[Projectors have images]
\label{homology-lemma-projectors-have-images}
\source{stacks:05QV}
\href{https://stacks.math.columbia.edu/tag/05QV}{\texttt{Stacks tag 05QV}}
\group{homology}

Let $\mathcal{D}$ be a preadditive category.
\begin{enumerate}
\item If $\mathcal{D}$ has countable products and kernels of maps which
have a right inverse, then $\mathcal{D}$ is Karoubian.
\item If $\mathcal{D}$ has countable coproducts and cokernels of
maps which have a left inverse, then $\mathcal{D}$ is Karoubian.
\end{enumerate}
\end{lemma}

\begin{proof}
\uses{homology-lemma-karoubian}

Let $X$ be an object of $\mathcal{D}$ and let $e : X \to X$ be an idempotent.
The functor
$$
W \longmapsto \Ker(
\Mor_\mathcal{D}(W, X)
\xrightarrow{e}
\Mor_\mathcal{D}(W, X)
)
$$
is representable if and only if $e$ has a kernel. Note that for any
abelian group $A$ and idempotent endomorphism $e : A \to A$ we have
$$
\Ker(e : A \to A)
= \Ker(\Phi :
\prod\nolimits_{n \in \mathbf{N}} A
\to
\prod\nolimits_{n \in \mathbf{N}} A
)
$$
where
$$
\Phi(a_1, a_2, a_3, \ldots) = (ea_1 + (1 - e)a_2, ea_2 + (1 - e)a_3, \ldots)
$$
Moreover, $\Phi$ has the right inverse
$$
\Psi(a_1, a_2, a_3, \ldots) =
(a_1, (1 - e)a_1 + ea_2, (1 - e)a_2 + ea_3, \ldots).
$$
Hence (1) holds. The proof of (2) is dual (using the dual definition
of a Karoubian category, namely condition (2) of
Lemma \ref{homology-lemma-karoubian}).
\end{proof}

\section{Abelian categories}
\label{homology-section-abelian-categories}
An abelian category is a category satisfying just enough axioms so the
snake lemma holds. An axiom (that is sometimes forgotten)
is that the canonical map $\Coim(f) \to \Im(f)$
of Lemma \ref{homology-lemma-coim-im-map} is always an isomorphism.
Example \ref{homology-example-not-abelian} shows that it is necessary.

\begin{definition}[Abelian category]
\label{homology-definition-abelian-category}
\source{stacks:0109}
\href{https://stacks.math.columbia.edu/tag/0109}{\texttt{Stacks tag 0109}}
\group{homology}

A category $\mathcal{A}$ is {\it abelian} if
it is additive, if all kernels and cokernels exist,
and if the natural map $\Coim(f) \to \Im(f)$
is an isomorphism for all morphisms $f$ of
$\mathcal{A}$.
\end{definition}

\begin{lemma}[Abelian opposite]
\label{homology-lemma-abelian-opposite}
\source{stacks:010A}
\href{https://stacks.math.columbia.edu/tag/010A}{\texttt{Stacks tag 010A}}
\group{homology}

Let $\mathcal{A}$ be a preadditive category.
The additions on sets of morphisms make
$\mathcal{A}^{opp}$ into a preadditive category.
Furthermore, $\mathcal{A}$ is additive if and only if $\mathcal{A}^{opp}$
is additive, and
$\mathcal{A}$ is abelian if and only if $\mathcal{A}^{opp}$ is abelian.
\end{lemma}

\begin{proof}
The first statement is straightforward.
To see that $\mathcal{A}$ is additive if and only if $\mathcal{A}^{opp}$
is additive, recall that additivity can be characterized by
the existence of a zero object and direct sums, which are both
preserved when passing to the opposite category.
Finally, to see that
$\mathcal{A}$ is abelian if and only if $\mathcal{A}^{opp}$ is abelian,
observes that kernels, cokernels, images and coimages in
$\mathcal{A}^{opp}$ correspond to
cokernels, kernels, coimages and images in $\mathcal{A}$,
respectively.
\end{proof}

\begin{definition}[Injective surjective]
\label{homology-definition-injective-surjective}
\source{stacks:010B}
\href{https://stacks.math.columbia.edu/tag/010B}{\texttt{Stacks tag 010B}}
\group{homology}

Let $f : x \to y$ be a morphism in an abelian category.
\begin{enumerate}
\item We say $f$ is {\it injective} if $\Ker(f) = 0$.
\item We say $f$ is {\it surjective} if $\Coker(f) = 0$.
\end{enumerate}
If $x \to y$ is injective, then we say that $x$ is a {\it subobject}
of $y$ and we use the notation $x \subset y$. If $x \to y$ is
surjective, then we say that $y$ is a {\it quotient} of $x$.
\end{definition}

\begin{lemma}[Characterize injective]
\label{homology-lemma-characterize-injective}
\source{stacks:010C}
\href{https://stacks.math.columbia.edu/tag/010C}{\texttt{Stacks tag 010C}}
\group{homology}

Let $f : x \to y$ be a morphism in an abelian category $\mathcal{A}$. Then
\begin{enumerate}
\item $f$ is injective if and only if $f$ is a monomorphism,
\item $f$ is surjective if and only if $f$ is an epimorphism, and
\item $f$ is an isomorphism if and only if $f$ is injective and surjective.
\end{enumerate}
\end{lemma}

\begin{proof}
\uses{homology-definition-kernel}

Proof of (1). Recall that $\Ker(f)$ is an object representing the
functor sending $z$ to
$\Ker(\Mor_\mathcal{A}(z, x) \to \Mor_\mathcal{A}(z, y))$, see
Definition \ref{homology-definition-kernel}.
Thus $\Ker(f)$ is $0$ if and only if
$\Mor_\mathcal{A}(z, x) \to \Mor_\mathcal{A}(z, y)$
is injective for all $z$ if and only if $f$ is a monomorphism.
The proof of (2) is similar.
For the proof of (3) note that an isomorphism is both a monomorphism
and epimorphism, which by (1), (2) proves $f$ is injective
and surjective. If $f$ is both injective and surjective, then
$x = \Coim(f)$ and $y = \Im(f)$ whence $f$ is an isomorphism.
\end{proof}

In an abelian category, if $x \subset y$ is a subobject,
then we denote
$$
y/x = \Coker(x \to y).
$$

\begin{lemma}[Colimit abelian category]
\label{homology-lemma-colimit-abelian-category}
\source{stacks:010D}
\href{https://stacks.math.columbia.edu/tag/010D}{\texttt{Stacks tag 010D}}
\group{homology}

Let $\mathcal{A}$ be an abelian category.
All finite limits and finite colimits exist in $\mathcal{A}$.
\end{lemma}

\begin{proof}
To show that finite limits exist it suffices to show
that finite products and equalizers exist, see
Categories, Lemma \ref{categories-lemma-finite-limits-exist}.
Finite products exist
by definition and the equalizer of $a, b : x \to y$ is
the kernel of $a - b$. The argument for finite colimits
is similar but dual to this.
\end{proof}

\begin{example}[Fibre product pushouts]
\label{homology-example-fibre-product-pushouts}
\source{stacks:05PJ}
\href{https://stacks.math.columbia.edu/tag/05PJ}{\texttt{Stacks tag 05PJ}}
\group{homology}

Let $\mathcal{A}$ be an abelian category.
Pushouts and fibre products in $\mathcal{A}$ have the following
simple descriptions:
\begin{enumerate}
\item If $a : x \to y$, $b : z \to y$ are morphisms in $\mathcal{A}$, then
we have the fibre product:
$x \times_y z = \Ker((a, -b) : x \oplus z \to y)$.
\item If $a : y \to x$, $b : y \to z$ are morphisms in $\mathcal{A}$, then
we have the pushout:
$x \amalg_y z = \Coker((a, -b) : y \to x \oplus z)$.
\end{enumerate}
\end{example}

\begin{definition}[Exact]
\label{homology-definition-exact}
\source{stacks:010E}
\href{https://stacks.math.columbia.edu/tag/010E}{\texttt{Stacks tag 010E}}
\group{homology}

Let $\mathcal{A}$ be an additive category. Consider a sequence of morphisms
$$
\ldots \to x \to y \to z \to \ldots
\quad\text{or}\quad
x_1 \to x_2 \to \ldots \to x_n
$$
in $\mathcal{A}$. We say such a sequence is a {\it complex} if the
composition of any two consecutive (drawn) arrows is zero.
If $\mathcal{A}$ is abelian then we say a complex of the first
type above is {\it exact at $y$} if $\Im(x \to y) = \Ker(y \to z)$
and we say a complex of the second kind is {\it exact at $x_i$}
where $1 < i < n$ if
$\Im(x_{i - 1} \to x_i) = \Ker(x_i \to x_{i + 1})$. We a
sequence as above is {\it exact} or is an {\it exact sequence} or is an
{\it exact complex} if it is a complex and exact at every object (in
the first case) or exact at $x_i$ for all $1 < i < n$ (in the second case).
There are variants of these notions for sequences of the form
$$
\ldots \to x_{-3} \to x_{-2} \to x_{-1}
\quad\text{and}\quad
x_1 \to x_2 \to x_3 \to \ldots
$$
A {\it short exact sequence} is an exact complex of the form
$$
0 \to A  \to B \to C \to 0.
$$
\end{definition}

In the following lemma we assume the reader knows what it means
for a sequence of abelian groups to be exact.

\begin{lemma}[Check exactness]
\label{homology-lemma-check-exactness}
\source{stacks:05AA}
\href{https://stacks.math.columbia.edu/tag/05AA}{\texttt{Stacks tag 05AA}}
\group{homology}

Let $\mathcal{A}$ be an abelian category.
Let $0 \to M_1 \to M_2 \to M_3 \to 0$ be a complex of $\mathcal{A}$.
\begin{enumerate}
\item $M_1 \to M_2 \to M_3 \to 0$ is exact if and only if
$$
0 \to \Hom_\mathcal{A}(M_3, N) \to
\Hom_\mathcal{A}(M_2, N) \to \Hom_\mathcal{A}(M_1, N)
$$
is an exact sequence of abelian groups for all objects $N$ of
$\mathcal{A}$, and
\item $0 \to M_1 \to M_2 \to M_3$ is exact if and only if
$$
0 \to \Hom_\mathcal{A}(N, M_1) \to \Hom_\mathcal{A}(N, M_2) \to
\Hom_\mathcal{A}(N, M_3)
$$
is an exact sequence of abelian groups for all objects $N$ of $\mathcal{A}$.
\end{enumerate}
\end{lemma}

\begin{proof}
Omitted. Hint: See
Algebra, Lemma \ref{algebra-lemma-hom-exact}.
\end{proof}

\begin{definition}[Ses split]
\label{homology-definition-ses-split}
\source{stacks:010F}
\href{https://stacks.math.columbia.edu/tag/010F}{\texttt{Stacks tag 010F}}
\group{homology}

Let $\mathcal{A}$ be an abelian category.
Let $i : A \to B$ and $q : B \to C$ be morphisms
of $\mathcal{A}$ such that
$0 \to A \to B \to C \to 0$ is a short
exact sequence. We say the short exact
sequence is {\it split} if there exist
morphisms $j : C \to B$ and $p : B \to A$ such
that $(B, i, j, p, q)$ is the direct sum of $A$ and $C$.
\end{definition}

\begin{lemma}[Ses split]
\label{homology-lemma-ses-split}
