\begin{lemma}[Four lemma]
\label{homology-lemma-four-lemma}
\source{stacks:05QA}
\href{https://stacks.math.columbia.edu/tag/05QA}{\texttt{Stacks tag 05QA}}
\group{homology}

Let $\mathcal{A}$ be an abelian category. Let
$$
\begin{array}{cccc}w \longrightarrow\overset{\alpha}{\downarrow} & x \longrightarrow\overset{\beta}{\downarrow} & y \longrightarrow\overset{\gamma}{\downarrow} & z \overset{\delta}{\downarrow} \\ w' \longrightarrow & x' \longrightarrow & y' \longrightarrow & z'\end{array}
$$
be a commutative diagram with exact rows.
\begin{enumerate}
\item If $\alpha, \gamma$ are surjective and $\delta$ is injective, then
$\beta$ is surjective.
\item If $\beta, \delta$ are injective and $\alpha$ is surjective, then
$\gamma$ is injective.
\end{enumerate}
\end{lemma}

\begin{proof}
\uses{homology-lemma-snake}

Assume $\alpha, \gamma$ are surjective and $\delta$ is injective.
We may replace $w'$ by $\Im(w' \to x')$, i.e., we may assume
that $w' \to x'$ is injective.
We may replace $z$ by $\Im(y \to z)$, i.e., we may assume that
$y \to z$ is surjective. Then we may apply
Lemma \ref{homology-lemma-snake}
to
$$
\begin{array}{ccccc} & \Ker(y \to z) \longrightarrow\downarrow & y \longrightarrow\downarrow & z \longrightarrow\downarrow & 0 \\ 0 \longrightarrow & \Ker(y' \to z') \longrightarrow & y' \longrightarrow & z' & \end{array}
$$
to conclude that $\Ker(y \to z) \to \Ker(y' \to z')$ is
surjective. Finally, we apply
Lemma \ref{homology-lemma-snake}
to
$$
\begin{array}{ccccc} & w \longrightarrow\downarrow & x \longrightarrow\downarrow & \Ker(y \to z) \longrightarrow\downarrow & 0 \\ 0 \longrightarrow & w' \longrightarrow & x' \longrightarrow & \Ker(y' \to z') & \end{array}
$$
to conclude that $x \to x'$ is surjective. This proves (1). The proof
of (2) is dual to this.
\end{proof}

