\begin{definition}[Cohomology shift]
\label{homology-definition-cohomology-shift}
\source{stacks:011H}
\href{https://stacks.math.columbia.edu/tag/011H}{\texttt{Stacks tag 011H}}
\group{homology}

Let $\mathcal{A}$ be an abelian category.
