Omitted.
\end{proof}

\begin{lemma}[2 out of 3 computes]
\label{derived-lemma-2-out-of-3-computes}
\source{stacks:05SZ}
\href{https://stacks.math.columbia.edu/tag/05SZ}{\texttt{Stacks tag 05SZ}}
\group{derived}

\uses{derived-situation-derived-functor}
Assumptions and notation as in
Situation \ref{derived-situation-derived-functor}.
Let $(X, Y, Z, f, g, h)$ be a distinguished triangle of $\mathcal{D}$.
If $X, Y$ compute $RF$ then so does $Z$. Similar for $LF$.
\end{lemma}

\begin{proof}
\uses{derived-lemma-2-out-of-3-defined}

By
Lemma \ref{derived-lemma-2-out-of-3-defined}
we know that $RF$ is defined at $Z$ and that $RF$ applied to the
triangle produces a distinguished triangle.
Consider the morphism of distinguished triangles
$$
\begin{array}{c}(F(X), F(Y), F(Z), F(f), F(g), F(h)) \downarrow \\ (RF(X), RF(Y), RF(Z), RF(f), RF(g), RF(h))\end{array}
$$
Two out of three maps are isomorphisms, hence so is the third.
\end{proof}

\begin{lemma}[Direct sum computes]
\label{derived-lemma-direct-sum-computes}
\source{stacks:05T0}
\href{https://stacks.math.columbia.edu/tag/05T0}{\texttt{Stacks tag 05T0}}
\group{derived}

\uses{derived-situation-derived-functor}
Assumptions and notation as in Situation \ref{derived-situation-derived-functor}.
Let $X, Y$ be objects of $\mathcal{D}$. If $X \oplus Y$ computes $RF$, then
$X$ and $Y$ compute $RF$. Similarly for $LF$.
\end{lemma}

\begin{proof}
\uses{derived-lemma-direct-sum-defined}

If $X \oplus Y$ computes $RF$, then $RF(X \oplus Y) = F(X) \oplus F(Y)$.
In the proof of Lemma \ref{derived-lemma-direct-sum-defined} we have seen that
the functor $X/S \times Y/S \to (X \oplus Y)/S$, $(s, s') \mapsto s \oplus s'$
is cofinal. Thus by Categories, Lemma
\ref{categories-lemma-cofinal-essentially-constant} and by
characterization (4) of Categories, Lemma
\ref{categories-lemma-characterize-essentially-constant-ind}
we know that for any object $W$ in $\mathcal{D}'$ the map
$$
\Hom_{\mathcal{D}'}(F(X \oplus Y), W)
\longrightarrow
\colim_{s : X \to X', s' : Y \to Y'} \Hom_{\mathcal{D}'}(F(X' \oplus Y'), W)
$$
is bijective. Since this arrow is clearly compatible with direct sum
decompositions on both sides, we conclude that the map
$$
\Hom_{\mathcal{D}'}(F(X), W)
\longrightarrow
\colim_{s : X \to X'} \Hom_{\mathcal{D}'}(F(X'), W)
$$
is bijective (minor detail omitted). Thus by
Categories, Lemma \ref{categories-lemma-characterize-essentially-constant-ind}
we conclude $RF$ is defined at $X$ with value $F(X)$.
Similarly for $Y$.
\end{proof}

