of $n$-truncated simplicial objects of the
category $\mathcal{C}$. Then
$$
\text{cosk}_n (U \times_V W)
=
\text{cosk}_nU \times_{\text{cosk}_n V} \text{cosk}_nW
$$
whenever the left and right hand side exist.
\end{lemma}

\begin{proof}
\uses{simplicial-lemma-cosk-product}

Omitted, but very similar to the proof of
Lemma \ref{simplicial-lemma-cosk-product} above.
\end{proof}

\begin{lemma}[Cosk above object]
\label{simplicial-lemma-cosk-above-object}
\source{stacks:08NJ}
\href{https://stacks.math.columbia.edu/tag/08NJ}{\texttt{Stacks tag 08NJ}}
