\begin{lemma}[Quasi isomorphism]
\label{simplicial-lemma-quasi-isomorphism}
\source{stacks:019C}
\href{https://stacks.math.columbia.edu/tag/019C}{\texttt{Stacks tag 019C}}
\group{simplicial}

\uses{simplicial-lemma-decompose-associated-complexes}
Let $\mathcal{A}$ be an abelian category.
Let $V$ be a simplicial object of $\mathcal{A}$.
The canonical morphism of chain complexes
$N(V) \to s(V)$ is a quasi-isomorphism.
In other words, the complex $D(V)$ of Lemma
\ref{simplicial-lemma-decompose-associated-complexes} is acyclic.
\end{lemma}

\begin{proof}
\uses{simplicial-lemma-homology-eilenberg-maclane, simplicial-lemma-N-K, simplicial-lemma-eilenberg-maclane-object, simplicial-definition-eilenberg-maclane, simplicial-lemma-n-skeleton-abelian, simplicial-lemma-s-exact, simplicial-lemma-N-exact}

Note that the result holds for $K(A, k)$ for
any object $A$ and any $k \geq 0$, by Lemmas
\ref{simplicial-lemma-homology-eilenberg-maclane} and \ref{simplicial-lemma-N-K}.
Consider the hypothesis $IH_{n, m}$:
for all $V$ such that $V_j = 0$ for
$j \leq m$ and all $i \leq n$ the map
$N(V) \to s(V)$ induces an isomorphism
$H_i(N(V)) \to H_i(s(V))$.

\medskip\noindent
To start of the induction, note that $IH_{n, n}$
is trivially true, because in that case $N(V)_n = 0$
and $s(V)_n = 0$.

\medskip\noindent
Assume $IH_{n, m}$, with $m \leq n$.
Pick a simplicial object $V$ such that
$V_j = 0$ for $j < m$. By Lemma \ref{simplicial-lemma-eilenberg-maclane-object}
and Definition \ref{simplicial-definition-eilenberg-maclane}
we have $K(V_m, m) = i_{m!} \text{sk}_mV$.
By Lemma \ref{simplicial-lemma-n-skeleton-abelian} the natural morphism
$$
K(V_m, m) = i_{m!} \text{sk}_mV \to V
$$
is injective. Thus we get a short exact sequence
$$
0 \to K(V_m, m) \to V \to W \to 0
$$
for some $W$ with $W_i = 0$ for $i = 0, \ldots, m$. This short exact sequence
induces a morphism of short exact sequence of associated complexes
$$
\begin{array}{ccccc}0 \longrightarrow & N(K(V_m, m)) \longrightarrow\downarrow & N(V) \longrightarrow\downarrow & N(W) \longrightarrow\downarrow & 0 \\ 0 \longrightarrow & s(K(V_m, m)) \longrightarrow & s(V) \longrightarrow & s(W) \longrightarrow & 0\end{array}
$$
see Lemmas \ref{simplicial-lemma-s-exact} and \ref{simplicial-lemma-N-exact}.
Hence we deduce the result for $V$ from the result
on the ends.
\end{proof}

\section{Dold-Kan}
\label{simplicial-section-dold-kan}
In this section we prove the Dold-Kan theorem relating
simplicial objects in an abelian category with chain complexes.

\begin{lemma}[N faithful]
\label{simplicial-lemma-N-faithful}
\source{stacks:019E}
\href{https://stacks.math.columbia.edu/tag/019E}{\texttt{Stacks tag 019E}}
\group{simplicial}

Let $\mathcal{A}$ be an abelian category.
The functor $N$ is faithful, and reflects
isomorphisms, injections and surjections.
\end{lemma}

\begin{proof}
\uses{simplicial-lemma-splitting-abelian-category, simplicial-lemma-injective-map-simplicial-abelian}

The faithfulness is immediate from the canonical
splitting of Lemma \ref{simplicial-lemma-splitting-abelian-category}.
The statement on reflecting injections, surjections, and
isomorphisms follows from
Lemma \ref{simplicial-lemma-injective-map-simplicial-abelian}.
\end{proof}

\begin{lemma}[S N]
\label{simplicial-lemma-S-N}
\source{stacks:019F}
\href{https://stacks.math.columbia.edu/tag/019F}{\texttt{Stacks tag 019F}}
\group{simplicial}

Let $\mathcal{A}$ and $\mathcal{B}$ be abelian categories.
Let $N : \mathcal{A} \to \mathcal{B}$, and
$S : \mathcal{B} \to \mathcal{A}$ be functors.
Suppose that
\begin{enumerate}
\item the functors $S$ and $N$ are exact,
\item there is an isomorphism $g : N \circ S \to \text{id}_\mathcal{B}$
to the identity functor of $\mathcal{B}$,
\item $N$ is faithful, and
\item $S$ is essentially surjective.
\end{enumerate}
Then $S$ and $N$ are quasi-inverse equivalences of categories.
\end{lemma}

\begin{proof}
It suffices to construct a functorial
isomorphism $S(N(A)) \cong A$. To do this
choose $B$ and an isomorphism $f : A  \to S(B)$.
Consider the map
$$
f^{-1} \circ g_{S(B)} \circ S(N(f)) :
S(N(A)) \to S(N(S(B))) \to S(B) \to A.
$$
It is easy to show this does not depend on
the choice of $f, B$ and gives the desired
isomorphism $S \circ N \to \text{id}_\mathcal{A}$.
\end{proof}

\begin{theorem}[Dold kan]
\label{simplicial-theorem-dold-kan}
\source{stacks:019G}
\href{https://stacks.math.columbia.edu/tag/019G}{\texttt{Stacks tag 019G}}
\group{simplicial}

Let $\mathcal{A}$ be an abelian category.
The functor $N$ induces an equivalence of
categories
$$
N :
\text{Simp}(\mathcal{A})
\longrightarrow
\text{Ch}_{\geq 0}(\mathcal{A})
$$
\end{theorem}

\begin{proof}
\uses{simplicial-lemma-extension, simplicial-lemma-decompose-associated-complexes, simplicial-remark-degenerate-subcomplex, simplicial-definition-split}

We will describe a functor in the reverse direction
inspired by the construction of Lemma \ref{simplicial-lemma-extension}
(except that we throw in a sign to get the boundaries
right). Let $A_\bullet$ be a chain complex with boundary maps
$d_{A, n} : A_n \to A_{n - 1}$. For each $n \geq 0$ denote
$$
I_n =
\Big\{
\alpha : [n] \to \{0, 1, 2, \ldots\}
\mid
\Im(\alpha) = [k]\text{ for some }k
\Big\}.
$$
For $\alpha \in I_n$ we denote $k(\alpha)$ the unique
integer such that $\Im(\alpha) = [k]$.
We define a simplicial object $S(A_\bullet)$ as follows:
\begin{enumerate}
\item $S(A_\bullet)_n = \bigoplus_{\alpha \in I_n} A_{k(\alpha)}$, which
we will write as
$\bigoplus_{\alpha \in I_n} A_{k(\alpha)} \cdot \alpha$
to suggest thinking of ``$\alpha$'' as a basis vector for the
summand corresponding to it,
\item given $\varphi : [m] \to [n]$ we define
$S(A_\bullet)(\varphi)$ by its restriction to
the direct summand $A_{k(\alpha)} \cdot \alpha$
of $S(A_\bullet)_n$ as follows
\begin{enumerate}
\item $\alpha \circ \varphi \not \in I_m$ then we set it equal to zero,
\item $\alpha \circ \varphi \in I_m$ but $k(\alpha \circ \varphi)$
not equal to either $k(\alpha)$ or $k(\alpha) - 1$ then we set it
equal to zero as well,
\item if $\alpha \circ \varphi \in I_m$
and $k(\alpha \circ \varphi) = k(\alpha)$ then we use
the identity map to the summand
$A_{k(\alpha \circ \varphi)} \cdot (\alpha \circ \varphi)$
of $S(A_\bullet)_m$, and
\item if $\alpha \circ \varphi \in I_m$
and $k(\alpha \circ \varphi) = k(\alpha) - 1$
then we use $(-1)^{k(\alpha)} d_{A, k(\alpha)}$ to the summand
$A_{k(\alpha \circ \varphi)}\cdot (\alpha \circ \varphi)$
of $S(A_\bullet)_m$.
\end{enumerate}
\end{enumerate}
Let us show that $S(A_\bullet)$ is a simplicial object of $\mathcal{A}$.
To do this, assume we have maps $\varphi : [m] \to [n]$ and
$\psi : [n] \to [p]$. We will show that
$S(A_\bullet)(\varphi) \circ S(A_\bullet)(\psi) =
S(A_\bullet)(\psi \circ \varphi)$. Choose $\beta \in I_p$ and set
$\alpha = \beta \circ \psi$ and $\gamma = \alpha \circ \varphi$
viewed as maps $\alpha : [n] \to \{0, 1, 2, \ldots\}$
and $\gamma : [m] \to \{0, 1, 2, \ldots\}$. Picture
$$
\begin{array}{ccc}[m] \underset{\varphi}{\longrightarrow}\underset{\gamma}{\downarrow} & [n] \underset{\psi}{\longrightarrow}\underset{\alpha}{\downarrow} & [p] \overset{\beta}{\downarrow} \\ \Im(\gamma) \longrightarrow & \Im(\alpha) \longrightarrow & [k(\beta)]\end{array}
$$
We will show that the restriction of the maps
$S(A_\bullet)(\varphi) \circ S(A_\bullet)(\psi)$ and
$S(A_\bullet)(\psi \circ \varphi)$.
to the summand $A_{k(\beta)} \cdot \beta$ agree.
There are several cases to consider
\begin{enumerate}
\item Say $\alpha \not \in I_n$ so the restriction of
$S(A_\bullet)(\psi)$ to $A_{k(\beta)} \cdot \beta$ is zero.
Then either $\gamma \not \in I_m$ or we have
$[k(\gamma)] = \Im(\gamma) \subset \Im(\alpha) \subset [k(\beta)]$
and the subset $\Im(\alpha)$ of $[k(\beta)]$ has a gap so
$k(\gamma) < k(\beta) - 1$. In both cases we see that
the restriction of
$S(A_\bullet)(\psi \circ \varphi)$ to $A_{k(\beta)} \cdot \beta$
is zero as well.
\item Say $\alpha \in I_n$ and $k(\alpha) < k(\beta) - 1$ so the restriction of
$S(A_\bullet)(\psi)$ to $A_{k(\beta)} \cdot \beta$ is zero.
Then either $\gamma \not \in I_m$ or we have
$[k(\gamma)] \subset [k(\alpha)] \subset [k(\beta)]$
and it follows that $k(\gamma) < k(\beta) - 1$. In both cases we see that
the restriction of
$S(A_\bullet)(\psi \circ \varphi)$ to $A_{k(\beta)} \cdot \beta$
is zero as well.
\item Say $\alpha \in I_n$ and $k(\alpha) = k(\beta)$ so the restriction of
$S(A_\bullet)(\psi)$ to $A_{k(\beta)} \cdot \beta$ is
the identity map from $A_{k(\beta)} \cdot \beta$ to
$A_{k(\alpha)} \cdot \alpha$. In this case because $\Im(\alpha) =[k(\beta)]$
the rule describing the restriction of $S(A_\bullet)(\psi \circ \varphi)$
to the summand $A_{k(\beta)} \cdot \beta$ is exactly the same
as the rule describing the restriction of $S(A_\bullet)(\varphi)$
to the summand $A_{k(\alpha)} \cdot \alpha$ and hence agreement holds.
\item Say $\alpha \in I_n$ and $k(\alpha) = k(\beta) - 1$
so the restriction of $S(A_\bullet)(\psi)$ to $A_{k(\beta)} \cdot \beta$
is given by $(-1)^{k(\beta)}d_{A, k(\beta)}$ to $A_{k(\alpha)} \cdot \alpha$.
Subcases
\begin{enumerate}
\item If $\gamma \not \in I_m$, then both the restriction of
$S(A_\bullet)(\psi \circ \varphi)$ to the summand $A_{k(\beta)} \cdot \beta$
and the restriction of $S(A_\bullet)(\varphi)$ to the summand
$A_{k(\alpha)} \cdot \alpha$ are zero and we get agreement.
\item If $\gamma \in I_m$ but $k(\gamma) < k(\alpha) - 1$, then
again both restrictions are zero and we get agreement.
\item If $\gamma \in I_m$ and $k(\gamma) = k(\alpha)$ then
$\Im(\gamma) = \Im(\alpha)$. In this case
the restriction of $S(A_\bullet)(\psi \circ \varphi)$
to the summand $A_{k(\beta)} \cdot \beta$ is given by
$(-1)^{k(\beta)}d_{A, k(\beta)}$ to $A_{k(\gamma)} \cdot \gamma$
and the restriction of $S(A_\bullet)(\varphi)$ to the summand
$A_{k(\alpha)} \cdot \alpha$ is the identity map
$A_{k(\alpha)} \cdot \alpha \to A_{k(\gamma)} \cdot \gamma$.
Hence agreement holds.
\item Finally, if $\gamma \in I_m$ and $k(\gamma) = k(\alpha) - 1$ then
the restriction of $S(A_\bullet)(\varphi)$ to the summand
$A_{k(\alpha)} \cdot \alpha$ is given by $(-1)^{k(\alpha)} d_{A, k(\alpha)}$
as a map
$A_{k(\alpha)} \cdot \alpha \to A_{k(\beta)} \cdot \beta$.
Since $A_\bullet$ is a complex we see that the composition
$A_{k(\beta)} \cdot \beta \to
A_{k(\alpha)} \cdot \alpha \to A_{k(\gamma)} \cdot \gamma$ is zero
which matches what we get for the restriction of
$S(A_\bullet)(\psi \circ \varphi)$
to the summand $A_{k(\beta)} \cdot \beta$
because $k(\gamma) = k(\beta) - 2 < k(\beta) - 1$.
\end{enumerate}
\end{enumerate}
Thus $S(A_\bullet)$ is a simplicial object of $\mathcal{A}$.

\medskip\noindent
Let us construct an isomorphism $A_\bullet \to N(S(A_\bullet))$
functorial in $A_\bullet$. Recall that
$$
S(A_\bullet) =  N(S(A_\bullet)) \oplus D(S(A_\bullet))
$$
as chain complexes by Lemma \ref{simplicial-lemma-decompose-associated-complexes}.
On the other hand it follows from Remark \ref{simplicial-remark-degenerate-subcomplex}
and the construction of $S(A_\bullet)$ that
$$
D(S(A_\bullet))_n =
\bigoplus\nolimits_{\alpha \in I_n,\ k(\alpha) < n} A_{k(\alpha)} \cdot \alpha
\subset
\bigoplus\nolimits_{\alpha \in I_n} A_{k(\alpha)} \cdot \alpha
$$
However, if $\alpha \in I_n$ then we have
$k(\alpha) \geq n \Leftrightarrow \alpha = \text{id}_{[n]} : [n] \to [n]$.
Thus the summand $A_n \cdot \text{id}_{[n]}$ of $S(A_\bullet)_n$
is a complement to the summand $D(S(A_\bullet))_n$.
All the maps $d^n_i : S(A_\bullet)_n \to S(A_\bullet)_n$
restrict to zero on the summand $A_n \cdot \text{id}_{[n]}$
except for $d^n_n$ which produces $(-1)^n d_{A, n}$
from $A_n \cdot \text{id}_{[n]}$ to $A_{n - 1} \cdot \text{id}_{[n - 1]}$.
We conclude that $A_n \cdot \text{id}_{[n]}$ must be
equal to the summand $N(S(A_\bullet))_n$ and moreover
the restriction of the differential
$d_n = \sum (-1)^id^n_i : S(A_\bullet)_n \to S(A_\bullet)_{n - 1}$
to the summand $A_n \cdot \text{id}_{[n]}$ gives what we want!

\medskip\noindent
Finally, we have to show that $S \circ N$ is isomorphic to the
identity functor. Let $U$ be a simplicial object of $\mathcal{A}$.
Then we can define an obvious map
$$
S(N(U))_n = \bigoplus\nolimits_{\alpha \in I_n} N(U)_{k(\alpha)} \cdot \alpha
\longrightarrow
U_n
$$
by using $U(\alpha) : N(U)_{k(\alpha)} \to U_n$ on the summand corresponding
to $\alpha$. By Definition \ref{simplicial-definition-split} this is an isomorphism.
To finish the proof we have to show that this is compatible with
the maps in the simplicial objects. Thus let $\varphi : [m] \to [n]$
and let $\alpha \in I_n$. Set $\beta = \alpha \circ \varphi$.
Picture
$$
\begin{array}{cc}[m] \underset{\varphi}{\longrightarrow}\underset{\beta}{\downarrow} & [n] \underset{\alpha}{\downarrow} \\ \Im(\beta) \longrightarrow & [k(\alpha)]\end{array}
$$
There are several cases to consider
\begin{enumerate}
\item Say $\beta \not \in I_m$. Then there exists an index
$0 \leq j < k(\alpha)$ with $j \not \in \Im(\alpha \circ \varphi)$
and hence we can choose a factorization
$\alpha \circ \varphi = \delta^{k(\alpha)}_j \circ \psi$
for some $\psi : [m] \to [k(\alpha) - 1]$.
It follows that $U(\varphi)$ is zero on the image of the summand
$N(U)_{k(\alpha)} \cdot \alpha$ because $U(\varphi) \circ U(\alpha) =
U(\alpha \circ \varphi) = U(\psi) \circ d^{k(\alpha)}_j$
is zero on $N(U)_{k(\alpha)}$ by construction of $N$.
This matches our rule for $S(N(U))$ given above.
\item Say $\beta \in I_m$ and $k(\beta) < k(\alpha) - 1$. Here we
argue exactly as in case (1) with $j = k(\alpha) - 1$.
\item Say $\beta \in I_m$ and $k(\beta) = k(\alpha)$. Here
the summand $N(U)_{k(\alpha)} \cdot \alpha$ is mapped by the
identity to the summand $N(U)_{k(\beta)} \cdot \beta$.
This is the same as the effect of $U(\varphi)$ since in
this case $U(\varphi) \circ U(\alpha) = U(\beta)$.
\item Say $\beta \in I_m$ and $k(\beta) = k(\alpha) - 1$.
Here we use the differential $(-1)^{k(\alpha)} d_{N(U), k(\alpha)}$
to map the summand $N(U)_{k(\alpha)} \cdot \alpha$
to the summand $N(U)_{k(\beta)} \cdot \beta$.
On the other hand, since $\Im(\beta) = [k(\beta)]$ in this case
we get $\alpha \circ \varphi = \delta^{k(\alpha)}_{k(\alpha)} \circ \beta$.
Thus we see that $U(\varphi)$ composed with the restriction of
$U(\alpha)$ to $N(U)_{k(\alpha)}$ is equal to
$U(\beta)$ precomposed with $d^{k(\alpha)}_{k(\alpha)}$ restricted to
$N(U)_{k(\alpha)}$.
Since $d_{N(U), k(\alpha)} = \sum (-1)^i d^{k(\alpha)}_i$
and since $d^{k(\alpha)}_i$ restricts to zero on
$N(U)_{k(\alpha)}$ for $i < k(\alpha)$
we see that equality holds.
\end{enumerate}
This finishes the proof of the theorem.
\end{proof}

\section{Dold-Kan for cosimplicial objects}
\label{simplicial-section-dold-kan-cosimplicial}
Let $\mathcal{A}$ be an abelian category.
According to Homology, Lemma \ref{homology-lemma-abelian-opposite}
also $\mathcal{A}^{opp}$ is abelian. It follows
formally from the definitions that
$$
\text{CoSimp}(\mathcal{A}) = \text{Simp}(\mathcal{A}^{opp})^{opp}.
$$
Thus Dold-Kan
(Theorem \ref{simplicial-theorem-dold-kan})
implies that $\text{CoSimp}(\mathcal{A})$ is equivalent to
the category
$\text{Ch}_{\geq 0}(\mathcal{A}^{opp})^{opp}$. And it
follows formally from the definitions that
$$
\text{CoCh}_{\geq 0}(\mathcal{A}) =
\text{Ch}_{\geq 0}(\mathcal{A}^{opp})^{opp}.
$$
Putting these arrows together we obtain an equivalence
$$
Q :
\text{CoSimp}(\mathcal{A})
\longrightarrow
\text{CoCh}_{\geq 0}(\mathcal{A}).
$$
In this section we describe $Q$.

\medskip\noindent
First we define the
{\it cochain complex $s(U)$ associated to a cosimplicial
object $U$}. It is the cochain complex with terms zero in
negative degrees, and $s(U)^n = U_n$ for $n \geq 0$.
As differentials we use the maps
$d^n : s(U)^n \to s(U)^{n + 1}$ defined by
$d^n = \sum_{i = 0}^{n + 1} (-1)^i \delta^{n + 1}_i$.
In other words the complex $s(U)$ looks like
$$
\begin{array}{ccccccc}0 \longrightarrow & U_0 \overset{\delta^1_0 - \delta^1_1}{\longrightarrow} &  & U_1 \overset{\delta^2_0 - \delta^2_1 + \delta^2_2}{\longrightarrow} &  & U_2 \longrightarrow & \ldots\end{array}
$$
This is sometimes also called the {\it Moore complex} associated
to $U$.

\medskip\noindent
On the other hand, given a
cosimplicial object $U$ of $\mathcal{A}$ set
$Q(U)^0 = U_0$ and
$$
Q(U)^n = \Coker(
\begin{array}{cc}\bigoplus_{i = 0}^{n - 1} U_{n - 1} \overset{\delta^n_i}{\longrightarrow} & U_n\end{array}).
$$
The differential $d^n : Q(U)^n \to Q(U)^{n + 1}$
is induced by $(-1)^{n + 1}\delta^{n + 1}_{n + 1}$, i.e., by
fitting the morphism
$(-1)^{n + 1}\delta^{n + 1}_{n + 1}$
into a commutative
diagram
$$
\begin{array}{ccc}U_n \underset{(-1)^{n + 1}\delta^{n + 1}_{n + 1}}{\longrightarrow}\downarrow &  & U_{n + 1} \downarrow \\ Q(U)^n \overset{d_n}{\longrightarrow} &  & Q(U)^{n + 1}.\end{array}
$$
We leave it to the reader to show that this diagram makes
sense, i.e., that the image of $\delta^n_i$ maps into
the kernel of the right vertical arrow for $i = 0, \ldots, n - 1$.
(This is dual to Lemma \ref{simplicial-lemma-N-d-in-N}.)
Thus our cochain complex $Q(U)$ looks like this
$$
0 \to Q(U)^0 \to Q(U)^1 \to Q(U)^2 \to \ldots
$$
This is called the {\it normalized cochain complex associated
to $U$}.
The dual to the Dold-Kan Theorem \ref{simplicial-theorem-dold-kan} is the following.

\begin{lemma}[Dual dold kan]
\label{simplicial-lemma-dual-dold-kan}
\source{stacks:019I}
\href{https://stacks.math.columbia.edu/tag/019I}{\texttt{Stacks tag 019I}}
\group{simplicial}

Let $\mathcal{A}$ be an abelian category.
\begin{enumerate}
\item The functor
$s : \text{CoSimp}(\mathcal{A}) \to \text{CoCh}_{\geq 0}(\mathcal{A})$
is exact.
\item The maps $s(U)^n \to Q(U)^n$ define a morphism
of cochain complexes.
\item There exists a functorial direct sum decomposition
$s(U) = D(U) \oplus Q(U)$ in $\text{CoCh}_{\geq 0}(\mathcal{A})$.
\item The functor $Q$ is exact.
\item The morphism of complexes $s(U) \to Q(U)$ is a quasi-isomorphism.
\item The functor $U \mapsto Q(U)^\bullet$ defines
an equivalence of categories
$\text{CoSimp}(\mathcal{A}) \to \text{CoCh}_{\geq 0}(\mathcal{A})$.
\end{enumerate}
\end{lemma}

\begin{proof}
\uses{simplicial-lemma-s-exact, simplicial-lemma-map-associated-complexes, simplicial-lemma-decompose-associated-complexes, simplicial-lemma-N-exact, simplicial-lemma-quasi-isomorphism, simplicial-theorem-dold-kan}

Omitted. But the results are the exact dual statements to
Lemmas \ref{simplicial-lemma-s-exact}, \ref{simplicial-lemma-map-associated-complexes},
\ref{simplicial-lemma-decompose-associated-complexes},
\ref{simplicial-lemma-N-exact}, \ref{simplicial-lemma-quasi-isomorphism}, and
Theorem \ref{simplicial-theorem-dold-kan}.
\end{proof}

\section{Homotopies}
\label{simplicial-section-homotopy}
Consider the simplicial sets $\Delta[0]$ and $\Delta[1]$.
Recall that there are two morphisms
$$
e_0, e_1 : \Delta[0] \longrightarrow \Delta[1],
$$
coming from the morphisms $[0] \to [1]$ mapping
$0$ to an element of $[1] = \{0, 1\}$. Recall also that each
set $\Delta[1]_k$ is finite. Hence, if the category
$\mathcal{C}$ has finite coproducts, then we can
form the product
$$
U \times \Delta[1]
$$
for any simplicial object $U$ of $\mathcal{C}$, see
Definition \ref{simplicial-definition-product-with-simplicial-set}.
Note that $\Delta[0]$ has the property that $\Delta[0]_k = \{*\}$
is a singleton for all $k \geq 0$. Hence $U \times \Delta[0]
= U$. Thus $e_0, e_1$ above gives rise to morphisms
$$
e_0, e_1 : U \to U \times \Delta[1].
$$

\begin{definition}[Homotopy]
\label{simplicial-definition-homotopy}
\source{stacks:019K}
\href{https://stacks.math.columbia.edu/tag/019K}{\texttt{Stacks tag 019K}}
\group{simplicial}

Let $\mathcal{C}$ be a category having finite coproducts.
Suppose that $U$ and $V$ are two simplicial objects of $\mathcal{C}$.
Let $a, b : U \to V$ be two morphisms.
\begin{enumerate}
\item We say a morphism
$$
h : U \times \Delta[1] \longrightarrow V
$$
is a {\it homotopy from $a$ to $b$} if $a = h \circ e_0$ and
$b = h \circ e_1$.
\item We say the morphisms $a$ and $b$ are {\it homotopic} or are
{\it in the same homotopy class}
if there exists a sequence of morphisms $a = a_0, a_1, \ldots, a_n = b$
from $U$ to $V$ such that for each $i = 1, \ldots, n$ there either exists
a homotopy from $a_{i - 1}$ to $a_i$ or there exists a homotopy
from $a_i$ to $a_{i - 1}$.
\end{enumerate}
\end{definition}

The relation ``there is a homotopy from $a$ to $b$'' is in general not
transitive or symmetric; we will see it is reflexive in
Example \ref{simplicial-example-trivial-homotopy}. Of course, ``being homotopic''
is an equivalence relation on the set $\Mor(U, V)$ and it is the
equivalence relation generated by the relation
``there is a homotopy from $a$ to $b$'' .
It turns out we can define homotopies between pairs of maps of simplicial
objects in any category. We will do this in Remark \ref{simplicial-remark-homotopy-better}
after we work out in some detail what it means to have a morphism
$h : U \times \Delta[1] \to V$.

\medskip\noindent
Let $\mathcal{C}$ be a category with finite coproducts.
Let $U$, $V$ be simplicial objects of $\mathcal{C}$.
Let $a, b : U \to V$ be morphisms. Further, suppose
that $h : U \times \Delta[1] \to V$ is a homotopy
from $a$ to $b$. For every $n \geq 0$
let us write
$$
\Delta[1]_n = \{\alpha^n_0, \ldots, \alpha^n_{n + 1}\}
$$
where $\alpha^n_i : [n] \to [1]$ is the map
such that
$$
\alpha^n_i(j)
=
\left\{
\begin{matrix}
0 & \text{if} & j < i\\
1 & \text{if} & j \geq i
\end{matrix}
\right.
$$
Thus
$$
h_n : (U \times \Delta[1])_n = \coprod U_n \cdot \alpha^n_i
\longrightarrow
V_n
$$
has a component $h_{n, i} : U_n \to V_n$ which is the restriction
to the summand corresponding to $\alpha^n_i$ for all $i = 0, \ldots, n + 1$.

\begin{lemma}[Relations homotopy]
\label{simplicial-lemma-relations-homotopy}
\source{stacks:019L}
\href{https://stacks.math.columbia.edu/tag/019L}{\texttt{Stacks tag 019L}}
\group{simplicial}

In the situation above, we have the following relations:
\begin{enumerate}
\item We have $h_{n, 0} = b_n$ and $h_{n, n + 1} = a_n$.
\item We have $d^n_j \circ h_{n, i} = h_{n - 1, i - 1} \circ d^n_j$
for $i > j$.
\item We have $d^n_j \circ h_{n, i} = h_{n - 1, i} \circ d^n_j$
for $i \leq j$.
\item We have $s^n_j \circ h_{n, i} = h_{n + 1, i + 1} \circ s^n_j$
for $i > j$.
\item We have $s^n_j \circ h_{n, i} = h_{n + 1, i} \circ s^n_j$
for $i \leq j$.
\end{enumerate}
Conversely, given a system of maps $h_{n, i}$ satisfying the
properties listed above, then these define a morphism
$h$ which is a homotopy from $a$ to $b$.
\end{lemma}

\begin{proof}
\uses{simplicial-lemma-face-degeneracy-category}

Omitted. You can prove the last statement using the fact,
see Lemma \ref{simplicial-lemma-face-degeneracy-category} that
to give a morphism of simplicial objects is the
same as giving a sequence of morphisms $h_n$ commuting
with all $d^n_j$ and $s^n_j$.
\end{proof}

\begin{example}[Trivial homotopy]
\label{simplicial-example-trivial-homotopy}
\source{stacks:07KA}
\href{https://stacks.math.columbia.edu/tag/07KA}{\texttt{Stacks tag 07KA}}
\group{simplicial}

Suppose in the situation above $a = b$. Then there is a {\it trivial}
homotopy from $a$ to $b$, namely the one with $h_{n, i} = a_n = b_n$.
\end{example}

\begin{remark}[Homotopy better]
\label{simplicial-remark-homotopy-better}
\source{stacks:019M}
\href{https://stacks.math.columbia.edu/tag/019M}{\texttt{Stacks tag 019M}}
\group{simplicial}

\uses{simplicial-lemma-relations-homotopy, simplicial-definition-homotopy}
Let $\mathcal{C}$ be any category (no assumptions whatsoever). Let
$U$ and $V$ be simplicial objects of $\mathcal{C}$. Let $a, b : U \to V$
be morphisms of simplicial objects of $\mathcal{C}$. A
{\it homotopy from $a$ to $b$} is given by
morphisms\footnote{In the literature, often the maps
$h_{n + 1, i} \circ s_i : U_n \to V_{n + 1}$ are used instead
of the maps $h_{n, i}$. Of course the relations these maps satisfy
are different from the ones in Lemma \ref{simplicial-lemma-relations-homotopy}.}
$h_{n, i} : U_n \to V_n$, for $n \geq 0$, $i = 0, \ldots, n + 1$
satisfying the relations of Lemma \ref{simplicial-lemma-relations-homotopy}.
As in Definition \ref{simplicial-definition-homotopy} we say the morphisms $a$ and $b$
are {\it homotopic} if there exists a sequence of morphisms
$a = a_0, a_1, \ldots, a_n = b$ from $U$ to $V$ such that for each
$i = 1, \ldots, n$ there either exists a homotopy from $a_{i - 1}$ to $a_i$
or there exists a homotopy from $a_i$ to $a_{i - 1}$.
Clearly, if $F : \mathcal{C} \to \mathcal{C}'$ is any functor
and $\{h_{n, i}\}$ is a homotopy from $a$ to $b$, then
$\{F(h_{n, i})\}$ is a homotopy from $F(a)$ to $F(b)$.
Similarly, if $a$ and $b$ are homotopic, then $F(a)$ and $F(b)$
are homotopic.
Since the lemma says that the newer notion is the same
as the old one in case finite coproduct exist, we deduce
in particular that functors preserve the original notion
whenever both categories have finite coproducts.
\end{remark}

\begin{remark}[Homotopy pre post compose]
\label{simplicial-remark-homotopy-pre-post-compose}
\source{stacks:08RJ}
\href{https://stacks.math.columbia.edu/tag/08RJ}{\texttt{Stacks tag 08RJ}}
\group{simplicial}

Let $\mathcal{C}$ be any category. Suppose two morphisms $a, a' : U \to V$
of simplicial objects are homotopic. Then for any morphism $b : V \to W$
the two maps $b \circ a, b \circ a' : U \to W$ are homotopic.
Similarly, for any morphism $c : X \to U$ the two maps
$a \circ c, a' \circ c : X \to V$ are homotopic. In fact the maps
$b \circ a \circ c, b \circ a' \circ c : X \to W$ are homotopic.
Namely, if the maps $h_{n, i} : U_n \to V_n$ define a homotopy from
$a$ to $a'$ then the maps $b \circ h_{n, i} \circ c$ define a homotopy
from $b \circ a \circ c$ to $b \circ a' \circ c$. In this way we see that
we obtain a new category $\text{hSimp}(\mathcal{C})$ with the same
objects as $\text{Simp}(\mathcal{C})$ but whose morphisms are
homotopy classes of morphisms of $\text{Simp}(\mathcal{C})$.
Thus there is a canonical functor
$$
\text{Simp}(\mathcal{C})
\longrightarrow
\text{hSimp}(\mathcal{C})
$$
which is essentially surjective and surjective on sets of morphisms.
\end{remark}

\begin{definition}[Homotopy equivalent]
\label{simplicial-definition-homotopy-equivalent}
\source{stacks:019N}
\href{https://stacks.math.columbia.edu/tag/019N}{\texttt{Stacks tag 019N}}
\group{simplicial}

Let $U$ and $V$ be two simplicial objects of a category $\mathcal{C}$.
We say a morphism $a : U \to V$ is a {\it homotopy equivalence}
if there exists a morphism $b : V \to U$ such that $a \circ b$ is
homotopic to $\text{id}_V$ and $b \circ a$ is homotopic to $\text{id}_U$.
We say $U$ and $V$ are {\it homotopy equivalent} if there
exists a homotopy equivalence $a : U \to V$.
\end{definition}

\begin{example}[Simplex contractible]
\label{simplicial-example-simplex-contractible}
\source{stacks:08Q3}
\href{https://stacks.math.columbia.edu/tag/08Q3}{\texttt{Stacks tag 08Q3}}
\group{simplicial}

The simplicial set $\Delta[m]$ is homotopy equivalent to $\Delta[0]$.
Namely, consider the unique morphism $f : \Delta[m] \to \Delta[0]$ and
the morphism $g : \Delta[0] \to \Delta[m]$ given by the inclusion of the
last $0$-simplex of $\Delta[m]$. We have $f \circ g = \text{id}$.
We will give a homotopy $h : \Delta[m] \times \Delta[1] \to \Delta[m]$
from $\text{id}_{\Delta[m]}$ to $g \circ f$. Namely $h$ is given by
the maps
$$
\Mor_\Delta([n], [m]) \times \Mor_\Delta([n], [1]) \to \Mor_\Delta([n], [m])
$$
which send $(\varphi, \alpha)$ to
$$
k \mapsto
\left\{
\begin{matrix}
\varphi(k) & \text{if} & \alpha(k) = 0 \\
m & \text{if} & \alpha(k) = 1
\end{matrix}
\right.
$$
Note that this only works because we took $g$ to be the inclusion of the
last $0$-simplex. If we took $g$ to be the inclusion of the first $0$-simplex
we could find a homotopy from $g \circ f$ to $\text{id}_{\Delta[m]}$.
This is an illustration of the asymmetry inherent in homotopies in the
category of simplicial sets.
\end{example}

The following lemma says that $U \times \Delta[1]$
is homotopy equivalent to $U$.

\begin{lemma}[Contractible]
\label{simplicial-lemma-contractible}
\source{stacks:019O}
\href{https://stacks.math.columbia.edu/tag/019O}{\texttt{Stacks tag 019O}}
\group{simplicial}

\uses{simplicial-lemma-back-to-U}
Let $\mathcal{C}$ be a category with finite coproducts.
Let $U$ be a simplicial object of $\mathcal{C}$.
Consider the maps $e_1, e_0 : U \to U \times \Delta[1]$,
and $\pi : U \times \Delta[1] \to U$, see
Lemma \ref{simplicial-lemma-back-to-U}.
\begin{enumerate}
\item We have $\pi \circ e_1 = \pi \circ e_0 = \text{id}_U$, and
\item The morphisms $\text{id}_{U \times \Delta[1]}$,
and $e_0 \circ \pi$ are homotopic.
\item The morphisms $\text{id}_{U \times \Delta[1]}$,
and $e_1 \circ \pi$ are homotopic.
\end{enumerate}
\end{lemma}

\begin{proof}
\uses{simplicial-lemma-back-to-U}

The first assertion is trivial. Consider the map of simplicial sets
$\Delta[1] \times \Delta[1] \longrightarrow \Delta[1]$
which in degree $n$ assigns to a pair $(\beta_1, \beta_2)$,
$\beta_i : [n] \to [1]$ the morphism
$\beta : [n] \to [1]$ defined by the rule
$$
\beta(i) = \max\{\beta_1(i), \beta_2(i)\}.
$$
It is a morphism of simplicial sets, because the action
$\Delta[1](\varphi) : \Delta[1]_n \to \Delta[1]_m$
of $\varphi : [m] \to [n]$ is by precomposing.
Using the notation $\Delta[1]_n = \{\alpha^n_0, \ldots, \alpha^n_{n + 1}\}$
introduced above, we have $\beta = \alpha^n_0$ if $\beta_2 = \alpha^n_0$
and $\beta = \beta_1$ if $\beta_2 = \alpha^n_{n + 1}$.
Since $\alpha^n_0$, resp.\ $\alpha^n_{n + 1}$ is the constant map
with value $1$, resp.\ $0$, this implies that the induced morphism
$$
U \times \Delta[1] \times \Delta[1]
\longrightarrow
U \times \Delta[1]
$$
of Lemma \ref{simplicial-lemma-back-to-U}
is a homotopy from $\text{id}_{U \times \Delta[1]}$ to $e_1 \circ \pi$.
Similarly for $e_0 \circ \pi$ (use minimum instead of maximum).
\end{proof}

\begin{lemma}[Fibre products simplicial object w section]
\label{simplicial-lemma-fibre-products-simplicial-object-w-section}
\source{stacks:019P}
\href{https://stacks.math.columbia.edu/tag/019P}{\texttt{Stacks tag 019P}}
\group{simplicial}

\uses{simplicial-example-fibre-products-simplicial-object}
Let $f : Y \to X$ be a morphism of a category $\mathcal{C}$ with
fibre products. Assume $f$ has a section $s$. Consider the
simplicial object $U$ constructed in
Example \ref{simplicial-example-fibre-products-simplicial-object}
starting with $f$. The morphism $U \to U$ which in each degree
is the self map $(s \circ f)^{n + 1}$ of $Y \times_X \ldots \times_X Y$
given by $s \circ f$ on each factor is homotopic to the identity on $U$.
In particular, $U$ is homotopy equivalent to the constant
simplicial object $X$.
\end{lemma}

\begin{proof}
\uses{simplicial-lemma-relations-homotopy, simplicial-remark-homotopy-better}

Set $g^0 = \text{id}_Y$ and $g^1 = s \circ f$.
We use the morphisms
\begin{eqnarray*}
Y \times_X \ldots \times_X Y \times \Mor([n], [1])
& \to &
Y \times_X \ldots \times_X Y \\
(y_0, \ldots, y_n) \times \alpha
& \mapsto &
(g^{\alpha(0)}(y_0), \ldots, g^{\alpha(n)}(y_n))
\end{eqnarray*}
where we use the functor of points point of view to define the maps.
Another way to say this is to say that
$h_{n, 0} = \text{id}$, $h_{n, n + 1} = (s \circ f)^{n + 1}$ and
$h_{n, i} = \text{id}_Y^{i + 1} \times (s \circ f)^{n + 1 - i}$.
We leave it to the reader to show that these satisfy the relations
of Lemma \ref{simplicial-lemma-relations-homotopy}. Hence they define
the desired homotopy. See also Remark \ref{simplicial-remark-homotopy-better}
which shows that
we do not need to assume anything else on the category $\mathcal{C}$.
\end{proof}

\begin{lemma}[Products homotopy]
\label{simplicial-lemma-products-homotopy}
\source{stacks:08Q4}
\href{https://stacks.math.columbia.edu/tag/08Q4}{\texttt{Stacks tag 08Q4}}
\group{simplicial}

Let $\mathcal{C}$ be a category. Let $T$ be a set. For $t \in T$
let $X_t$, $Y_t$ be simplicial objects of $\mathcal{C}$. Assume
$X = \prod_{t \in T} X_t$ and $Y = \prod_{t \in T} Y_t$ exist.
\begin{enumerate}
\item If $X_t$ and $Y_t$ are homotopy equivalent for all $t \in T$
and $T$ is finite, then $X$ and $Y$ are homotopy equivalent.
\end{enumerate}
For $t \in T$ let $a_t, b_t : X_t \to Y_t$ be morphisms.
Set $a = \prod a_t : X \to Y$ and $b = \prod b_t : X \to Y$.
\begin{enumerate}
\item[(2)] If there exists a homotopy from $a_t$ to $b_t$ for
all $t \in T$, then there exists a homotopy from $a$ to $b$.
\item[(3)] If $T$ is finite and $a_t, b_t : X_t \to Y_t$ for $t \in T$
are homotopic, then $a$ and $b$ are homotopic.
\end{enumerate}
\end{lemma}

\begin{proof}
\uses{simplicial-remark-homotopy-better, simplicial-example-trivial-homotopy}

If $h_t = (h_{t, n , i})$ is a homotopy from $a_t$ to $b_t$
(see Remark \ref{simplicial-remark-homotopy-better}), then
$h = (\prod_t h_{t, n, i})$ is a homotopy from $\prod a_t$ to $\prod b_t$.
This proves (2).

\medskip\noindent
Proof of (3). Choose $t \in T$. There exists an integer $n \geq 0$
and a chain $a_t = a_{t, 0}, a_{t, 1}, \ldots, a_{t, n} = b_t$ such that
for every $1 \leq i \leq n$ either there is a homotopy from
$a_{t, i - 1}$ to $a_{t, i}$ or there is a homotopy from
$a_{t, i}$ to $a_{t, i - 1}$. If $n = 0$, then we pick another $t$.
(We're done if $a_t = b_t$ for all $t \in T$.) So assume $n > 0$.
By Example \ref{simplicial-example-trivial-homotopy}
there are is a homotopy from $b_{t'}$ to $b_{t'}$ for all
$t' \in T \setminus \{t\}$. Thus by (2) there is a homotopy from
$a_{t, n - 1} \times \prod_{t'} b_{t'}$ to $b$ or there is a
homotopy from $b$ to $a_{t, n - 1} \times \prod_{t'} b_{t'}$.
In this way we can decrease $n$ by $1$. This proves (3).

\medskip\noindent
Part (1) follows from part (3) and the definitions.
\end{proof}

\section{Homotopies in abelian categories}
\label{simplicial-section-homotopy-abelian}
Let $\mathcal{A}$ be an additive category. Let $U$, $V$ be simplicial objects
of $\mathcal{A}$. Let $a, b : U \to V$ be morphisms. Further, suppose that
$h : U \times \Delta[1] \to V$ is a homotopy from $a$ to $b$. Let us prove
the two morphisms of chain complexes $s(a), s(b) : s(U) \longrightarrow s(V)$
are homotopic in the sense of
Homology, Section \ref{homology-section-complexes}.
Using the notation introduced in Section \ref{simplicial-section-homotopy}
we define
$$
s(h)_n : U_n \longrightarrow V_{n + 1}
$$
by the formula
\begin{equation}
\label{equation-homotopy-to-homotopy}
s(h)_n = \sum\nolimits_{i = 0}^n (-1)^{i + 1} h_{n + 1, i + 1} \circ s^n_i.
\end{equation}
Let us compute $d_{n + 1} \circ s(h)_n + s(h)_{n - 1} \circ d_n$.
We first compute
\begin{eqnarray*}
d_{n + 1} \circ s(h)_n & = &
\sum\nolimits_{j = 0}^{n + 1}
\sum\nolimits_{i = 0}^n
(-1)^{j + i + 1}
d^{n + 1}_j \circ h_{n + 1, i + 1} \circ s^n_i \\
& = &
\sum\nolimits_{1 \leq i + 1 \leq j \leq n + 1}
(-1)^{j + i + 1}
h_{n, i + 1} \circ d^{n + 1}_j \circ s^n_i \\
& &
+
\sum\nolimits_{n \geq i \geq j \geq 0}
(-1)^{i + j + 1}
h_{n, i} \circ d^{n + 1}_j \circ s^n_i \\
& = &
\sum\nolimits_{1 \leq i + 1 < j \leq n + 1}
(-1)^{j + i + 1}
h_{n, i + 1} \circ s^{n - 1}_i \circ d^n_{j - 1} \\
& &
+
\sum\nolimits_{1 \leq i + 1 = j \leq n + 1}
(-1)^{j + i + 1}
h_{n, i + 1} \\
& &
+
\sum\nolimits_{n \geq i = j \geq 0}
(-1)^{i + j + 1}
h_{n, i} \\
& &
+
\sum\nolimits_{n \geq i > j \geq 0}
(-1)^{i + j + 1}
h_{n, i} \circ s^{n - 1}_{i - 1} \circ d^n_j
\end{eqnarray*}
We leave it to the reader to see that the first and the last
of the four sums cancel exactly against all the terms of
$$
s(h)_{n - 1} \circ d_n
=
\sum_{i = 0}^{n - 1} \sum_{j = 0}^n
(-1)^{i + 1 + j} h_{n, i + 1} \circ s^{n - 1}_i \circ d^n_j.
$$
Hence we obtain
\begin{eqnarray*}
d_{n + 1} \circ s(h)_n + s(h)_{n - 1} \circ d_n
& = &
\sum_{j = 1}^{n + 1} (-1)^{2j} h_{n, j}
+
\sum_{i = 0}^n (-1)^{2i + 1} h_{n, i} \\
& = &
h_{n, n + 1} - h_{n , 0} \\
& = &
a_n - b_n
\end{eqnarray*}
as desired.

\begin{lemma}[Homotopy s N]
\label{simplicial-lemma-homotopy-s-N}
\source{stacks:019S}
\href{https://stacks.math.columbia.edu/tag/019S}{\texttt{Stacks tag 019S}}
\group{simplicial}

Let $\mathcal{A}$ be an additive category. Let $a, b : U \to V$ be morphisms
of simplicial objects of $\mathcal{A}$. If $a$, $b$ are homotopic,
then $s(a), s(b) : s(U) \to s(V)$ are homotopic maps of chain complexes.
If $\mathcal{A}$ is abelian, then also $N(a), N(b) : N(U) \to N(V)$ are
homotopic maps of chain complexes.
\end{lemma}

\begin{proof}
\uses{simplicial-lemma-decompose-associated-complexes}

We may choose a sequence $a = a_0, a_1, \ldots, a_n = b$ of morphisms from
$U$ to $V$ such that for each $i = 1, \ldots, n$ either there is a
homotopy from $a_i$ to $a_{i - 1}$ or there is a
homotopy from $a_{i - 1}$ to $a_i$. The calculation above
shows that in this case either
$s(a_i)$ is homotopic to $s(a_{i - 1})$ as a map of chain complexes
or $s(a_{i - 1})$ is homotopic to $s(a_i)$ as a map of chain complexes.
Of course, these things are equivalent and moreover being homotopic
is an equivalence relation on the set of maps of chain complexes, see
Homology, Section \ref{homology-section-complexes}.
This proves that $s(a)$ and $s(b)$ are homotopic as maps
of chain complexes.

\medskip\noindent
Next, we turn to $N(a)$ and $N(b)$. It follows from
Lemma \ref{simplicial-lemma-decompose-associated-complexes} that
$N(a)$, $N(b)$ are compositions
$$
N(U) \to s(U) \to s(V) \to N(V)
$$
where we use $s(a)$, $s(b)$ in the middle. Hence the assertion
follows from
Homology, Lemma \ref{homology-lemma-compose-homotopy}.
\end{proof}

