\end{lemma}

\begin{proof}
\uses{simplicial-lemma-homotopy-s-N}

Omitted. See Lemma \ref{simplicial-lemma-homotopy-s-N} above.
\end{proof}

\section{Homotopies and cosimplicial objects}
\label{simplicial-section-homotopy-cosimplicial}
Let $\mathcal{C}$ be a category with finite products. Let $V$ be a
cosimplicial object and consider $\Hom(\Delta[1], V)$, see
Section \ref{simplicial-section-hom-from-simplicial-sets-into-cosimplicial}.
The morphisms $e_0, e_1 : \Delta[0] \to \Delta[1]$
produce two morphisms $e_0, e_1 : \Hom(\Delta[1], V) \to V$.

\begin{definition}[Homotopy cosimplicial]
\label{simplicial-definition-homotopy-cosimplicial}
\source{stacks:019W}
\href{https://stacks.math.columbia.edu/tag/019W}{\texttt{Stacks tag 019W}}
\group{simplicial}

Let $\mathcal{C}$ be a category having finite products.
Let $U$ and $V$ be two cosimplicial objects of $\mathcal{C}$.
Let $a, b : U \to V$ be two morphisms of cosimplicial objects
of $\mathcal{C}$.
\begin{enumerate}
\item We say a morphism
$$
h : U \longrightarrow \Hom(\Delta[1], V)
$$
such that $a = e_0 \circ h$ and $b = e_1 \circ h$ is a
{\it homotopy from $a$ to $b$}.
\item We say $a$ and $b$ are {\it homotopic} or are
{\it in the same homotopy class} if there exists a sequence
$a = a_0, a_1, \ldots, a_n = b$ of morphisms from $U$ to $V$
such that for each $i = 1, \ldots, n$ there either exists a
homotopy from $a_i$ to $a_{i - 1}$ or there exists a homotopy
from $a_{i - 1}$ to $a_i$.
\end{enumerate}
\end{definition}

This is dual to the notion we introduced for simplicial objects in
Section \ref{simplicial-section-homotopy}. To explain this, consider a
homotopy $h : U \to \Hom(\Delta[1], V)$ from $a$ to $b$ as
in the definition. Recall that $\Delta[1]_n$ is a finite
set. The degree $n$ component of $h$ is a morphism
$$
h_n = (h_{n, \alpha}) :
U
\longrightarrow
\Hom(\Delta[1], V)_n =
\prod\nolimits_{\alpha \in \Delta[1]_n} V_n
$$
The morphisms $h_{n, \alpha} : U_n \to V_n$ of $\mathcal{C}$ have the
property that for every morphism $f : [n] \to [m]$
of $\Delta$ we have
\begin{equation}
\label{equation-property-homotopy-cosimplicial}
h_{m, \alpha} \circ U(f) = V(f) \circ h_{n, \alpha \circ f}
\end{equation}
Moreover, the condition that $a = e_0 \circ h$ means that
$a_n = h_{n, 0 : [n] \to [1]}$ where $0 : [n] \to [1]$ is the
constant map with value $0$. Similarly, the condition that
$b = e_1 \circ h$ means that $b_n = h_{n, 1 : [n] \to [1]}$
where $1 : [n] \to [1]$ is the constant map with value $1$.
Conversely, given a family of morphisms $\{h_{n, \alpha}\}$
such that (\ref{equation-property-homotopy-cosimplicial})
holds for all morphisms $f$ of $\Delta$ and such that
$a_n = h_{n, 0 : [n] \to [1]}$ and $b_n = h_{n, 1 : [n] \to [1]}$
for all $n \geq 0$, then we obtain a homotopy $h$ from $a$ to $b$ by setting
$h = \prod_{\alpha \in \Delta[1]_n} h_{n, \alpha}$.

\begin{remark}[Homotopy cosimplicial better]
\label{simplicial-remark-homotopy-cosimplicial-better}
\source{stacks:0FKJ}
\href{https://stacks.math.columbia.edu/tag/0FKJ}{\texttt{Stacks tag 0FKJ}}
\group{simplicial}

\uses{simplicial-definition-homotopy-cosimplicial}
Let $\mathcal{C}$ be any category (no assumptions whatsoever). Let
$U$ and $V$ be cosimplicial objects of $\mathcal{C}$. Let $a, b : U \to V$
be morphisms of cosimplicial objects of $\mathcal{C}$. A
{\it homotopy from $a$ to $b$} is given by morphisms
$h_{n, \alpha} : U_n \to V_n$, for $n \geq 0$, $\alpha \in \Delta[1]_n$
satisfying (\ref{equation-property-homotopy-cosimplicial})
for all morphisms $f$ of $\Delta$ and such that
$a_n = h_{n, 0 : [n] \to [1]}$ and $b_n = h_{n, 1 : [n] \to [1]}$
for all $n \geq 0$.
As in Definition \ref{simplicial-definition-homotopy-cosimplicial}
we say the morphisms $a$ and $b$
are {\it homotopic} if there exists a sequence of morphisms
$a = a_0, a_1, \ldots, a_n = b$ from $U$ to $V$ such that for each
$i = 1, \ldots, n$ there either exists a homotopy from $a_{i - 1}$ to $a_i$
or there exists a homotopy from $a_i$ to $a_{i - 1}$.
Clearly, if $F : \mathcal{C} \to \mathcal{C}'$ is any functor
and $\{h_{n, i}\}$ is a homotopy from $a$ to $b$, then
$\{F(h_{n, i})\}$ is a homotopy from $F(a)$ to $F(b)$.
Similarly, if $a$ and $b$ are homotopic, then $F(a)$ and $F(b)$
are homotopic. This new notion is the same
as the old one in case finite products exist. We deduce
in particular that functors preserve the original notion
whenever both categories have finite products.
\end{remark}

\begin{lemma}[Compare homotopies]
\label{simplicial-lemma-compare-homotopies}
\source{stacks:019X}
\href{https://stacks.math.columbia.edu/tag/019X}{\texttt{Stacks tag 019X}}
\group{simplicial}

\uses{simplicial-remark-homotopy-cosimplicial-better, simplicial-remark-homotopy-better}
Let $\mathcal{C}$ be a category. Suppose that $U$ and $V$ are two
cosimplicial objects of $\mathcal{C}$. Let $a, b : U \to V$ be morphisms
of cosimplicial objects. Recall that $U$, $V$ correspond
to simplicial objects $U'$, $V'$ of $\mathcal{C}^{opp}$.
Moreover $a, b$ correspond to morphisms $a', b' : V' \to U'$.
The following are equivalent
\begin{enumerate}
\item There exists a homotopy $h = \{h_{n, \alpha}\}$ from
$a$ to $b$ as in Remark \ref{simplicial-remark-homotopy-cosimplicial-better}.
\item There exists a homotopy $h = \{h_{n, i}\}$ from $a'$ to $b'$
as in Remark \ref{simplicial-remark-homotopy-better}.
\end{enumerate}
Thus $a$ is homotopic to $b$ as in
Remark \ref{simplicial-remark-homotopy-cosimplicial-better}
if and only if $a'$ is homotopic to $b'$ as in
Remark \ref{simplicial-remark-homotopy-better}.
\end{lemma}

\begin{proof}
\uses{simplicial-definition-homotopy-cosimplicial, simplicial-definition-homotopy, simplicial-remark-homotopy-cosimplicial-better, simplicial-remark-homotopy-better, simplicial-lemma-relations-homotopy}

In case $\mathcal{C}$ has finite products, then $\mathcal{C}^{opp}$
has finite coproducts and we may use
Definitions \ref{simplicial-definition-homotopy-cosimplicial}
and \ref{simplicial-definition-homotopy} instead of
Remarks \ref{simplicial-remark-homotopy-cosimplicial-better} and
\ref{simplicial-remark-homotopy-better}.
In this case $h : U \to \Hom(\Delta[1], V)$
is the same as a morphism $h' : \Hom(\Delta[1], V)' \to U'$.
Since products and coproducts get switched too, it is immediate
that $(\Hom(\Delta[1], V))' = V' \times \Delta[1]$.
Moreover, the ``primed'' version of the morphisms
$e_0, e_1 : \Hom(\Delta[1], V) \to V$ are the morphisms
$e_0, e_1 : V' \to \Delta[1] \times V$.
Thus $e_0 \circ h = a$ translates into $h' \circ e_0 = a'$ and
similarly $e_1 \circ h = b$ translates into $h' \circ e_1 = b'$.
This proves the lemma in this case.

\medskip\noindent
In the general case, one needs to translate the relations given
by (\ref{equation-property-homotopy-cosimplicial}) into the relations
given in Lemma \ref{simplicial-lemma-relations-homotopy}. We omit the details.

\medskip\noindent
The final assertion is formal from the equivalence of (1) and (2).
\end{proof}

\begin{lemma}[Functors preserve homotopic morphisms of (co)simplicial objects.]
\label{simplicial-lemma-functorial-homotopy}
\source{stacks:019Y}
\href{https://stacks.math.columbia.edu/tag/019Y}{\texttt{Stacks tag 019Y}}
\group{simplicial}


\uses{simplicial-remark-homotopy-cosimplicial-better, simplicial-remark-homotopy-better}
Let $\mathcal{C}, \mathcal{C}', \mathcal{D}, \mathcal{D}'$ be categories.
With terminology as in Remarks \ref{simplicial-remark-homotopy-cosimplicial-better} and
\ref{simplicial-remark-homotopy-better}.
\begin{enumerate}
\item Let $a, b : U \to V$ be morphisms of simplicial objects
of $\mathcal{D}$. Let $F : \mathcal{D} \to \mathcal{D}'$ be a covariant
functor. If $a$ and $b$ are homotopic, then $F(a)$, $F(b)$
are homotopic morphisms $F(U) \to F(V)$ of simplicial objects.
\item Let $a, b : U \to V$ be morphisms of cosimplicial objects
of $\mathcal{C}$. Let $F : \mathcal{C} \to \mathcal{C}'$ be a covariant
functor. If $a$ and $b$ are homotopic, then $F(a)$, $F(b)$
are homotopic morphisms $F(U) \to F(V)$ of cosimplicial objects.
\item Let $a, b : U \to V$ be morphisms of simplicial objects of $\mathcal{D}$.
Let $F : \mathcal{D} \to \mathcal{C}$ be a contravariant
functor. If $a$ and $b$ are homotopic, then $F(a)$, $F(b)$
are homotopic morphisms $F(V) \to F(U)$ of cosimplicial objects.
\item Let $a, b : U \to V$ be morphisms of cosimplicial objects of
$\mathcal{C}$.
Let $F : \mathcal{C} \to \mathcal{D}$ be a contravariant
functor. If $a$ and $b$ are homotopic, then $F(a)$, $F(b)$
are homotopic morphisms $F(V) \to F(U)$ of simplicial objects.
\end{enumerate}
\end{lemma}

\begin{proof}
\uses{simplicial-lemma-compare-homotopies, simplicial-remark-homotopy-better}

By Lemma \ref{simplicial-lemma-compare-homotopies} above, we can
turn $F$ into a covariant functor between a pair of
categories, and we have to show that the functor preserves homotopic pairs
of maps. This is explained in Remark \ref{simplicial-remark-homotopy-better}.
\end{proof}

\begin{lemma}[Push outs simplicial object w section]
\label{simplicial-lemma-push-outs-simplicial-object-w-section}
\source{stacks:019Z}
\href{https://stacks.math.columbia.edu/tag/019Z}{\texttt{Stacks tag 019Z}}
