\begin{lemma}[The (cosimplicial) Dold-Kan functor carries homotopic maps to homotopic maps.]
\label{simplicial-lemma-homotopy-s-Q}
\source{stacks:01A0}
\href{https://stacks.math.columbia.edu/tag/01A0}{\texttt{Stacks tag 01A0}}
\group{simplicial}


Let $\mathcal{A}$ be an additive category. Let $a, b : U \to V$ be morphisms
of cosimplicial objects of $\mathcal{A}$. If $a$, $b$ are homotopic,
then $s(a), s(b) : s(U) \to s(V)$ are homotopic maps of cochain complexes.
If in addition $\mathcal{A}$ is abelian, then $Q(a), Q(b) : Q(U) \to Q(V)$
are homotopic maps of cochain complexes.
\end{lemma}

\begin{proof}
\uses{simplicial-lemma-push-outs-simplicial-object-w-section, simplicial-lemma-homotopy-s-N}

Let $(-)' : \mathcal{A} \to \mathcal{A}^{opp}$
be the contravariant functor $A \mapsto A$. By
Lemma \ref{simplicial-lemma-push-outs-simplicial-object-w-section}
the maps $a'$ and $b'$ are homotopic.
By Lemma \ref{simplicial-lemma-homotopy-s-N} we see that
$s(a')$ and $s(b')$ are homotopic maps of chain
complexes. Since $s(a') = (s(a))'$ and
$s(b') = (s(b))'$ we conclude that also
$s(a)$ and $s(b)$ are homotopic by applying the additive
contravariant functor $(-)'' : \mathcal{A}^{opp} \to \mathcal{A}$.
The result for the $Q$-complexes follows in the same manner
using that $Q(U)' = N(U')$.
\end{proof}

\begin{lemma}[Homotopy equivalence s Q]
\label{simplicial-lemma-homotopy-equivalence-s-Q}
\source{stacks:0FKK}
\href{https://stacks.math.columbia.edu/tag/0FKK}{\texttt{Stacks tag 0FKK}}
