\begin{lemma}[Simplicial group kan]
\label{simplicial-lemma-simplicial-group-kan}
\source{stacks:08NZ}
\href{https://stacks.math.columbia.edu/tag/08NZ}{\texttt{Stacks tag 08NZ}}
\group{simplicial}

Let $X$ be a simplicial group. Then $X$ is a Kan complex.
\end{lemma}

\begin{proof}
The following proof is basically just a translation into English
of the proof in the reference mentioned above.
Using the terminology as explained in the introduction to this section,
suppose $f : \Lambda_k[n] \to X$ is a morphism from a horn. Set
$x_i = f(\sigma_i) \in X_{n - 1}$ for $i = 0, \ldots, \hat k, \ldots, n$.
This means that for $i < j$ we have $d_i x_j = d_{j - 1} x_i$
whenever $i, j \not = k$.
We have to find an $x \in X_n$ such that $x_i = d_ix$ for
$i = 0, \ldots, \hat k, \ldots, n$.

\medskip\noindent
We first prove there exists a $u \in X_n$ such that $d_i u = x_i$
for $i < k$. This is trivial for $k = 0$. If $k > 0$, one defines by
induction an element $u^r \in X_n$ such that $d_i u^r = x_i$ for
$0 \leq i \leq r$. Start with $u^0 = s_0x_0$. If $r < k - 1$,
we set
$$
y^r = s_{r + 1}((d_{r + 1}u^r)^{-1}x_{r + 1}),\quad
u^{r + 1} = u^r y^r.
$$
An easy calculation shows that $d_iy^r = 1$ (unit element of the group
$X_{n - 1}$) for $i \leq r$ and
$d_{r + 1}y^r = (d_{r + 1}u^r)^{-1}x_{r + 1}$. It follows that
$d_iu^{r + 1} = x_i$ for $i \leq r + 1$. Finally, take $u = u^{k - 1}$
to get $u$ as promised.

\medskip\noindent
Next we prove, by induction on the integer $r$, $0 \leq r \leq n - k$,
there exists a $x^r \in X_n$ such that
$$
d_i x^r = x_i\quad\text{for }i < k\text{ and }i > n - r.
$$
Start with $x^0 = u$ for $r = 0$. Having defined $x^r$ for $r \leq n - k - 1$
we set
$$
z^r = s_{n - r - 1}((d_{n - r}x^r)^{-1}x_{n - r}),\quad x^{r + 1} = x^rz^r
$$
A simple calculation, using the given relations, shows that
$d_iz^r = 1$ for $i < k$ and $i > n - r$ and that
$d_{n - r}(z^r) = (d_{n - r}x^r)^{-1}x_{n - r}$. It follows that
$d_ix^{r + 1} = x_i$ for $i < k$ and $i > n - r - 1$. Finally, we
take $x = x^{n - k}$ which finishes the proof.
\end{proof}

\begin{lemma}[Surjection simplicial abelian groups kan]
\label{simplicial-lemma-surjection-simplicial-abelian-groups-kan}
\source{stacks:08P0}
\href{https://stacks.math.columbia.edu/tag/08P0}{\texttt{Stacks tag 08P0}}
\group{simplicial}

Let $f : X \to Y$ be a homomorphism of simplicial abelian groups
which is termwise surjective. Then $f$ is a Kan fibration of
simplicial sets.
\end{lemma}

\begin{proof}
\uses{simplicial-definition-kan, simplicial-lemma-simplicial-group-kan}

Consider a commutative solid diagram
$$
\begin{array}{cc}\Lambda_k[n] \underset{a}{\longrightarrow}\downarrow & X \downarrow \\ \Delta[n] \overset{b}{\longrightarrow}\nearrow & Y\end{array}
$$
as in Definition \ref{simplicial-definition-kan}. The map $a$ corresponds
to $x_0, \ldots, \hat x_k, \ldots, x_n \in X_{n - 1}$ satisfying
$d_i x_j = d_{j - 1} x_i$ for $i < j$, $i, j \not = k$.
The map $b$ corresponds to an element $y \in Y_n$ such
that $d_iy = f(x_i)$ for $i \not = k$. Our task is to produce an
$x \in X_n$ such that $d_ix = x_i$ for $i \not = k$ and $f(x) = y$.

\medskip\noindent
Since $f$ is termwise surjective we can find $x \in X_n$ with $f(x) = y$.
Replace $y$ by $0 = y - f(x)$ and $x_i$ by $x_i - d_ix$ for $i \not = k$.
Then we see that we may assume $y = 0$. In particular $f(x_i) = 0$.
In other words, we can replace $X$ by $\Ker(f) \subset X$
and $Y$ by $0$. In this case the statement become
Lemma \ref{simplicial-lemma-simplicial-group-kan}.
\end{proof}

\begin{lemma}[Qis simplicial abelian groups]
\label{simplicial-lemma-qis-simplicial-abelian-groups}
\source{stacks:08P1}
\href{https://stacks.math.columbia.edu/tag/08P1}{\texttt{Stacks tag 08P1}}
\group{simplicial}

Let $f : X \to Y$ be a homomorphism of simplicial abelian groups
which is termwise surjective and induces a quasi-isomorphism on
associated chain complexes. Then $f$ is a trivial Kan fibration of
simplicial sets.
\end{lemma}

\begin{proof}
\uses{simplicial-definition-trivial-kan, simplicial-lemma-simplicial-group-kan, simplicial-lemma-quasi-isomorphism}

Consider a commutative solid diagram
$$
\begin{array}{cc}\partial \Delta[n] \underset{a}{\longrightarrow}\downarrow & X \downarrow \\ \Delta[n] \overset{b}{\longrightarrow}\nearrow & Y\end{array}
$$
as in Definition \ref{simplicial-definition-trivial-kan}. The map $a$ corresponds
to $x_0, \ldots, x_n \in X_{n - 1}$ satisfying $d_i x_j = d_{j - 1} x_i$
for $i < j$. The map $b$ corresponds to an element $y \in Y_n$ such
that $d_iy = f(x_i)$. Our task is to produce an $x \in X_n$ such that
$d_ix = x_i$ and $f(x) = y$.

\medskip\noindent
Since $f$ is termwise surjective we can find $x \in X_n$ with $f(x) = y$.
Replace $y$ by $0 = y - f(x)$ and $x_i$ by $x_i - d_ix$. Then we
see that we may assume $y = 0$. In particular $f(x_i) = 0$.
In other words, we can replace $X$ by $\Ker(f) \subset X$
and $Y$ by $0$. This works, because by
Homology, Lemma \ref{homology-lemma-long-exact-sequence-chain}
the homology of the chain complex associated to $\Ker(f)$
is zero and hence $\Ker(f) \to 0$ induces a quasi-isomorphism
on associated chain complexes.

\medskip\noindent
Since $X$ is a Kan complex (Lemma \ref{simplicial-lemma-simplicial-group-kan})
we can find $x \in X_n$ with $d_i x = x_i$ for $i = 0, \ldots, n - 1$.
After replacing $x_i$ by $x_i - d_ix$ for $i = 0, \ldots, n$ we
may assume that $x_0 = x_1 = \ldots = x_{n - 1} = 0$.
In this case we see that $d_i x_n = 0$ for $i = 0, \ldots, n - 1$.
Thus $x_n \in N(X)_{n - 1}$ and lies in the kernel of the differential
$N(X)_{n - 1} \to N(X)_{n - 2}$. Here $N(X)$ is the normalized chain
complex associated to $X$, see Section \ref{simplicial-section-complexes}.
Since $N(X)$ is quasi-isomorphic to $s(X)$
(Lemma \ref{simplicial-lemma-quasi-isomorphism})
and thus acyclic we find $x \in N(X_n)$ whose differential is $x_n$.
This $x$ answers the question posed by the lemma and we are done.
\end{proof}

\begin{lemma}[Homotopy equivalence]
\label{simplicial-lemma-homotopy-equivalence}
\source{stacks:08P2}
\href{https://stacks.math.columbia.edu/tag/08P2}{\texttt{Stacks tag 08P2}}
\group{simplicial}

Let $f : X \to Y$ be a map of simplicial abelian groups. If $f$ is a
homotopy equivalence of simplicial sets, then $f$ induces a
quasi-isomorphism of associated chain complexes.
\end{lemma}

\begin{proof}
\uses{simplicial-lemma-functorial-homotopy, simplicial-lemma-homotopy-equivalence-s-N}

In this proof we will write $H_n(Z) = H_n(s(Z)) = H_n(N(Z))$
when $Z$ is a simplicial abelian group, with $s$ and $N$ as in
Section \ref{simplicial-section-complexes}.
Let $\mathbf{Z}[X]$ denote the free abelian group on $X$ viewed as
a simplicial set and similarly for $\mathbf{Z}[Y]$. Consider the
commutative diagram
$$
\begin{array}{cc}\mathbf{Z}[X] \underset{g}{\longrightarrow}\downarrow & \mathbf{Z}[Y] \downarrow \\ X \overset{f}{\longrightarrow} & Y\end{array}
$$
of simplicial abelian groups. Since taking the free abelian group on a set
is a functor, we see that the horizontal arrow is a homotopy equivalence of
simplicial abelian groups, see Lemma \ref{simplicial-lemma-functorial-homotopy}.
By Lemma \ref{simplicial-lemma-homotopy-equivalence-s-N}
we see that $H_n(g) : H_n(\mathbf{Z}[X]) \to H_n(\mathbf{Z}[Y])$ is bijective
for all $n \geq 0$.

\medskip\noindent
Let $\xi \in H_n(Y)$. By definition of $N(Y)$ we can represent
$\xi$ by an element $y \in N(Y_n)$ whose boundary is zero.
This means $y \in Y_n$ with $d^n_0(y) = \ldots = d^n_{n - 1}(y) = 0$
because $y \in N(Y_n)$ and $d^n_n(y) = 0$ because the boundary
of $y$ is zero. Denote $0_n \in Y_n$ the zero element. Then we see that
$$
\tilde y = [y] - [0_n] \in (\mathbf{Z}[Y])_n
$$
is an element with $d^n_0(\tilde y) = \ldots = d^n_{n - 1}(\tilde y) = 0$
and $d^n_n(\tilde y) = 0$. Thus $\tilde y$ is in $N(\mathbf{Z}[Y])_n$
has boundary $0$, i.e., $\tilde y$ determines a
class $\tilde \xi \in H_n(\mathbf{Z}[Y])$ mapping to $\xi$.
Because $H_n(\mathbf{Z}[X]) \to H_n(\mathbf{Z}[Y])$ is bijective
we can lift $\tilde \xi$ to a class in $H_n(\mathbf{Z}[X])$.
Looking at the commutative diagram above
we see that $\xi$ is in the image of $H_n(X) \to H_n(Y)$.

\medskip\noindent
Let $\xi \in H_n(X)$ be an element mapping to zero in $H_n(Y)$.
Exactly as in the previous parapgraph we can represent
$\xi$ by an element $x \in N(X_n)$ whose boundary is zero, i.e.,
$d^n_0(x) = \ldots = d^n_{n - 1}(x) = d^n_n(x) = 0$.
In particular, we see that $[x] - [0_n]$ is an element of
$N(\mathbf{Z}[X])_n$ whose boundary is zero, whence defines
a lift $\tilde \xi \in H_n(\mathbf{Z}[x])$ of $\xi$.
The fact that $\xi$ maps to zero in $H_n(Y)$
means there exists a $y \in N(Y_{n + 1})$ whose boundary is $f_n(x)$.
This means $d^{n + 1}_0(y) = \ldots = d^{n + 1}_n(y) = 0$ and
$d^{n + 1}_{n + 1}(y) = f(x)$.
However, this means exactly that
$z = [y] - [0_{n + 1}]$ is in $N(\mathbf{Z}[y])_{n + 1}$ and
$$
g([x] - [0_n]) = [f(x)] - [0_n] = \text{boundary of }z
$$
This proves that $\tilde \xi$ maps to zero in $H_n(\mathbf{Z}[y])$.
As $H_n(\mathbf{Z}[X]) \to H_n(\mathbf{Z}[Y])$ is bijective
we conclude $\tilde \xi = 0$ and hence $\xi = 0$.
\end{proof}

\section{A homotopy equivalence}
\label{simplicial-section-homotopy-equivalence}
Suppose that $A$, $B$ are sets, and that $f : A \to B$
is a map. Consider the associated map of
simplicial sets
$$
\begin{array}{cccc}\text{cosk}_0(A) \xlongequal{} & \Big(\ldots A \times A \times A
\downarrow\longrightarrow\longrightarrow\longrightarrow & A \times A \downarrow\longrightarrow\longrightarrow\longleftarrow\longleftarrow & A \Big) \downarrow\longleftarrow \\ \text{cosk}_0(B) \xlongequal{} & \Big( \ldots B \times B \times B \longrightarrow\longrightarrow\longrightarrow & B \times B \longrightarrow\longrightarrow\longleftarrow\longleftarrow & B \Big) \longleftarrow\end{array}
$$
See Example \ref{simplicial-example-cosk0}. The case $n = 0$ of the following lemma
says that this map of simplicial sets is a trivial Kan fibration if $f$ is
surjective.

\begin{lemma}[Section]
\label{simplicial-lemma-section}
\source{stacks:01A6}
\href{https://stacks.math.columbia.edu/tag/01A6}{\texttt{Stacks tag 01A6}}
\group{simplicial}

Let $f : V \to U$ be a morphism of simplicial sets. Let $n \geq 0$ be an
integer. Assume
\begin{enumerate}
\item The map $f_i : V_i \to U_i$ is a bijection for $i < n$.
\item The map $f_n : V_n \to U_n$ is a surjection.
\item The canonical morphism $U \to \text{cosk}_n \text{sk}_n U$
is an isomorphism.
\item The canonical morphism $V \to \text{cosk}_n \text{sk}_n V$
is an isomorphism.
\end{enumerate}
Then $f$ is a trivial Kan fibration.
\end{lemma}

\begin{proof}
\uses{simplicial-definition-trivial-kan}

Consider a solid diagram
$$
\begin{array}{cc}\partial \Delta[k] \longrightarrow\downarrow & V \downarrow \\ \Delta[k] \longrightarrow\nearrow & U\end{array}
$$
as in Definition \ref{simplicial-definition-trivial-kan}. Let $x \in U_k$ be
the $k$-simplex corresponding to the lower horizontal arrow.
If $k \leq n$ then the dotted arrow is the one corresponding to
a lift $y \in V_k$ of $x$; the diagram will commute as the other
nondegenerate simplices of $\Delta[k]$ are in degrees $< k$ where
$f$ is an isomorphism. If $k > n$, then by conditions (3) and (4)
we have (using adjointness of skeleton and coskeleton functors)
$$
\Mor(\Delta[k], U) =
\Mor(\text{sk}_n\Delta[k], \text{sk}_nU) =
\Mor(\text{sk}_n\partial\Delta[k], \text{sk}_nU) =
\Mor(\partial \Delta[k], U)
$$
and similarly for $V$ because
$\text{sk}_n\Delta[k] = \text{sk}_n\partial\Delta[k]$ for $k > n$.
Thus we obtain a unique dotted arrow fitting into the diagram in
this case also.
\end{proof}

Let $A, B$ be sets. Let $f^0, f^1 : A \to B$ be maps of sets.
Consider the induced maps $f^0, f^1 : \text{cosk}_0(A) \to \text{cosk}_0(B)$
abusively denoted by the same symbols. The following lemma for $n = 0$
says that $f^0$ is homotopic to $f^1$. In fact, there is a
homotopy $h : \text{cosk}_0(A) \times \Delta[1] \to \text{cosk}_0(A)$
from $f^0$ to $f^1$ with components
\begin{eqnarray*}
h_m : A \times \ldots \times A \times \Mor_{\Delta}([m], [1])
& \longrightarrow &
B \times \ldots \times B, \\
(a_0, \ldots, a_m, \alpha) & \longmapsto &
(f^{\alpha(0)}(a_0), \ldots, f^{\alpha(m)}(a_m))
\end{eqnarray*}
To check that this works, note that for a map $\varphi : [k] \to [m]$
the induced maps are
$(a_0, \ldots, a_m) \mapsto (a_{\varphi(0)}, \ldots, a_{\varphi(k)})$
and $\alpha \mapsto \alpha \circ \varphi$. Thus $h = (h_m)_{m \geq 0}$
is clearly a map of simplicial sets as desired.

\begin{lemma}[Homotopy]
\label{simplicial-lemma-homotopy}
\source{stacks:01A9}
\href{https://stacks.math.columbia.edu/tag/01A9}{\texttt{Stacks tag 01A9}}
\group{simplicial}

Let $f^0, f^1 : V \to U$ be maps of simplicial sets.
Let $n \geq 0$ be an integer.
Assume
\begin{enumerate}
\item The maps $f^j_i : V_i \to U_i$, $j = 0, 1$ are equal for $i < n$.
\item The canonical morphism $U \to \text{cosk}_n \text{sk}_n U$
is an isomorphism.
\item The canonical morphism $V \to \text{cosk}_n \text{sk}_n V$
is an isomorphism.
\end{enumerate}
Then $f^0$ is homotopic to $f^1$.
\end{lemma}

\begin{proof}
\uses{simplicial-lemma-section, simplicial-lemma-trivial-kan}
[First proof]
Let $W$ be the $n$-truncated simplicial set with $W_i = U_i$ for
$i < n$ and $W_n = U_n / \sim$ where $\sim$ is the equivalence relation
generated by $f^0(y) \sim f^1(y)$ for $y \in V_n$. This makes sense
as the morphisms $U(\varphi) : U_n \to U_i$ corresponding to
$\varphi : [i] \to [n]$ for $i < n$ factor through the quotient map
$U_n \to W_n$ because $f^0$ and $f^1$ are morphisms of simplicial sets and
equal in degrees $< n$. Next, we upgrade $W$ to a simplicial set
by taking $\text{cosk}_n W$. By Lemma \ref{simplicial-lemma-section}
the morphism $g : U \to W$ is a trivial Kan fibration. Observe
that $g \circ f^0 = g \circ f^1$ by construction and denote
this morphism $f : V \to W$. Consider the diagram
$$
\begin{array}{ccc}\partial \Delta[1] \times V \underset{f^0, f^1}{\longrightarrow}\downarrow &  & U \downarrow \\ \Delta[1] \times V \overset{f}{\longrightarrow}\nearrow &  & W\end{array}
$$
By Lemma \ref{simplicial-lemma-trivial-kan} the dotted arrow exists and the proof is done.
\end{proof}

\begin{proof}
\uses{simplicial-lemma-simplex-cosk, simplicial-lemma-cosk-up, simplicial-lemma-cosk-product}
[Second proof]
We have to construct a morphism of simplicial sets
$h : V \times \Delta[1] \to U$ which recovers $f^i$ on composing with $e_i$.
The case $n = 0$ was dealt with above the lemma.
Thus we may assume that $n \geq 1$.
The map $\Delta[1] \to \text{cosk}_1 \text{sk}_1 \Delta[1]$
is an isomorphism, see Lemma \ref{simplicial-lemma-simplex-cosk}.
Thus we see that $\Delta[1] \to \text{cosk}_n \text{sk}_n \Delta[1]$
is an isomorphism as $n \geq 1$, see
Lemma \ref{simplicial-lemma-cosk-up}. And hence $V \times \Delta[1] \to
\text{cosk}_n \text{sk}_n (V \times \Delta[1])$
is an isomorphism too, see Lemma \ref{simplicial-lemma-cosk-product}.
In other words, in order to construct the homotopy
it suffices to construct a suitable
morphism of $n$-truncated simplicial sets
$h : \text{sk}_n V \times \text{sk}_n \Delta[1] \to \text{sk}_n U$.

\medskip\noindent
For $k = 0, \ldots, n - 1$ we define $h_k$ by the
formula $h_k(v, \alpha) = f^0(v) = f^1(v)$.
The map $h_n : V_n \times \Mor_{\Delta}([n], [1]) \to U_n$
is defined as follows. Pick $v \in V_n$ and $\alpha : [n] \to [1]$:
\begin{enumerate}
\item If $\Im(\alpha) = \{0\}$, then we set $h_n(v, \alpha) = f^0(v)$.
\item If $\Im(\alpha) = \{0, 1\}$, then we set $h_n(v, \alpha) = f^0(v)$.
\item If $\Im(\alpha) = \{1\}$, then we set $h_n(v, \alpha) = f^1(v)$.
\end{enumerate}
Let $\varphi : [k] \to [l]$ be a morphism of $\Delta_{\leq n}$.
We will show that the diagram
$$
\begin{array}{cc}V_{l} \times \Mor([l], [1]) \longrightarrow\downarrow & U_{l} \downarrow \\ V_{k} \times \Mor([k], [1]) \longrightarrow & U_{k}\end{array}
$$
commutes.
Pick $v \in V_{l}$ and $\alpha : [l] \to [1]$.
The commutativity means that
$$
h_k(V(\varphi)(v), \alpha \circ \varphi)
=
U(\varphi)(h_l(v, \alpha)).
$$
In almost every case this holds because
$h_k(V(\varphi)(v), \alpha \circ \varphi) = f^0(V(\varphi)(v))$
and $U(\varphi)(h_l(v, \alpha)) = U(\varphi)(f^0(v))$, combined
with the fact that $f^0$ is a morphism of simplicial sets.
The only cases where this does not hold is when
either (A) $\Im(\alpha) = \{1\}$ and $l = n$
or (B) $\Im(\alpha \circ \varphi) = \{1\}$ and $k = n$.
Observe moreover that necessarily $f^0(v) = f^1(v)$
for any degenerate $n$-simplex of $V$.
Thus we can narrow the cases above down even further
to the cases (A) $\Im(\alpha) = \{1\}$, $l = n$
and $v$ nondegenerate, and (B)
$\Im(\alpha \circ \varphi) = \{1\}$, $k = n$
and $V(\varphi)(v)$ nondegenerate.

\medskip\noindent
In case (A), we see that also $\Im(\alpha \circ \varphi) = \{1\}$.
Hence we see that not only $h_l(v, \alpha) = f^1(v)$ but also
$h_k(V(\varphi)(v), \alpha \circ \varphi) = f^1(V(\varphi)(v))$.
Thus we see that the relation holds because $f^1$ is a morphism
of simplicial sets.

\medskip\noindent
In case (B) we conclude that $l = k = n$ and
$\varphi$ is bijective, since otherwise $V(\varphi)(v)$
is degenerate. Thus $\varphi = \text{id}_{[n]}$, which is a trivial case.
\end{proof}

\begin{lemma}[Cosk minus one equivalence]
\label{simplicial-lemma-cosk-minus-one-equivalence}
\source{stacks:01AB}
\href{https://stacks.math.columbia.edu/tag/01AB}{\texttt{Stacks tag 01AB}}
\group{simplicial}

\uses{simplicial-example-fibre-products-simplicial-object}
Let $A$, $B$ be sets, and that $f : A \to B$ is a map. Consider the simplicial
set $U$ with $n$-simplices
$$
A \times_B A \times_B \ldots \times_B A\ (n + 1 \text{ factors)}.
$$
see Example \ref{simplicial-example-fibre-products-simplicial-object}.
If $f$ is surjective, the morphism $U \to B$
where $B$ indicates the constant simplicial set with value $B$
is a trivial Kan fibration.
\end{lemma}

\begin{proof}
\uses{simplicial-lemma-section, simplicial-lemma-trivial-kan-base-change}

Observe that $U$ fits into a cartesian square
$$
\begin{array}{cc}U \downarrow\longrightarrow & \text{cosk}_0(A) \downarrow \\ B \longrightarrow & \text{cosk}_0(B)\end{array}
$$
Since the right vertical arrow is a trivial Kan fibration by
Lemma \ref{simplicial-lemma-section}, so is the left by
Lemma \ref{simplicial-lemma-trivial-kan-base-change}.
\end{proof}

\section{Preparation for standard resolutions}
\label{simplicial-section-standard-pre}
The material in this section can be found in \cite[Appendix 1]{Godement}

\begin{example}[Godement]
\label{simplicial-example-godement}
\source{stacks:0G5M}
\href{https://stacks.math.columbia.edu/tag/0G5M}{\texttt{Stacks tag 0G5M}}
\group{simplicial}

Let $Y : \mathcal{C} \to \mathcal{C}$ be a functor from a category to
itself and suppose given transformations of functors
$$
d : Y \longrightarrow \text{id}_\mathcal{C}
\quad\text{and}\quad
s : Y \longrightarrow Y \circ Y
$$
Using these transformations we can construct something that looks
like a simplicial object. Namely, for $n \geq 0$ we define
$$
X_n = Y \circ \ldots \circ Y \quad (n + 1\text{ compositions})
$$
Observe that $X_{n + m + 1} = X_n \circ X_m$ for $n, m \geq 0$.
Next, for $n \geq 0$ and $0 \leq j \leq n$ we define using notation
as in Categories, Section \ref{categories-section-formal-cat-cat}
$$
d^n_j = 1_{X_{j - 1}} \star d \star 1_{X_{n - j - 1}} :
X_n
\to
X_{n - 1}
\quad\text{and}\quad
s^n_j = 1_{X_{j - 1}} \star s \star 1_{X_{n - j - 1}} :
X_n
\to
X_{n + 1}
$$
So $d^n_j$, resp.\ $s^n_j$ is the natural transformation using
$d$, resp.\ $s$ on the $j$th $Y$ (counted from the left) in the
composition defining $X_n$.
\end{example}

\begin{lemma}[Godement]
\label{simplicial-lemma-godement}
\source{stacks:0G5N}
\href{https://stacks.math.columbia.edu/tag/0G5N}{\texttt{Stacks tag 0G5N}}
\group{simplicial}

\uses{simplicial-example-godement}
In Example \ref{simplicial-example-godement} if
$$
1_Y = (d \star 1_Y) \circ s = (1_Y \star d) \circ s
\quad\text{and}\quad
(s \star 1) \circ s = (1 \star s) \circ s
$$
then $X = (X_n, d^n_j, s^n_j)$ is a simplicial object in the category
of endofunctors of $\mathcal{C}$ and $d : X_0 = Y \to \text{id}_\mathcal{C}$
defines an augmentation.
\end{lemma}

\begin{proof}
\uses{simplicial-lemma-characterize-simplicial-object}

To see that we obtain a simplicial object we have to check that the
relations (1)(a) -- (e) of Lemma \ref{simplicial-lemma-characterize-simplicial-object}
are satisfied. We will use the short hand notation
$$
1_a = 1_{X_{a - 1}} = 1_Y \star \ldots \star 1_Y \quad (a\text{ factors})
$$
for $a \geq 0$. With this notation we have
$$
d^n_j = 1_j \star d \star 1_{n - j}
\quad\text{and}\quad
s^n_j = 1_j \star s \star 1_{n - j}
$$
We are repeatedly going to use the rule that for transformations
of funtors $a, a', b, b'$ we have
$(a' \circ a) \star (b' \circ b) = (a' \star b') \circ (a \star b)$
provided that the $\star$ and $\circ$ compositions in this formula
make sense, see
Categories, Lemma \ref{categories-lemma-properties-2-cat-cats}.

\medskip\noindent
Condition (1)(a) always holds (no conditions needed on $d$ and $s$).
Namely, let $0 \leq i < j \leq n + 1$. We have to show that
$d^n_i \circ d^{n + 1}_j = d^n_{j - 1} \circ d^{n + 1}_i$, i.e.,
$$
(1_i \star d \star 1_{n - i}) \circ
(1_j \star d \star 1_{n + 1 - j}) =
(1_{j - 1} \star d \star 1_{n + 1 - j}) \circ
(1_i \star d \star 1_{n + 1 - i})
$$
We can rewrite the left hand side as
\begin{align*}
& (1_i \star d \star 1_{j - i - 1} \star 1_{n + 1 - j}) \circ
(1_i \star 1_1 \star 1_{j - i - 1} \star d \star 1_{n + 1 - j}) \\
& =
1_i \star
\left((d \star 1_{j - i - 1}) \circ
(1_1 \star 1_{j - i - 1} \star d)\right) \star 1_{n + 1 - j} \\
& =
1_i \star d \star 1_{j - i - 1} \star d \star 1_{n + 1 - j}
\end{align*}
The second equality is true because $d \circ 1_1 = d$ and
$1_{j - i} \circ (1_{j - i - 1} \star d) = 1_{j - i - 1} \star d$.
A similar computation gives the same result for the right hand side.

\medskip\noindent
We check condition (1)(b). Let $0 \leq i < j \leq n - 1$. We have to show
that $d^n_i \circ s^{n - 1}_j = s^{n - 2}_{j - 1} \circ d^{n - 1}_i$, i.e.,
$$
(1_i \star d \star 1_{n - i}) \circ
(1_j \star s \star 1_{n - 1 - j}) =
(1_{j - 1} \star s \star 1_{n - 1 - j}) \circ
(1_i \star d \star 1_{n - 1 - i})
$$
By the same kind of calculus as in case (1)(a) both sides simplify
to $1_i \star d \star 1_{j - i - 1} \star s \star 1_{n - j - 1}$.

\medskip\noindent
We check condition (1)(c). Let $0 \leq j \leq n - 1$. We have to show
$\text{id} = d^n_j \circ s^{n - 1}_j = d^n_{j + 1} \circ s^{n - 1}_j$, i.e.,
$$
1_n =
(1_j \star d \star 1_{n - j}) \circ
(1_j \star s \star 1_{n - 1 - j}) =
(1_{j + 1} \star d \star 1_{n - j - 1}) \circ
(1_j \star s \star 1_{n - 1 - j})
$$
This is easily seen to be implied by the first assumption of the lemma.

\medskip\noindent
We check condition (1)(d). Let $0 < j + 1 < i \leq n$. We have to show
$d^n_i \circ s^{n - 1}_j = s^{n - 2}_j \circ d^{n - 1}_{i - 1}$, i.e.,
$$
(1_i \star d \star 1_{n - i}) \circ
(1_j \star s \star 1_{n - 1 - j}) =
(1_j \star s \star 1_{n - 2 - j}) \circ
(1_{i - 1} \star d \star 1_{n - i})
$$
By the same kind of calculus as in case (1)(a) both sides simplify
to $1_j \star s \star 1_{i - j - 2} \star d \star 1_{n - i}$.

\medskip\noindent
We check condition (1)(e). Let $0 \leq i \leq j \leq n - 1$. We
have to show that
$s^n_i \circ s^{n - 1}_j = s^n_{j + 1} \circ s^{n - 1}_i$, i.e.,
$$
(1_i \star s \star 1_{n - i}) \circ
(1_j \star s \star 1_{n - 1 - j}) =
(1_{j + 1} \star s \star 1_{n - 1 - j}) \circ
(1_i \star s \star 1_{n - 1 - i})
$$
By the same kind of calculus as in case (1)(a) this reduces to
$$
(s \star 1_{j - i + 1}) \circ (1_{j - i} \star s) =
(1_{j - i + 1} \star s) \circ (s \star 1_{j - i})
$$
If $j = i$ this is exactly one of the two assumptions of the lemma.
For $j > i$ left and
right hand side both reduce to the equality $s \star 1_{j - i - 1} \star s$
by calculations similar to those we did in case (1)(a).

\medskip\noindent
Finally, in order to show that $d$ defines an augmentation we have
to show that $d \circ (1_1 \star d) = d \circ (d \star 1_1)$ which is
true because both sides are equal to $d \star d$.
\end{proof}

\begin{example}[Godement functorial]
\label{simplicial-example-godement-functorial}
\source{stacks:0G5P}
\href{https://stacks.math.columbia.edu/tag/0G5P}{\texttt{Stacks tag 0G5P}}
\group{simplicial}

\uses{simplicial-example-godement, simplicial-lemma-godement}
Let $\mathcal{C}$, $Y$, $d$, $s$ be as in Example \ref{simplicial-example-godement}
satisfying the equations of Lemma \ref{simplicial-lemma-godement}.
Given functors $F : \mathcal{A} \to \mathcal{C}$ and
$G : \mathcal{C} \to \mathcal{B}$ we obtain a simplicial
object $G \circ X \circ F$ in the category of functors
from $\mathcal{A}$ to $\mathcal{B}$ which comes with an
augmentation to $G \circ F$.
\end{example}

\begin{lemma}[Godement section]
\label{simplicial-lemma-godement-section}
\source{stacks:0G5Q}
\href{https://stacks.math.columbia.edu/tag/0G5Q}{\texttt{Stacks tag 0G5Q}}
\group{simplicial}

\uses{simplicial-example-godement-functorial}
Let $\mathcal{A}$, $\mathcal{B}$, $\mathcal{C}$, $Y$, $d$, $s$, $F$, $G$
be as in Example \ref{simplicial-example-godement-functorial}. Given a transformation
of functors $h_0 : G \circ F \to G \circ Y \circ F$ such that
$$
1_{G \circ F} = (1_G \star d \star 1_F) \circ h_0
$$
Then there is a morphism $h : G \circ F \to G \circ X \circ F$
of simplicial objects such that $\epsilon \circ h = \text{id}$ where
$\epsilon : G \circ X \circ F \to G \circ F$ is the augmentation.
\end{lemma}

\begin{proof}
Denote $u_n : Y = X_0 \to X_n$ the map of the simplicial object $X$
corresponding to the unique morphism $[n] \to [0]$ in $\Delta$.
Set $h_n : G \circ F \to G \circ X_n \circ F$ equal to
$(1_G \star u_n \star 1_F) \circ h_0$.

\medskip\noindent
For any simplicial object $X = (X_n)$ in any category
$u =(u_n) : X_0 \to X$ is a morphism from the constant simplicial object
on $X_0$ to $X$. Hence $h$ is a
morphism of simplicial objects because it is the composition of
$1_G \star u \star 1_F$ and $h_0$.

\medskip\noindent
Let us check that $\epsilon \circ h = \text{id}$. We compute
$$
\epsilon_n \circ (1_G \star u_n \star 1_F) \circ h_0 =
\epsilon_0 \circ h_0 = \text{id}
$$
The first equality because $\epsilon$ is a morphism of simplicial objects
and the second equality because
$\epsilon_0 = (1_G \star d \star 1_F)$ and we can apply the
assumption in the statement of the lemma.
\end{proof}

\begin{lemma}[Godement two maps]
\label{simplicial-lemma-godement-two-maps}
\source{stacks:0G5R}
\href{https://stacks.math.columbia.edu/tag/0G5R}{\texttt{Stacks tag 0G5R}}
\group{simplicial}

\uses{simplicial-example-godement-functorial}
Let $\mathcal{A}$, $\mathcal{B}$, $\mathcal{C}$, $Y$, $d$, $s$, $F$, $G$
be as in Example \ref{simplicial-example-godement-functorial}. Let
$F' : \mathcal{A} \to \mathcal{C}$ and
$G' : \mathcal{C} \to \mathcal{B}$ be two functors.
Let $(a_n) : G \circ X \to G' \circ X$ be a morphism of simplicial objects
compatible via augmentations with $a : G \to G'$.
Let $(b_n) : X \circ F \to X \circ F'$ be a morphism of simplicial objects
compatible via augmentations with $b : F \to F'$. Then the two maps
$$
a \star (b_n), (a_n) \star b : G \circ X \circ F \to G' \circ X \circ F'
$$
are homotopic.
\end{lemma}

\begin{proof}
\uses{simplicial-lemma-relations-homotopy, simplicial-remark-homotopy-better, simplicial-lemma-godement}

To show the morphisms are homotopic we construct morphisms
$$
h_{n, i} : G \circ X_n \circ F \to G' \circ X_n \circ F'
$$
for $n \geq 0$ and $0 \leq i \leq n + 1$
satisfying the relations described in Lemma \ref{simplicial-lemma-relations-homotopy}.
See also Remark \ref{simplicial-remark-homotopy-better}. To satisfy condition (1)
of Lemma \ref{simplicial-lemma-relations-homotopy} we are forced to set
$h_{n, 0} = a \star b_n$ and $h_{n , n + 1} = a_n \star b$.
Thus a logical choice is
$$
h_{n , i} = a_{i - 1} \star b_{n - i}
$$
for $1 \leq i \leq n$. Setting $a = a_{-1}$ and $b = b_{-1}$ we
see the displayed formular holds for $0 \leq i \leq n + 1$.

\medskip\noindent
Recall that
$$
d^n_j = 1_G \star 1_j \star d \star 1_{n - j} \star 1_F
$$
on $G \circ X \circ F$ where we use
the notation $1_a = 1_{Y \circ \ldots \circ Y}$ introduced
in the proof of Lemma \ref{simplicial-lemma-godement}. We are going to use below
that we can rewrite this as
\begin{align*}
d^n_j
& =
d^j_j \star 1_{n - j} =
d^{j + 1}_j \star 1_{n - j} = \ldots = d^{n - 1}_j \star 1_1 \\
& =
1_j \star d^{n - j}_0 = 1_{j - 1} \star d^{n - j + 1}_1 = \ldots =
1_1 \star d^{n - 1}_{j - 1}
\end{align*}
Of course we have the analogous formulae for $d^n_j$ on $G' \circ X \circ F'$.

\medskip\noindent
We check condition (2) of Lemma \ref{simplicial-lemma-relations-homotopy}.
Let $i > j$. We have to show
$$
d^n_j \circ (a_{i - 1} \star b_{n - i}) =
(a_{i - 2} \star b_{n - i}) \circ d^n_j
$$
Since $i - 1 \geq j$ we can use one of the possible descriptions of
$d^n_j$ to rewrite the left hand side as
$$
(d^{i - 1}_j \star 1_{n - i + 1}) \circ (a_{i - 1} \star b_{n - i}) =
(d^{i - 1}_j \circ a_{i - 1}) \star b_{n - i} =
(a_{i - 2} \circ d^{i - 1}_j) \star b_{n - i}
$$
Similarly the right hand side becomes
$$
(a_{i - 2} \star b_{n - i}) \circ (d^{i - 1}_j \star 1_{n - i + 1}) =
(a_{i - 2} \circ d^{i - 1}_j) \star b_{n - i}
$$
Thus we obtain the same result and (2) is checked.

\medskip\noindent
We check condition (3) of Lemma \ref{simplicial-lemma-relations-homotopy}.
Let $i \leq j$. We have to show
$$
d^n_j \circ (a_{i - 1} \star b_{n - i}) =
(a_{i - 1} \star b_{n - 1 - i}) \circ d^n_j
$$
Since $j \geq i$ we may rewrite the left hand side as
$$
(1_i \star d^{n - i}_{j - i}) \circ (a_{i - 1} \star b_{n - i}) =
a_{i - 1} \star (b_{n - 1 - i} \circ d^{n - i}_{j - i})
$$
A similar manipulation shows this agrees with the right hand side.

\medskip\noindent
Recall that
$$
s^n_j = 1_G \star 1_j \star s \star 1_{n - j} \star 1_F
$$
on $G \circ X \circ F$. We are going to use below
that we can rewrite this as
\begin{align*}
s^n_j
& =
s^j_j \star 1_{n - j} = s^{j + 1}_j \star 1_{n - j - 1} = \ldots =
s^{n - 1}_j \star 1_1 \\
& =
1_j \star s^{n - j}_0 = 1_{j - 1} \star s^{n - j + 1}_1 = \ldots =
1_1 \star s^{n - 1}_{j - 1}
\end{align*}
Of course we have the analogous formulae for $s^n_j$ on $G' \circ X \circ F'$.

\medskip\noindent
We check condition (4) of Lemma \ref{simplicial-lemma-relations-homotopy}.
Let $i > j$. We have to show
$$
s^n_j \circ (a_{i - 1} \star b_{n - i}) =
(a_i \star b_{n - i}) \circ s^n_j
$$
Since $i - 1 \geq j$ we can rewrite the left hand side as
$$
(s^{i - 1}_j \star 1_{n - i + 1}) \circ (a_{i - 1} \star b_{n - i}) =
(s^{i - 1}_j \circ a_{i - 1}) \star b_{n - i} =
(a_i \circ s^{i - 1}_j) \star b_{n - i}
$$
Similarly the right hand side becomes
$$
(a_i \star b_{n - i}) \circ (s^{i - 1}_j \star 1_{n - i + 1}) =
(a_i \circ s^{i - 1}_j) \star b_{n - i}
$$
as desired.

\medskip\noindent
We check condition (5) of Lemma \ref{simplicial-lemma-relations-homotopy}.
Let $i \leq j$. We have to show
$$
s^n_j \circ (a_{i - 1} \star b_{n - i}) =
(a_{i - 1} \star b_{n + 1 - i}) \circ s^n_j
$$
This equality holds because both sides evaluate to
$a_{i - 1} \star (s^{n - i}_{j - i} \circ b_{n - i}) =
a_{i - 1} \star (b_{n + 1 - i} \circ s^{n - i}_{j - i})$
by exactly the same arguments as above.
\end{proof}

\begin{lemma}[Godement before after]
\label{simplicial-lemma-godement-before-after}
\source{stacks:0G5S}
\href{https://stacks.math.columbia.edu/tag/0G5S}{\texttt{Stacks tag 0G5S}}
\group{simplicial}

\uses{simplicial-example-godement, simplicial-lemma-godement}
Let $\mathcal{C}$, $Y$, $d$, $s$ be as in Example \ref{simplicial-example-godement}
satisfying the equations of Lemma \ref{simplicial-lemma-godement}. Let
$f : \text{id}_\mathcal{C} \to \text{id}_\mathcal{C}$ be an endomorphism
of the identity functor. Then $f \star 1_X, 1_X \star f : X \to X$
are maps of simplicial objects compatible with $f$ via the augmentation
$\epsilon : X \to \text{id}_\mathcal{C}$. Moreover, $f \star 1_X$
and $1_X \star f$ are homotopic.
\end{lemma}

\begin{proof}
\uses{simplicial-lemma-relations-homotopy, simplicial-remark-homotopy-better, simplicial-lemma-godement, simplicial-lemma-godement-two-maps}

The map $f \star 1_X$ is the map with components
$$
X_n = \text{id}_\mathcal{C} \circ X_n
\xrightarrow{f \star 1_{X_n}}
\text{id}_\mathcal{C} \circ X_n = X_n
$$
For a transformation $a : F \to G$ of endofunctors of $\mathcal{C}$ we have
$a \circ (f \star 1_F) = f \star a = (f \star 1_G) \circ a$. Thus $f \star 1_X$
is indeed a morphism of simplicial objects. Similarly for $1_X \star f$.

\medskip\noindent
To show the morphisms are homotopic we construct
morphisms $h_{n, i} : X_n \to X_n$ for $n \geq 0$ and $0 \leq i \leq n + 1$
satisfying the relations described in Lemma \ref{simplicial-lemma-relations-homotopy}.
See also Remark \ref{simplicial-remark-homotopy-better}. It turns out we can take
$$
h_{n, i} = 1_i \star f \star 1_{n + 1 - i}
$$
where $1_i$ is the identity transformation on $Y \circ \ldots \circ Y$
as in the proof of Lemma \ref{simplicial-lemma-godement}. We have
$h_{n, 0} = f \star 1_{X_n}$ and $h_{n, n + 1} = 1_{X_n} \star f$
which checks the first condition. In checking the other conditions
we use the comments made in the proof of
Lemma \ref{simplicial-lemma-godement-two-maps} about the maps $d^n_j$ and $s^n_j$.

\medskip\noindent
We check condition (2) of Lemma \ref{simplicial-lemma-relations-homotopy}.
Let $i > j$. We have to show
$$
d^n_j \circ (1_i \star f \star 1_{n + 1 - i}) =
(1_{i - 1} \star f \star 1_{n + 1 - i}) \circ d^n_j
$$
Since $i - 1 \geq j$ we can use one of the possible descriptions of
$d^n_j$ to rewrite the left hand side as
$$
(d^{i - 1}_j \star 1_{n - i + 1}) \circ (1_i \star f \star 1_{n + 1 - i}) =
d^{i - 1}_j \star f \star 1_{n + 1 - i}
$$
Similarly the right hand side becomes
$$
(1_{i - 1} \star f \star 1_{n + 1 - i}) \circ
(d^{i - 1}_j \star 1_{n - i + 1}) =
d^{i - 1}_j \star f \star 1_{n + 1 - i}
$$
Thus we obtain the same result and (2) is checked.

\medskip\noindent
The conditions (3), (4), and (5) of Lemma \ref{simplicial-lemma-relations-homotopy}
are checked in exactly the same manner using the strategy of the proof
of Lemma \ref{simplicial-lemma-godement-two-maps}. We omit the details\footnote{When
$f$ is invertible it suffices to prove that $(a_n) = 1_X$ and
$(b_n) = f^{-1} \star 1_X \star f$ are homotopic.
But this follows from Lemma \ref{simplicial-lemma-godement-two-maps}
because in this case $a = b = 1_{\text{id}_\mathcal{C}}$.}.
\end{proof}

\section{Standard resolutions}
\label{simplicial-section-standard}
Some of the material in this section can be found in
\cite[Appendix 1]{Godement} and \cite[I 1.5]{cotangent}.

\begin{definition}[Situation: Adjoint functors]
\label{simplicial-situation-adjoint-functors}
\source{stacks:08N9}
\href{https://stacks.math.columbia.edu/tag/08N9}{\texttt{Stacks tag 08N9}}
\group{simplicial}

Let $\mathcal{A}$, $\mathcal{S}$ be categories and let
$V : \mathcal{A} \to \mathcal{S}$ be a functor with a left adjoint
$U : \mathcal{S} \to \mathcal{A}$.
\end{definition}

In this very general situation we will construct a simplicial
object $X$ in the category of functors from $\mathcal{A}$ to $\mathcal{A}$.
We suggest looking at the examples presented later on before reading
the text of this section.

\medskip\noindent
For the construction we will use the horizontal composition as
defined in Categories, Section \ref{categories-section-formal-cat-cat}.
The definition of the adjunction morphisms\footnote{We can't use
$\epsilon$ for the counit of the adjunction
because we want to use $\epsilon$ for the
augmentation of our simplicial object.}
$$
d : U \circ V \to \text{id}_\mathcal{A} \quad (\text{counit})
\quad\text{and}\quad
\eta : \text{id}_\mathcal{S} \to V \circ U \quad (\text{unit})
$$
in Categories, Section \ref{categories-section-adjoint}
shows that the compositions
\begin{equation}
\label{equation-composition}
V \xrightarrow{\eta \star 1_V} V \circ U \circ V \xrightarrow{1_V \star d} V
\quad\text{and}\quad
U \xrightarrow{1_U \star \eta} U \circ V \circ U \xrightarrow{d \star 1_U} U
\end{equation}
are the identity morphisms. Here to define the morphism $\eta \star 1_V$ we
silently identify $V$ with $\text{id}_\mathcal{S} \circ V$ and
$1_V$ stands for $\text{id}_V : V \to V$. We will use this notation and
these relations repeatedly in what follows.
For $n \geq 0$ we set
$$
X_n = (U \circ V)^{\circ (n + 1)} =
U \circ V \circ U \circ \ldots \circ U \circ V
$$
In other words, $X_n$ is the $(n + 1)$-fold composition of $U \circ V$
with itself. We also set $X_{-1} = \text{id}_\mathcal{A}$.
We have $X_{n + m + 1} = X_n \circ X_m$ for all $n, m \geq -1$.
We will endow this sequence of functors with the structure of a
simplicial object of $\text{Fun}(\mathcal{A}, \mathcal{A})$ by constructing
the morphisms of functors
$$
d^n_j : X_n \to X_{n - 1},\quad s^n_j : X_n \to X_{n + 1}
$$
satisfying the relations displayed in
Lemma \ref{simplicial-lemma-relations-face-degeneracy}.
Namely, we set
$$
d^n_j = 1_{X_{j - 1}} \star d \star 1_{X_{n - j - 1}}
\quad\text{and}\quad
s^n_j = 1_{X_{j - 1} \circ U} \star \eta \star 1_{V \circ X_{n - j - 1}}
$$
Finally, write $\epsilon_0 = d : X_0 \to X_{-1}$.

\begin{lemma}[Standard simplicial]
\label{simplicial-lemma-standard-simplicial}
\source{stacks:08NC}
\href{https://stacks.math.columbia.edu/tag/08NC}{\texttt{Stacks tag 08NC}}
\group{simplicial}

\uses{simplicial-situation-adjoint-functors}
In Situation \ref{simplicial-situation-adjoint-functors}
the system $X = (X_n, d^n_j, s^n_j)$
is a simplicial object of $\text{Fun}(\mathcal{A}, \mathcal{A})$
and $\epsilon_0$ defines an augmentation $\epsilon$ from $X$
to the constant simplicial object with value $X_{-1} = \text{id}_\mathcal{A}$.
\end{lemma}

\begin{proof}
\uses{simplicial-example-godement, simplicial-lemma-godement}

Consider $Y = U \circ V : \mathcal{A} \to \mathcal{A}$.
We already have the transformation
$d : Y = U \circ V \to \text{id}_\mathcal{A}$. Let us denote
$$
s = 1_U \star \eta \star 1_V :
Y = U \circ \text{id}_\mathcal{S} \circ V
\longrightarrow
U \circ V \circ U \circ V = Y \circ Y
$$
This places us in the situation of Example \ref{simplicial-example-godement}.
It is immediate from the formulas that
the $X, d^n_i, s^n_i$ constructed above and the
$X, s^n_i, s^n_i$ constructed from $Y, d, s$
in Example \ref{simplicial-example-godement} agree. Thus, according to
Lemma \ref{simplicial-lemma-godement} it suffices to prove that
$$
1_Y = (d \star 1_Y) \circ s = (1_Y \star d) \circ s
\quad\text{and}\quad
(s \star 1) \circ s = (1 \star s) \circ s
$$
The first equal sign translates into the equality
$$
1_U \star 1_V = (d \star 1_U \star 1_V) \circ (1_U \star \eta \star 1_V)
$$
which holds if we have $1_U = (d \star 1_U) \circ (1_U \star \eta)$
which in turn holds by (\ref{equation-composition}). Similarly for the
second equal sign. For the last equation we need to prove
$$
(1_U \star \eta \star 1_V \star 1_U \star 1_V) \circ
(1_U \star \eta \star 1_V) =
(1_U \star 1_V \star 1_U \star \eta \star 1_V) \circ
(1_U \star \eta \star 1_V)
$$
For this it suffices to prove
$(\eta \star 1_V \star 1_U) \circ \eta = (1_V \star 1_U \star \eta) \circ \eta$
which is true because both sides are the same as $\eta \star \eta$.
\end{proof}

Before reading the proof of the following lemma, we advise the
reader to look at the example discussed in
Example \ref{simplicial-example-polynomial-algebra-homotopy}
in order to understand the purpose of the lemma.

\begin{lemma}[Standard simplicial homotopy]
\label{simplicial-lemma-standard-simplicial-homotopy}
\source{stacks:08ND}
\href{https://stacks.math.columbia.edu/tag/08ND}{\texttt{Stacks tag 08ND}}
\group{simplicial}

\uses{simplicial-situation-adjoint-functors}
In Situation \ref{simplicial-situation-adjoint-functors} the maps
$$
1_V \star \epsilon : V \circ X \to V,
\quad\text{and}\quad
\epsilon \star 1_U : X \circ U \to U
$$
are homotopy equivalences.
\end{lemma}

\begin{proof}
\uses{simplicial-lemma-standard-simplicial, simplicial-example-godement, simplicial-lemma-godement-section, simplicial-lemma-godement-two-maps}

As in the proof of Lemma \ref{simplicial-lemma-standard-simplicial}
we set $Y = U \circ V$ so that we are
in the situation of Example \ref{simplicial-example-godement}.

\medskip\noindent
Proof of the first homotopy equivalence. By Lemma \ref{simplicial-lemma-godement-section}
to construct a map
$h : V \to V \circ X$ right inverse to $1_V \star \epsilon$ it
suffices to construct a map $h_0 : V \to V \circ Y = V \circ U \circ V$
such that $1_V = (1_V \star d) \circ h_0$. Of course we take
$h_0 = \eta \star 1_V$ and the equality holds by (\ref{equation-composition}).
To finish the proof we need to show the two maps
$$
(1_V \star \epsilon) \circ h, 1_V \star \text{id}_X :
V \circ X \longrightarrow V \circ X
$$
are homotopic. This follows immediately from
Lemma \ref{simplicial-lemma-godement-two-maps} (with
$G = G' = V$ and $F = F' = \text{id}_\mathcal{S}$).

\medskip\noindent
The proof of the second homotopy equivalence. By
Lemma \ref{simplicial-lemma-godement-section} to construct a map
$h : U \to X \circ U$ right inverse to $\epsilon \star 1_U$ it
suffices to construct a map $h_0 : U \to Y \circ U = U \circ V \circ U$
such that $1_U = (d \star 1_U) \circ h_0$. Of course we take
$h_0 = 1_U \star \eta$ and the equality holds by (\ref{equation-composition}).
To finish the proof we need to show the two maps
$$
(\epsilon \star 1_U) \circ h, \text{id}_X \star 1_U :
X \circ U \longrightarrow X \circ U
$$
are homotopic. This follows immediately from
Lemma \ref{simplicial-lemma-godement-two-maps} (with
$G = G' = \text{id}_\mathcal{A}$ and $F = F' = U$).
\end{proof}


\begin{example}[Module]
\label{simplicial-example-module}
\source{stacks:0G5T}
\href{https://stacks.math.columbia.edu/tag/0G5T}{\texttt{Stacks tag 0G5T}}
\group{simplicial}

\uses{simplicial-lemma-trivial-kan-homotopy, simplicial-lemma-homotopy-equivalence, simplicial-lemma-qis-simplicial-abelian-groups}
Let $R$ be a ring. As an example of the above we can take
$i : \text{Mod}_R \to \textit{Sets}$ to be the forgetful functor
and $F : \textit{Sets} \to \text{Mod}_R$ to be the functor that associates
to a set $E$ the free $R$-module $R[E]$ on $E$. For an $R$-module $M$
the simplicial $R$-module $X(M)$ will have the following shape
$$
X(M) =
\left( \ldots
\begin{array}{ccc}R[R[R[M]]]
\longrightarrow\longrightarrow\longrightarrow & R[R[M]]
\longrightarrow\longrightarrow\longleftarrow\longleftarrow & R[M]
\longleftarrow\end{array}
\right)
$$
which comes with an augmentation towards $M$. We will also show this
augmentation is a homotopy equivalence of sets. By Lemmas
\ref{simplicial-lemma-trivial-kan-homotopy}, \ref{simplicial-lemma-homotopy-equivalence}, and
\ref{simplicial-lemma-qis-simplicial-abelian-groups}
this is equivalent to asking $M$ to be the only nonzero cohomology
group of the chain complex associated to the simplicial module $X(M)$.
\end{example}

\begin{example}[Polynomial algebra]
\label{simplicial-example-polynomial-algebra}
\source{stacks:08NA}
\href{https://stacks.math.columbia.edu/tag/08NA}{\texttt{Stacks tag 08NA}}
\group{simplicial}

\uses{simplicial-example-module, simplicial-lemma-trivial-kan-homotopy, simplicial-lemma-homotopy-equivalence, simplicial-lemma-qis-simplicial-abelian-groups}
Let $A$ be a ring. Let $\textit{Alg}_A$ be the category of commutative
$A$-algebras. As an example of the above we can take
$i : \textit{Alg}_A \to \textit{Sets}$ to be the forgetful functor
and $F : \textit{Sets} \to \textit{Alg}_A$ to be the functor that associates
to a set $E$ the polynomial algebra $A[E]$ on $E$ over $A$.
(We apologize for the overlap in notation between this example and
Example \ref{simplicial-example-module}.) For an $A$-algebra $B$
the simplicial $A$-algebra $X(B)$ will have the following shape
$$
X(B) = \left( \ldots
\begin{array}{ccc}A[A[A[B]]]
\longrightarrow\longrightarrow\longrightarrow & A[A[B]]
\longrightarrow\longrightarrow\longleftarrow\longleftarrow & A[B]
\longleftarrow\end{array}
\right)
$$
which comes with an augmentation towards $B$. We will also show this
augmentation is a homotopy equivalence of sets. By Lemmas
\ref{simplicial-lemma-trivial-kan-homotopy}, \ref{simplicial-lemma-homotopy-equivalence}, and
\ref{simplicial-lemma-qis-simplicial-abelian-groups}
this is equivalent to asking $B$ to be the only nonzero cohomology
group of the chain complex of $A$-modules
associated to $X(B)$ viewed as a simplicial $A$-module.
\end{example}

\begin{example}[Module maps]
\label{simplicial-example-module-maps}
\source{stacks:0G5U}
\href{https://stacks.math.columbia.edu/tag/0G5U}{\texttt{Stacks tag 0G5U}}
\group{simplicial}

\uses{simplicial-example-module}
In Example \ref{simplicial-example-module} we have $X_n(M) = R[R[\ldots [M]\ldots]]$
with $n + 1$ brackets. We describe the maps constructed above using a
typical element
$$
\xi = \sum\nolimits_i r_i\left[\sum\nolimits_j r_{ij}[m_{ij}]\right]
$$
of $X_1(M)$. The maps $d_0, d_1 : R[R[M]] \to R[M]$ are given by
$$
d_0(\xi) = \sum\nolimits_{i, j} r_ir_{ij}[m_{ij}]
\quad\text{and}\quad
d_1(\xi) = \sum\nolimits_i r_i\left[\sum\nolimits_j r_{ij}m_{ij}\right].
$$
The maps $s_0, s_1 : R[R[M]] \to R[R[R[M]]]$
are given by
$$
s_0(\xi) =
\sum\nolimits_i r_i\left[\left[\sum\nolimits_j r_{ij}[m_{ij}]\right]\right]
\quad\text{and}\quad
s_1(\xi) = \sum\nolimits_i r_i\left[\sum\nolimits_j r_{ij}[[m_{ij}]]\right].
$$
\end{example}

\begin{example}[Polynomial algebra maps]
\label{simplicial-example-polynomial-algebra-maps}
\source{stacks:09CB}
\href{https://stacks.math.columbia.edu/tag/09CB}{\texttt{Stacks tag 09CB}}
\group{simplicial}

\uses{simplicial-example-polynomial-algebra}
In Example \ref{simplicial-example-polynomial-algebra} we have
$X_n(B) = A[A[\ldots [B]\ldots]]$ with $n + 1$ brackets.
We describe the maps constructed above using a typical element
$$
\xi = \sum\nolimits_i a_i [x_{i, 1}] \ldots [x_{i, m_i}] \in A[A[B]] = X_1(B)
$$
where for each $i, j$ we can write
$$
x_{i, j} = \sum a_{i, j, k} [b_{i, j, k, 1}] \ldots [b_{i, j, k, n_{i, j, k}}]
\in A[B]
$$
Obviously this is horrendous! To ease the notation, to see what the
$A$-algebra maps $d_0, d_1 : A[A[B]] \to A[B]$ are doing it suffices
to see what happens to the variables $[x]$ where
$$
x = \sum a_k [b_{k, 1}] \ldots [b_{k, n_k}] \in A[B]
$$
is a general element. For these we get
$$
d_0([x]) = x = \sum a_k [b_{k, 1}] \ldots [b_{k, n_k}]
\quad\text{and}\quad
d_1([x]) = \left[\sum a_k b_{k, 1} \ldots b_{k, n_k}\right]
$$
The maps $s_0, s_1 : A[A[B]] \to A[A[A[B]]]$ are given by
$$
s_0([x]) = \left[\left[\sum a_k [b_{k, 1}] \ldots [b_{k, n_k}]\right]\right]
\quad\text{and}\quad
s_1([x]) = \left[\sum a_k [[b_{k, 1}]] \ldots [[b_{k, n_k}]]\right]
$$
\end{example}

\begin{example}[Polynomial algebra homotopy]
\label{simplicial-example-polynomial-algebra-homotopy}
\source{stacks:08NE}
\href{https://stacks.math.columbia.edu/tag/08NE}{\texttt{Stacks tag 08NE}}
\group{simplicial}

\uses{simplicial-example-polynomial-algebra, simplicial-lemma-standard-simplicial-homotopy}
Going back to the example discussed in
Example \ref{simplicial-example-polynomial-algebra}
our Lemma \ref{simplicial-lemma-standard-simplicial-homotopy}
signifies that for any ring map $A \to B$ the map of simplicial rings
$$
\begin{array}{ccc}A[A[A[B]]] \downarrow\longrightarrow\longrightarrow\longrightarrow & A[A[B]] \downarrow\longrightarrow\longrightarrow\longleftarrow\longleftarrow & A[B] \downarrow\longleftarrow \\ B
\longrightarrow\longrightarrow\longrightarrow & B
\longrightarrow\longrightarrow\longleftarrow\longleftarrow & B
\longleftarrow\end{array}
$$
is a homotopy equivalence on underlying simplicial sets. Moreover, the inverse
map constructed in Lemma \ref{simplicial-lemma-standard-simplicial-homotopy}
is in degree $n$ given by
$$
b \longmapsto [\ldots[b]\ldots]
$$
with obvious notation. In the other direction the lemma tells us that
for every set $E$ there is a homotopy equivalence
$$
\begin{array}{ccc}A[A[A[A[E]]]] \downarrow\longrightarrow\longrightarrow\longrightarrow & A[A[A[E]]] \downarrow\longrightarrow\longrightarrow\longleftarrow\longleftarrow & A[A[E]] \downarrow\longleftarrow \\ A[E]
\longrightarrow\longrightarrow\longrightarrow & A[E]
\longrightarrow\longrightarrow\longleftarrow\longleftarrow & A[E]
\longleftarrow\end{array}
$$
of rings. The inverse map constructed in the lemma is in degree $n$
given by the ring map
$$
\sum a_{e_1,\ldots,e_p}[e_1][e_2] \ldots [e_p]
\longmapsto
\sum a_{e_1,\ldots,e_p}[\ldots[e_1]\ldots][\ldots[e_2]\ldots]
\ldots [\ldots[e_p]\ldots]
$$
(with obvious notation).
\end{example}
